/* Video embed auto-preview controller (Silent preview on hover, NO fsBtn) */
(function(){
  function getMediaData(thmb) {
    if (!thmb) return null;
    var img = thmb.querySelector('img.thmb, img.imgThm, img');
    var imgSrc = img ? (img.getAttribute('data-src') || img.src || '') : '';
    var postLink = thmb.querySelector('a.thmb, a') || thmb.closest('article')?.querySelector('a[href]');
    var postUrl = postLink ? (postLink.getAttribute('href') || '') : '';

    var videoId = null;
    var isShorts = false;

    var sm = postUrl.match(/shorts\/([a-zA-Z0-9_-]+)/i);
    if (sm) {
      videoId = sm[1];
      isShorts = true;
    } else {
      var ym = imgSrc.match(/\/vi\/([a-zA-Z0-9_-]+)/);
      if (ym) videoId = ym[1];
      if (imgSrc.indexOf('shorts') !== -1 || postUrl.indexOf('shorts') !== -1) isShorts = true;
    }

    return {
      videoId: videoId,
      isShorts: isShorts,
      imgSrc: imgSrc,
      alt: img ? (img.getAttribute('alt') || '') : ''
    };
  }

  function setupThumbnails() {
    // Remove any leftover fsBtn on thumbnails so nothing shows over/behind author negronn
    document.querySelectorAll('.pThmb .fsBtn, .bX .fsBtn, .featuredPost .fsBtn, .PopularPosts .fsBtn').forEach(function(b){ b.remove(); });

    var thumbs = document.querySelectorAll('.pThmb, .shorts .pThmb, .bX .pThmb, .featuredPost .pThmb, .PopularPosts .pThmb');
    thumbs.forEach(function(thmb){
      if (thmb.dataset.ytPreviewInit) return;
      thmb.dataset.ytPreviewInit = '1';

      var data = getMediaData(thmb);
      if (!data || !data.videoId) return;

      var previewIframe = null;
      var hoverTimer = null;

      thmb.addEventListener('mouseenter', function(){
        hoverTimer = setTimeout(function(){
          if (previewIframe || thmb.querySelector('.thmb-preview-frame')) return;
          previewIframe = document.createElement('iframe');
          previewIframe.className = 'thmb-preview-frame';
          var pSrc = 'https://www.youtube.com/embed/' + data.videoId + '?autoplay=1&mute=1&controls=0&loop=1&playlist=' + data.videoId + '&playsinline=1&rel=0&modestbranding=1';
          previewIframe.src = pSrc;
          previewIframe.setAttribute('allow', 'autoplay');
          thmb.appendChild(previewIframe);
        }, 180);
      });

      thmb.addEventListener('mouseleave', function(){
        if (hoverTimer) clearTimeout(hoverTimer);
        if (previewIframe) {
          previewIframe.remove();
          previewIframe = null;
        }
        var oldF = thmb.querySelectorAll('.thmb-preview-frame');
        oldF.forEach(function(f){ f.remove(); });
      });
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', setupThumbnails);
  } else {
    setupThumbnails();
  }
  setInterval(setupThumbnails, 2500);
})();

/* Ticker animation */
(function(){
  var e = document.querySelector(".ticker-items");
  if(e){
    var t = e.querySelectorAll(".ticker-item"), n = t.length, i = 0;
    if(n > 0){
      t[0].classList.add("active");
      var l = function(){ t[i].classList.remove("active"); i = (i + 1) % n; t[i].classList.add("active"); };
      var r = function(){ t[i].classList.remove("active"); i = (i - 1 + n) % n; t[i].classList.add("active"); };
      document.querySelector(".tn-prev") && document.querySelector(".tn-prev").addEventListener("click", function(e){ e.preventDefault(); r(); });
      document.querySelector(".tn-next") && document.querySelector(".tn-next").addEventListener("click", function(e){ e.preventDefault(); l(); });
      var o = setInterval(l, 5000);
      document.querySelector("#ticker-wrapper") && document.querySelector("#ticker-wrapper").addEventListener("mouseenter", function(){ clearInterval(o); });
      document.querySelector("#ticker-wrapper") && document.querySelector("#ticker-wrapper").addEventListener("mouseleave", function(){ o = setInterval(l, 5000); });
    }
  }
})();
