/*--[ Custom JS SingleItem (placed above </body>) ]--*/
(function() {
  "use strict";
  // Blogger Native SVGs
  var BTT_ICONS = {
    chat: '<svg class="line" viewBox="0 0 24 24"><path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z"/></svg>',
    flash: '<svg class="line" viewBox="0 0 24 24"><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/></svg>',
    hierarchy: '<svg class="line" viewBox="0 0 24 24"><rect x="9" y="3" width="6" height="4" rx="1"/><rect x="2" y="17" width="6" height="4" rx="1"/><rect x="16" y="17" width="6" height="4" rx="1"/><path d="M12 7v4m0 0H5v6m7-6h7v6"/></svg>',
    reply: '<svg class="line" viewBox="0 0 24 24"><path d="M10 9V5l-7 7 7 7v-4.1c5 0 8.5 1.6 11 5.1-1-5-4-10-11-11z"/></svg>',
    link: '<svg class="line" viewBox="0 0 24 24"><path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"/><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"/></svg>',
    arrowLeft: '<svg class="line" viewBox="0 0 24 24"><path d="M19 12H5M12 19l-7-7 7-7"/></svg>',
    check: '<svg class="line" viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg>',
    search: '<svg class="line" viewBox="0 0 24 24"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>',
    clock: '<svg class="line" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>',
    user: '<svg class="line" viewBox="0 0 24 24"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>'
  };

  function normTr(str) {
    if (!str) return "";
    return str.toString()
      .replace(/İ/g, "i").replace(/I/g, "i").replace(/ı/g, "i")
      .toLowerCase()
      .replace(/ğ/g, "g").replace(/ü/g, "u").replace(/ş/g, "s")
      .replace(/ö/g, "o").replace(/ç/g, "c")
      .replace(/ı/g, "i")
      .trim();
  }


  // =========================================================================
  // 1. /KOMUT & PLUS UI PARSER
  // =========================================================================
  function cleanUrl(u) {
    if (!u) return "";
    return u.replace(/&amp;/g, "&").trim();
  }

  function isGifUrl(url) {
    if (!url) return false;
    return /\.(gif|webp)(\?.*)?$/i.test(url) || /giphy\.com|tenor\.com|imgur\.com\/.*\.gif/i.test(url);
  }

  function renderGif(url) {
    var cUrl = cleanUrl(url);
    return '<div class="btt-gif-wrap"><span class="btt-gif-badge">GIF</span><img src="' + cUrl + '" class="btt-gif-img" alt="GIF" loading="lazy" onclick="event.stopPropagation();window.open(this.src)"/></div>';
  }

  function renderLinkPill(url, customText) {
    var cUrl = cleanUrl(url);
    var domain = cUrl.replace(/^https?:\/\/(www\.)?/i, "").split("/")[0];
    var label = customText && customText.trim() && customText.trim() !== cUrl ? customText.trim() : domain;
    var fav = "https://www.google.com/s2/favicons?sz=64&domain_url=" + encodeURIComponent(cUrl);
    return '<a href="' + cUrl + '" target="_blank" rel="noopener noreferrer" class="btt-link-pill" onclick="event.stopPropagation()">' +
           '<img src="' + fav + '" class="btt-pill-favicon" alt="" loading="lazy"/>' +
           '<span>' + label + '</span>' +
           '<span class="btt-pill-domain">(' + domain + ')</span>' +
           '</a>';
  }

  function renderMarkdownTable(lines) {
    var html = '<div class="discourse-table-wrap"><table class="discourse-table">';
    lines.forEach(function(line, idx) {
      if (idx === 1 && /^[\|\s\-:]+$/.test(line)) return;
      var cells = line.replace(/^\||\|$/g, "").split("|");
      var tag = idx === 0 ? "th" : "td";
      html += "<tr>";
      cells.forEach(function(c) { html += "<" + tag + ">" + c.trim() + "</" + tag + ">"; });
      html += "</tr>";
    });
    html += "</table></div>";
    return html;
  }

  function decodeWhitelistedPlusUI(str) {
    if (!str || (str.indexOf("&lt;") === -1 && str.indexOf("&#") === -1)) return str;
    var hasPlusUI = /(?:class|id|for|name|data-text|rel)=['"]?(?:tabs|tabT-|tabC-|postTabs|grid|ac|alt|note|alert|spoiler|button|dl|icon|step|tl|showH)/i.test(str);
    if (!hasPlusUI) return str;
    var decoded = str
      .replace(/&lt;/gi, "<")
      .replace(/&gt;/gi, ">")
      .replace(/&quot;/gi, '"')
      .replace(/&#39;|&apos;/gi, "'")
      .replace(/&amp;/gi, "&")
      .replace(/<!--\[[\s\S]*?\]-->/g, "");
    decoded = decoded
      .replace(/<\s*(script|iframe|object|embed|form|meta|link|style|base)\b[^>]*>[\s\S]*?<\s*\/\s*\1\s*>/gi, "")
      .replace(/<\s*(script|iframe|object|embed|form|meta|link|style|base)\b[^>]*\/?>/gi, "")
      .replace(/\bon\w+\s*=\s*(['"][^'"]*['"]|[^\s>]+)/gi, "");
    return decoded;
  }

  window.bttClickPlusTab = function(labelEl, idx, e) {
    var tabsRoot = labelEl && labelEl.closest ? labelEl.closest(".tabs") : null;
    if (!tabsRoot) return;
    var radios = tabsRoot.querySelectorAll("input[type='radio']");
    if (radios && radios[idx]) {
      if (e) {
        e.preventDefault();
        e.stopPropagation();
      }
      radios.forEach(function(r, i) { r.checked = (i === idx); });
      try { radios[idx].dispatchEvent(new Event("change", { bubbles: true })); } catch(err) {}
    }
    var panels = tabsRoot.querySelectorAll("[class*='tabC-']");
    if (panels && panels.length > 0) {
      panels.forEach(function(p, pIdx) {
        p.style.display = (pIdx === idx) ? "block" : "none";
      });
    }
  };

    window.bttSwitchTab = function(btn, panelIdx, e) {
    if (e && typeof e.stopPropagation === "function") e.stopPropagation();
    var tabsWrap = btn.closest(".btt-custom-tabs");
    if (!tabsWrap) return;
    tabsWrap.querySelectorAll(".btt-tab-btn").forEach(function(b, i) {
      b.classList.toggle("active", i === panelIdx);
    });
    tabsWrap.querySelectorAll(".btt-tab-panel").forEach(function(p, i) {
      p.classList.toggle("active", i === panelIdx);
    });
  };

  function parseDiscourseTags(str) {
    if (!str) return "";
    str = str.replace(/^\s*\[KONU:\s*[^\]]+\]\s*(?:<br\s*\/?>|\n)*/i, "");
    str = decodeWhitelistedPlusUI(str);

    // Unwrap Blogger auto-linked <a href="..."> immediately after any /command
    str = str.replace(/(\/(?:url|link|button|btn|download|indir|img|resim|image|gif|audio|ses|video|youtube|yt)\s+)<a\s+[^>]*href=["']([^"']+)["'][^>]*>[\s\S]*?<\/a>/gi, "$1$2");

    var codeBlocks = [];
    function pushCode(html) {
      var token = "%%BTTCODE" + codeBlocks.length + "%%";
      codeBlocks.push(html);
      return token;
    }

    var mediaBlocks = [];
    function pushMedia(html) {
      var token = "%%BTTMEDIA" + mediaBlocks.length + "%%";
      mediaBlocks.push(html);
      return token;
    }

    str = str.replace(/\[code(?:=([a-zA-Z0-9_\-]+))?\]([\s\S]*?)\[\/code\]/gi, function(m, lang, c) {
      return pushCode('<pre class="discourse-code"><code>' + c.trim() + "</code></pre>");
    });
    str = str.replace(/```([a-zA-Z0-9_\-]+)?\n([\s\S]*?)```/gi, function(m, lang, c) {
      return pushCode('<pre class="discourse-code"><code>' + c.trim() + "</code></pre>");
    });
    str = str.replace(/`([^`\n]+)`/g, function(m, c) {
      return pushCode('<code class="inline-code">' + c + "</code>");
    });

    var CMD_LOOKAHEAD = "(?=\\s*\\/(?:guilded|spoiler|spolier|url|link|button|btn|download|indir|demo|h[2-6]|note|not|warning|uyari|alert|bilgi|info|success|basari|error|hata|danger|tip|ipucu|question|soru|details|detay|img|resim|image|gif|audio|ses|video|youtube|yt|code|kod|quote|alinti|mark|vurgu|kbd)\\b|[\\n\\r]|<br|$)";

    // Discord & Guilded ||spoiler|| Syntax
    str = str.replace(/\|\|([\s\S]+?)\|\|/g, function(m, c) {
      return ' <span class="spoiler" title="Görmek için tıkla" onclick="event.stopPropagation();this.classList.toggle(\'revealed\')">' + c.trim() + "</span>";
    });

    // /guilded [url] [başlık] Komutu
    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n|\\s)\\/guilded\\s+(https?:\\/\\/[^\\s<\"'\\)]+)(?:\\s+([\\s\\S]+?))?" + CMD_LOOKAHEAD, "gi"), function(m, url, label) {
      var cUrl = cleanUrl(url);
      var inviteMatch = cUrl.match(/guilded\.gg\/(?:i\/|teams\/|groups\/[^\/]+\/channels\/[^\/]+\/)?([a-zA-Z0-9_-]+)/i);
      var gName = label ? label.trim() : (inviteMatch ? ('Guilded #' + inviteMatch[1]) : 'Guilded Topluluğu');
      return " " + pushMedia(
        '<div class="guilded-comment-card" onclick="event.stopPropagation()">' +
          '<div class="gcc-badge-row">' +
            '<svg viewBox="0 0 24 24" class="gcc-logo"><path fill="#F5C400" d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1.88 15.25h-3.76v-2.07h3.76v2.07zm2.47-5.59c-.48.6-1.18.96-1.95 1.05v.06c.86.13 1.58.55 2.05 1.2.47.65.68 1.48.59 2.33-.13 1.25-.85 2.32-1.96 2.91-1.01.54-2.22.69-3.41.69H7.5V6.75h4.14c1.19 0 2.4.15 3.41.69 1.11.59 1.83 1.66 1.96 2.91.09.85-.12 1.68-.59 2.33-.04.05-.08.09-.12.13-.03.03-.03.07 0 .1.46.34.84.82 1.07 1.37.11.26.18.53.22.82-.09-.85-.3-1.68-.77-2.33-.47-.65-1.19-1.07-2.05-1.2v-.06c.77-.09 1.47-.45 1.95-1.05.47-.6.68-1.36.59-2.14-.13-1.15-.81-2.13-1.83-2.67-.93-.49-2.04-.63-3.14-.63H7.5v1.88h3.81c.88 0 1.77.11 2.51.5.73.39 1.22 1.09 1.31 1.91.06.52-.08 1.03-.39 1.43-.31.4-.78.64-1.29.7-.22.03-.45.04-.68.04h-1.5v1.88h1.5c.23 0 .46.01.68.04.51.06.98.3 1.29.7.31.4.45.91.39 1.43-.09.82-.58 1.52-1.31 1.91-.74.39-1.63.5-2.51.5H7.5v1.88h4.14c1.1 0 2.21-.14 3.14-.63 1.02-.54 1.7-1.52 1.83-2.67.09-.78-.12-1.54-.59-2.14z"/></svg>' +
            '<span class="gcc-brand">Guilded</span>' +
          '</div>' +
          '<div class="gcc-title">' + gName + '</div>' +
          '<a href="' + cUrl + '" target="_blank" rel="nofollow noopener noreferrer" class="gcc-join-btn">Guilded\'da Katıl ve Sohbet Et</a>' +
        '</div>'
      );
    });

    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n|\\s)\\/(?:spoiler|spolier)\\s+([\\s\\S]+?)" + CMD_LOOKAHEAD, "gi"), function(m, c) {
      return ' <span class="spoiler" title="Görmek için tıkla" onclick="event.stopPropagation();this.classList.toggle(\'revealed\')">' + c.trim() + "</span>";
    });
    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n)\\s*\\/h([2-6])\\s+([\\s\\S]+?)" + CMD_LOOKAHEAD, "gi"), function(m, lvl, c) {
      return "<h" + lvl + ' class="btt-heading btt-h' + lvl + '">' + c.trim() + "</h" + lvl + ">";
    });
    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n)\\s*\\/(?:note|not)\\s+([\\s\\S]+?)" + CMD_LOOKAHEAD, "gi"), function(m, c) {
      return '<p class="note"><b>Not:</b><br/>' + c.trim() + "</p>";
    });
    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n|\\s)\\s*\\/(?:warning|uyari)\\s+([\\s\\S]+?)" + CMD_LOOKAHEAD, "gi"), function(m, c) {
      return '<div class="alert warning"><b>Uyarı!</b> ' + c.trim() + "</div>";
    });
    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n|\\s)\\s*\\/(?:alert|bilgi|info)\\s+([\\s\\S]+?)" + CMD_LOOKAHEAD, "gi"), function(m, c) {
      return '<div class="alert info"><b>Bilgi!</b> ' + c.trim() + "</div>";
    });
    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n|\\s)\\s*\\/(?:success|basari)\\s+([\\s\\S]+?)" + CMD_LOOKAHEAD, "gi"), function(m, c) {
      return '<div class="alert success"><b>Başarılı!</b> ' + c.trim() + "</div>";
    });
    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n|\\s)\\s*\\/(?:error|hata|danger)\\s+([\\s\\S]+?)" + CMD_LOOKAHEAD, "gi"), function(m, c) {
      return '<div class="alert error"><b>Hata!</b> ' + c.trim() + "</div>";
    });
    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n|\\s)\\s*\\/(?:tip|ipucu)\\s+([\\s\\S]+?)" + CMD_LOOKAHEAD, "gi"), function(m, c) {
      return '<div class="alert tip"><b>İpucu!</b> ' + c.trim() + "</div>";
    });
    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n|\\s)\\s*\\/(?:question|soru)\\s+([\\s\\S]+?)" + CMD_LOOKAHEAD, "gi"), function(m, c) {
      return '<p class="note qs"><b>Soru:</b><br/>' + c.trim() + "</p>";
    });
    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n)\\s*\\/(?:details|detay)\\s+([^|\\n<]+)(?:\\|\\s*([\\s\\S]+?))?" + CMD_LOOKAHEAD, "gi"), function(m, title, content) {
      return '<details class="ac" onclick="event.stopPropagation()"><summary>' + title.trim() + "</summary><div><p>" + (content ? content.trim() : "") + "</p></div></details>";
    });


    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n|\\s)\\/(?:download|indir)\\s+(https?:\\/\\/[^\\s<\"'\\)]+)(?:\\s+([\\s\\S]+?))?" + CMD_LOOKAHEAD, "gi"), function(m, url, label) {
      return " " + pushMedia('<a class="button" href="' + cleanUrl(url) + '" target="_blank" rel="nofollow noreferrer noopener" onclick="event.stopPropagation()"><i class="icon dl"></i>' + (label ? label.trim() : "Dosyayı İndir") + "</a>");
    });
    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n|\\s)\\/(?:button|btn)\\s+(https?:\\/\\/[^\\s<\"'\\)]+)(?:\\s+([\\s\\S]+?))?" + CMD_LOOKAHEAD, "gi"), function(m, url, label) {
      return " " + pushMedia('<a class="button" href="' + cleanUrl(url) + '" target="_blank" rel="nofollow noreferrer noopener" onclick="event.stopPropagation()">' + (label ? label.trim() : "Bağlantı") + "</a>");
    });
    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n|\\s)\\/(?:url|link)\\s+(https?:\\/\\/[^\\s<\"'\\)]+)(?:\\s+([\\s\\S]+?))?" + CMD_LOOKAHEAD, "gi"), function(m, url, label) {
      var cUrl = cleanUrl(url);
      if (isGifUrl(cUrl)) return " " + pushMedia(renderGif(cUrl));
      return " " + pushMedia(renderLinkPill(cUrl, label ? label.trim() : null));
    });
    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n|\\s)\\/(?:img|resim|image)\\s+(https?:\\/\\/[^\\s<\"'\\)]+)", "gi"), function(m, url) {
      var cUrl = cleanUrl(url);
      if (isGifUrl(cUrl)) return " " + pushMedia(renderGif(cUrl));
      return pushMedia('<div class="discourse-img-box"><img src="' + cUrl + '" alt="Görsel" loading="lazy" onclick="event.stopPropagation();window.open(this.src)"/></div>');
    });
    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n|\\s)\\/gif\\s+(https?:\\/\\/[^\\s<\"'\\)]+)", "gi"), function(m, url) {
      return " " + pushMedia(renderGif(cleanUrl(url)));
    });
    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n|\\s)\\/(?:audio|ses)\\s+(https?:\\/\\/[^\\s<\"'\\)]+)", "gi"), function(m, url) {
      return pushMedia('<audio controls preload="metadata" style="width:100%;margin:8px 0;" onclick="event.stopPropagation()"><source src="' + cleanUrl(url) + '" type="audio/mpeg"></audio>');
    });
    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n|\\s)\\/video\\s+(https?:\\/\\/[^\\s<\"'\\)]+)", "gi"), function(m, url) {
      return pushMedia('<video controls preload="metadata" playsinline style="max-width:100%;border-radius:8px;margin:8px 0;" onclick="event.stopPropagation()"><source src="' + cleanUrl(url) + '" type="video/mp4"></video>');
    });
    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n|\\s)\\/(?:youtube|yt)\\s+(https?:\\/\\/[^\\s<\"'\\)]+|[a-zA-Z0-9_\\-]+)", "gi"), function(m, val) {
      var id = cleanUrl(val);
      var match = id.match(/(?:youtu\.be\/|v=|\/embed\/|\/shorts\/)([a-zA-Z0-9_\-]+)/);
      if (match) id = match[1];
      return pushMedia('<div class="discourse-video-wrap" style="position:relative;padding-bottom:56.25%;height:0;overflow:hidden;border-radius:8px;margin:8px 0;"><iframe src="https://www.youtube.com/embed/' + id + '" style="position:absolute;top:0;left:0;width:100%;height:100%;border:0;" allowfullscreen=""></iframe></div>');
    });
    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n)\\s*\\/(?:code|kod)\\s+([\\s\\S]+?)" + CMD_LOOKAHEAD, "gi"), function(m, c) {
      return pushCode('<pre class="discourse-code"><code>' + c.trim() + "</code></pre>");
    });
    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n)\\s*\\/(?:quote|alinti)\\s+([\\s\\S]+?)" + CMD_LOOKAHEAD, "gi"), function(m, c) {
      return '<div class="discourse-quote"><div class="quote-header">Alıntı:</div><div class="quote-content">' + c.trim() + "</div></div>";
    });
    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n|\\s)\\/(?:mark|vurgu)\\s+([\\s\\S]+?)" + CMD_LOOKAHEAD, "gi"), " <mark>$1</mark>");
    str = str.replace(new RegExp("(?:^|<br\\s*\\/?>|\\n|\\s)\\/kbd\\s+([\\s\\S]+?)" + CMD_LOOKAHEAD, "gi"), " <kbd>$1</kbd>");

    str = str.replace(/<i\s+rel=['"]image['"]>([\s\S]*?)<\/i>/gi, function(m, url) {
      var cUrl = cleanUrl(url);
      if (isGifUrl(cUrl)) return pushMedia(renderGif(cUrl));
      return pushMedia('<div class="discourse-img-box"><img src="' + cUrl + '" alt="Görsel" loading="lazy" onclick="event.stopPropagation();window.open(this.src)"/></div>');
    });
    str = str.replace(/<i\s+rel=['"]spoiler['"]>([\s\S]*?)<\/i>/gi, '<span class="spoiler" title="Görmek için tıkla" onclick="event.stopPropagation();this.classList.toggle(\'revealed\')">$1</span>');
    str = str.replace(/<i\s+rel=['"]tag['"]>([\s\S]*?)<\/i>/gi, function(m, u) {
      var cleanU = u.replace(/^@/, "").trim();
      return pushMedia('<span class="btt-reply-parent-ref" onclick="event.stopPropagation();window.bttFindAndScrollToAuthor(\'' + cleanU + '\')">↩️ @' + cleanU + "</span>");
    });

    // Existing <a> tags from Blogger
    str = str.replace(/<a\s+[^>]*href=["'](https?:\/\/[^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi, function(m, url, text) {
      if (m.indexOf('class="button"') !== -1 || m.indexOf("class='button'") !== -1 || m.indexOf('class="extL"') !== -1) {
        return pushMedia(m);
      }
      var cUrl = cleanUrl(url);
      if (isGifUrl(cUrl)) return pushMedia(renderGif(cUrl));
      return pushMedia(renderLinkPill(cUrl, text.replace(/<[^>]+>/g, "").trim() || null));
    });

    // Bare URLs
    str = str.replace(/(^|[^"'>=\/])(https?:\/\/[^\s<"'\)]+)/gi, function(m, prefix, url) {
      var cUrl = cleanUrl(url);
      if (isGifUrl(cUrl)) return prefix + pushMedia(renderGif(cUrl));
      return prefix + pushMedia(renderLinkPill(cUrl, null));
    });

    // Markdown Tables
    if (str.indexOf("|") !== -1) {
      var lines = str.split(/<br\s*\/?>|\n/);
      var tableLines = [], inTable = false, newLines = [];
      for (var i = 0; i < lines.length; i++) {
        var trimmed = lines[i].trim();
        if (trimmed.indexOf("|") === 0 && trimmed.lastIndexOf("|") === trimmed.length - 1) {
          inTable = true;
          tableLines.push(trimmed);
        } else {
          if (inTable && tableLines.length >= 3) newLines.push(renderMarkdownTable(tableLines));
          else if (inTable) newLines = newLines.concat(tableLines);
          tableLines = [];
          inTable = false;
          newLines.push(lines[i]);
        }
      }
      if (inTable && tableLines.length >= 3) newLines.push(renderMarkdownTable(tableLines));
      else if (inTable) newLines = newLines.concat(tableLines);
      str = newLines.join("<br/>");
    }

    // Mentions
    str = str.replace(/(?:↩️\s*)?@([a-zA-Z0-9_ğüşıöçĞÜŞİÖÇ]+)(?:\s*kişisine\s*yanıt)?/g, function(m, u) {
      return '<span class="btt-reply-parent-ref" onclick="event.stopPropagation();window.bttFindAndScrollToAuthor(\'' + u + '\')">↩️ @' + u + "</span>";
    });

    for (var mIdx = 0; mIdx < mediaBlocks.length; mIdx++) {
      str = str.replace("%%BTTMEDIA" + mIdx + "%%", mediaBlocks[mIdx]);
    }
    for (var k = 0; k < codeBlocks.length; k++) {
      str = str.replace("%%BTTCODE" + k + "%%", codeBlocks[k]);
    }
    return str;
  }

  // =========================================================================
  // 2. CLIPBOARD, LAZY AVATAR HYDRATION & LINK HELPERS
  // =========================================================================
  function safeCopy(text) {
    if (typeof navigator !== "undefined" && navigator.clipboard && navigator.clipboard.writeText) {
      return navigator.clipboard.writeText(text).catch(function() { fallbackCopy(text); });
    }
    fallbackCopy(text);
    return Promise.resolve();
  }

  function fallbackCopy(text) {
    if (typeof document === "undefined") return;
    var ta = document.createElement("textarea");
    ta.value = text;
    ta.style.position = "fixed";
    ta.style.left = "-9999px";
    document.body.appendChild(ta);
    ta.focus();
    ta.select();
    try { document.execCommand("copy"); } catch (e) {}
    document.body.removeChild(ta);
  }

    window.bttFallbackAv = function(name) {
    return getFallbackAvatarSvg(name);
  };

  function getFallbackAvatarSvg(name) {
    var cleanName = (name || "").trim();
    var isAnonymous = !cleanName || cleanName.toLowerCase() === "anonymous" || cleanName.toLowerCase() === "adsız" || cleanName.toLowerCase() === "adsiz" || cleanName.toLowerCase() === "misafir" || cleanName.toLowerCase() === "ziyaretçi";

    var palettes = [
      ["#0284c7", "#0369a1"],
      ["#6366f1", "#4f46e5"],
      ["#059669", "#047857"],
      ["#d97706", "#b45309"],
      ["#8b5cf6", "#7c3aed"],
      ["#0891b2", "#0e7490"],
      ["#e11d48", "#be123c"]
    ];

    if (isAnonymous) {
      return 'data:image/svg+xml;utf8,' + encodeURIComponent(
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40" width="40" height="40">' +
          '<defs><linearGradient id="anonGrad" x1="0" y1="0" x2="1" y2="1">' +
            '<stop offset="0%" stop-color="#2d2d30"/>' +
            '<stop offset="100%" stop-color="#1e1e1e"/>' +
          '</linearGradient></defs>' +
          '<rect width="40" height="40" rx="20" fill="url(#anonGrad)"/>' +
          '<path d="M20 20c2.76 0 5-2.24 5-5s-2.24-5-5-5-5 2.24-5 5 2.24 5 5 5zm0 2.5c-3.33 0-10 1.67-10 5v2.5h20v-2.5c0-3.33-6.67-5-10-5z" fill="#9ca3af"/>' +
        '</svg>'
      );
    }

    var hash = 0;
    for (var i = 0; i < cleanName.length; i++) hash = cleanName.charCodeAt(i) + ((hash << 5) - hash);
    var c = palettes[Math.abs(hash) % palettes.length];
    var gid = "avG" + Math.abs(hash);
    var initial = cleanName.charAt(0).toLocaleUpperCase("tr-TR") || "U";

    return 'data:image/svg+xml;utf8,' + encodeURIComponent(
      '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40" width="40" height="40">' +
        '<defs><linearGradient id="' + gid + '" x1="0" y1="0" x2="1" y2="1">' +
          '<stop offset="0%" stop-color="' + c[0] + '"/>' +
          '<stop offset="100%" stop-color="' + c[1] + '"/>' +
        '</linearGradient></defs>' +
        '<rect width="40" height="40" rx="20" fill="url(#' + gid + ')"/>' +
        '<text x="20" y="25" text-anchor="middle" fill="#ffffff" font-family="-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,sans-serif" font-size="16" font-weight="700">' + initial + '</text>' +
      '</svg>'
    );
  }

  function upgradeAvatarUrl(url) {
    if (!url || url.indexOf("blank.gif") !== -1 || url.indexOf("data:image") !== -1) return url;
    var u = url.replace(/\/(?:s|w)\d+(?:-h\d+)?(?:-[a-z0-9-]+)?\//i, "/s240-c/");
    u = u.replace(/=(?:s|w)\d+(?:-h\d+)?(?:-[a-z0-9-]+)?(?=$|[&#])/i, "=s240-c");
    return u;
  }

  function hydrateLazyAvatars() {
    var lis = document.querySelectorAll("#cmHolder li.c");
    lis.forEach(function(li) {
      var authorName = (li.getAttribute("data-author-name") || "Misafir").trim();
      var highRes = li.getAttribute("data-author-image");
      var avWrap = li.querySelector(".cmAv");
      if (!avWrap) return;
      var img = avWrap.querySelector("img");

      var hasRealPhoto = false;
      var ds = highRes || (img ? (img.getAttribute("data-src") || img.getAttribute("src")) : "");
      if (ds && ds.indexOf("blank.gif") === -1 && ds.indexOf("b16-rounded") === -1 && ds.indexOf("data:image") === -1) {
        var crisp = upgradeAvatarUrl(ds);
        if (img) {
          if (img.getAttribute("src") !== crisp) img.setAttribute("src", crisp);
          img.removeAttribute("data-src");
          img.classList.remove("lazyload");
          img.classList.add("lazyloaded");
          img.style.opacity = "1";
          img.style.display = "block";
          img.style.visibility = "visible";
          img.onerror = function() {
            img.onerror = null;
            img.src = getFallbackAvatarSvg(authorName);
          };
          hasRealPhoto = true;
        } else {
          var imDiv = avWrap.querySelector(".im");
          var targetParent = imDiv || avWrap;
          if (imDiv) imDiv.classList.add("has-img");
          targetParent.innerHTML = '<img class="lazyloaded" src="' + crisp + '" alt="' + authorName.replace(/"/g, '&quot;') + '" style="width:100%;height:100%;border-radius:50%;display:block;opacity:1;visibility:visible;object-fit:cover;" onerror="this.onerror=null;this.src=window.bttFallbackAv(this.alt);"/>';
          hasRealPhoto = true;
        }
      }

      if (!hasRealPhoto) {
        var fallbackSvg = getFallbackAvatarSvg(authorName);
        if (img) {
          img.src = fallbackSvg;
          img.removeAttribute("data-src");
          img.classList.remove("lazyload");
          img.classList.add("lazyloaded");
          img.style.opacity = "1";
          img.style.display = "block";
          img.style.visibility = "visible";
        } else {
          var imDiv = avWrap.querySelector(".im");
          var targetParent = imDiv || avWrap;
          if (imDiv) imDiv.classList.add("has-img");
          targetParent.innerHTML = '<img class="lazyloaded" src="' + fallbackSvg + '" alt="' + authorName.replace(/"/g, '&quot;') + '" style="width:100%;height:100%;border-radius:50%;display:block;opacity:1;visibility:visible;object-fit:cover;"/>';
        }
      }
    });
  }


  // =========================================================================
  // GUILDED.GG MESSENGER ENGINE (REACTIONS, HOVER ACTIONS, ROLES, CHANNELS)
  // =========================================================================
  var BTT_AUDIO_CTX = null;
  window.bttPlayPopSound = function() {
    try {
      if (!BTT_AUDIO_CTX) {
        var AC = window.AudioContext || window.webkitAudioContext;
        if (AC) BTT_AUDIO_CTX = new AC();
      }
      if (BTT_AUDIO_CTX && BTT_AUDIO_CTX.state === "suspended") {
        BTT_AUDIO_CTX.resume();
      }
      if (BTT_AUDIO_CTX) {
        var osc = BTT_AUDIO_CTX.createOscillator();
        var gain = BTT_AUDIO_CTX.createGain();
        osc.type = "sine";
        osc.frequency.setValueAtTime(540, BTT_AUDIO_CTX.currentTime);
        osc.frequency.exponentialRampToValueAtTime(880, BTT_AUDIO_CTX.currentTime + 0.08);
        gain.gain.setValueAtTime(0.08, BTT_AUDIO_CTX.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, BTT_AUDIO_CTX.currentTime + 0.08);
        osc.connect(gain);
        gain.connect(BTT_AUDIO_CTX.destination);
        osc.start();
        osc.stop(BTT_AUDIO_CTX.currentTime + 0.08);
      }
    } catch(e) {}
  };

  // Reactions Storage Helper
  function getReactionsStore() {
    try {
      var k = "btt_guilded_reactions_" + (window.location.pathname || "root");
      return JSON.parse(localStorage.getItem(k) || "{}");
    } catch(e) {
      return {};
    }
  }

  function setReactionsStore(store) {
    try {
      var k = "btt_guilded_reactions_" + (window.location.pathname || "root");
      localStorage.setItem(k, JSON.stringify(store));
    } catch(e) {}
  }

  window.bttToggleReaction = function(msgId, emoji, btnEl) {
    var store = getReactionsStore();
    if (!store[msgId]) store[msgId] = {};
    var count = store[msgId][emoji] || 0;
    var userKey = "user_reacted_" + emoji;
    var hasReacted = !!store[msgId][userKey];

    if (hasReacted) {
      count = Math.max(0, count - 1);
      delete store[msgId][userKey];
    } else {
      count += 1;
      store[msgId][userKey] = true;
      window.bttPlayPopSound();
    }
    if (count > 0) {
      store[msgId][emoji] = count;
    } else {
      delete store[msgId][emoji];
    }
    setReactionsStore(store);
    window.bttRenderReactions(msgId);
  };

  window.bttRenderReactions = function(msgId) {
    var container = document.getElementById("reactions-" + msgId);
    if (!container) return;
    var store = getReactionsStore();
    var msgReactions = store[msgId] || {};

    var defaultEmojis = ["👍", "🔥", "❤️"];
    var html = "";

    // Render active or default reactions
    var renderedEmojis = new Set();
    Object.keys(msgReactions).forEach(function(k) {
      if (k.indexOf("user_reacted_") === 0) return;
      var count = msgReactions[k];
      if (count > 0) {
        renderedEmojis.add(k);
        var isUser = !!msgReactions["user_reacted_" + k];
        html += '<button type="button" class="btt-reaction-btn' + (isUser ? ' active' : '') + '" onclick="window.bttToggleReaction(\'" + msgId + "\', \'" + k + "\', this)" title="' + k + ' tepkisini ver/kaldır">' +
                '<span class="r-emoji">' + k + '</span> <span class="r-count">' + count + '</span>' +
                '</button>';
      }
    });

    // If none active, show default unreacted starter buttons
    if (html === "") {
      defaultEmojis.forEach(function(em) {
        html += '<button type="button" class="btt-reaction-btn" onclick="window.bttToggleReaction(\'" + msgId + "\', \'" + em + "\', this)" title="' + em + ' tepkisi ver">' +
                '<span class="r-emoji">' + em + '</span>' +
                '</button>';
      });
    }

    html += '<button type="button" class="btt-reaction-add" title="Tepki Ekle" onclick="window.bttOpenReactionPicker(\'" + msgId + "\', this, event)">' +
            '<svg viewBox="0 0 24 24" style="width:14px;height:14px;stroke:currentColor;stroke-width:2;fill:none;"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>' +
            '</button>';

    container.innerHTML = html;
  };

  window.bttOpenReactionPicker = function(msgId, triggerEl, e) {
    if (e) { e.preventDefault(); e.stopPropagation(); }
    document.querySelectorAll(".btt-reaction-popover").forEach(function(p) { p.remove(); });

    var pop = document.createElement("div");
    pop.className = "btt-reaction-popover";
    var emojis = ["👍", "❤️", "🔥", "😂", "🎉", "🚀", "👀", "💯", "⭐", "💬"];
    var popHtml = "";
    emojis.forEach(function(em) {
      popHtml += '<span class="g-pop-emoji" onclick="window.bttToggleReaction(\'" + msgId + "\', \'" + em + "\'); this.parentNode.remove();">' + em + '</span>';
    });
    pop.innerHTML = popHtml;

    document.body.appendChild(pop);
    var rect = triggerEl.getBoundingClientRect();
    pop.style.top = (rect.bottom + window.scrollY + 6) + "px";
    pop.style.left = Math.max(10, (rect.left + window.scrollX - 40)) + "px";

    function closePop(ev) {
      if (!pop.contains(ev.target) && ev.target !== triggerEl) {
        pop.remove();
        document.removeEventListener("click", closePop);
      }
    }
    setTimeout(function() { document.addEventListener("click", closePop); }, 50);
  };

  // Quote message into composer
  window.bttQuoteMessage = function(commentId, e) {
    if (e) { e.preventDefault(); e.stopPropagation(); }
    var rawId = String(commentId).replace(/^c/, "");
    var targetLi = document.getElementById("c" + rawId) || document.getElementById(commentId);
    if (!targetLi) return;
    var author = (targetLi.getAttribute("data-author-name") || "Kullanıcı").trim();
    var co = targetLi.querySelector(".cmCo");
    var txt = co ? (co.getAttribute("data-raw-text") || co.textContent || "").trim() : "";
    if (txt.length > 90) txt = txt.substring(0, 90) + "…";

    window.bttNativeReply(commentId, e);
    var ed = document.getElementById("comment-editor");
    if (ed) {
      safeCopy("> @" + author + ': "' + txt + '"\n\n');
      var hdr = document.querySelector(".btt-composer-header .btt-composer-title");
      if (hdr) {
        var origText = hdr.innerHTML;
        hdr.innerHTML = "Alıntı Panoya Kopyalandı! 📋 (Yapıştırın: Ctrl+V)";
        setTimeout(function() { hdr.innerHTML = origText; }, 2600);
      }
    }
  };

  // Channels Bar Filtering
  window.bttFilterChannel = function(chan, btnEl) {
    if (btnEl && btnEl.parentNode) {
      btnEl.parentNode.querySelectorAll(".g-chan-pill").forEach(function(b) { b.classList.remove("active"); });
      btnEl.classList.add("active");
    }
    var holder = document.getElementById("cmHolder");
    if (!holder) return;
    var roots = Array.prototype.slice.call(holder.children).filter(function(el) {
      return el.tagName === "LI" && el.classList.contains("c");
    });

    if (chan === "all") {
      roots.forEach(function(r) { r.style.display = ""; });
      return;
    }

    var kw = chan.toLowerCase();
    roots.forEach(function(r) {
      var text = (r.textContent || "").toLowerCase();
      if (text.indexOf("#" + kw) !== -1 || text.indexOf(kw) !== -1) {
        r.style.display = "";
      } else {
        r.style.display = "none";
      }
    });
  };

  // Ensure Channels Bar in Comments
  function ensureGuildedChannelsBar() {
    var bar = document.getElementById("guildedChannelsBar");
    if (bar && bar.parentNode) bar.parentNode.removeChild(bar);
  }

  window.bttCopyLink = function(msgId, btn, e) {
    if (e) {
      e.preventDefault();
      e.stopPropagation();
    }
    var url = window.location.origin + window.location.pathname + "#topic-" + msgId;
    safeCopy(url);
    if (btn) {
      var orig = btn.getAttribute("data-orig") || btn.innerHTML;
      btn.setAttribute("data-orig", orig);
      btn.innerHTML = "Kopyalandı";
      setTimeout(function() { btn.innerHTML = orig; }, 1400);
    }
  };

  window.bttScrollAndFlash = function(id, e) {
    if (e) {
      if (typeof e.preventDefault === "function") e.preventDefault();
      if (typeof e.stopPropagation === "function") e.stopPropagation();
    }
    var targetId = String(id).replace(/^c/, "");
    var el = document.getElementById("c" + targetId) || document.getElementById(id);
    if (!el) {
      el = document.querySelector('[data-comment-id="' + targetId + '"]') || document.querySelector('[id*="' + targetId + '"]');
    }
    if (!el) return;

    var rootLi = el.closest("#cmHolder > li.c") || el;
    var holder = document.getElementById("cmHolder");
    if (holder && !holder.classList.contains("btt-in-topic-view")) {
      window.bttOpenTopicPage(rootLi.id, el.id);
      return;
    }

    var directBd = el.querySelector(":scope > .cmIn > .cmBd") || el.querySelector(".cmBd");
    if (!directBd) return;

    directBd.scrollIntoView({ behavior: "smooth", block: "center" });

    document.querySelectorAll("#cmHolder .btt-target-highlight").forEach(function(m) {
      m.classList.remove("btt-target-highlight");
    });
    document.querySelectorAll("#cmHolder li.c.btt-active-msg").forEach(function(m) {
      m.classList.remove("btt-active-msg");
    });

    directBd.classList.remove("btt-target-highlight");
    void directBd.offsetWidth;
    directBd.classList.add("btt-target-highlight");

    setTimeout(function() {
      directBd.classList.remove("btt-target-highlight");
    }, 3200);
  };

  // =========================================================================
  // 1. DETERMINISTIC BLOGGER COMMENT COMPOSER & IFRAME ENGINE
  // =========================================================================
  var cachedBaseThreadUrl = "";

  function getBaseThreadUrl() {
    if (cachedBaseThreadUrl) return cachedBaseThreadUrl;

    var ed = document.getElementById("comment-editor");
    var iCmn = document.getElementById("iCmn");
    var anyThreadEl = document.querySelector("[data-thread]");

    var url = "";
    if (iCmn) url = iCmn.getAttribute("data-thread") || "";
    if (!url && ed) url = ed.getAttribute("data-thread") || ed.getAttribute("data-src") || ed.src || "";
    if (!url && anyThreadEl) url = anyThreadEl.getAttribute("data-thread") || "";

    if (!url) {
      var isPage = (window.location.pathname.indexOf("/p/") !== -1) || (document.body && document.body.classList.contains("onPg"));
      var blogId = "";
      var itemId = "";
      var html = document.documentElement ? document.documentElement.innerHTML : "";
      var mBlog = html.match(/blogId['":\s]+(\d+)/i) || html.match(/feeds\/(\d+)\/posts/i) || html.match(/followers\/follow\/(\d+)/i);
      if (mBlog) blogId = mBlog[1];
      var mItem = isPage
        ? (html.match(/pageId['":\s]+(\d+)/i) || html.match(/\/pages\/default\/(\d+)/i))
        : (html.match(/postId['":\s]+(\d+)/i) || html.match(/\/posts\/default\/(\d+)/i));
      if (mItem) itemId = mItem[1];

      var orig = window.location.origin || ("https://" + window.location.hostname);
      var paramName = isPage ? "pa" : "po";
      if (blogId && itemId) {
        url = "https://www.blogger.com/comment/frame/" + blogId + "?" + paramName + "=" + itemId + "&hl=tr&origin=" + encodeURIComponent(orig) + "&skin=contempo";
      } else {
        var defBlog = orig.indexOf("aleyulala") !== -1 ? "560859626649677709" : "1915278968279215939";
        var defItem = orig.indexOf("aleyulala") !== -1 ? (isPage ? "1083332573935075987" : "4337311298790360591") : (isPage ? "6836001094147118188" : "5871903855103380275");
        url = "https://www.blogger.com/comment/frame/" + defBlog + "?" + paramName + "=" + defItem + "&hl=tr&origin=" + encodeURIComponent(orig) + "&skin=contempo";
      }
    }

    cachedBaseThreadUrl = url.replace(/&parentID=\d+/g, "");
    return cachedBaseThreadUrl;
  }

  var cachedBaseThreadUrl = "";

  function getBaseThreadUrl() {
    if (cachedBaseThreadUrl) return cachedBaseThreadUrl;

    var ed = document.getElementById("comment-editor");
    var iCmn = document.getElementById("iCmn");
    var anyThreadEl = document.querySelector("[data-thread]");

    var url = "";
    if (iCmn) url = iCmn.getAttribute("data-thread") || "";
    if (!url && ed) url = ed.getAttribute("data-thread") || ed.getAttribute("data-src") || ed.src || "";
    if (!url && anyThreadEl) url = anyThreadEl.getAttribute("data-thread") || "";

    if (!url) {
      var isPage = (window.location.pathname.indexOf("/p/") !== -1) || (document.body && document.body.classList.contains("onPg"));
      var blogId = "";
      var itemId = "";
      var html = document.documentElement ? document.documentElement.innerHTML : "";
      var mBlog = html.match(/blogId['":\s]+(\d+)/i) || html.match(/feeds\/(\d+)\/posts/i) || html.match(/followers\/follow\/(\d+)/i);
      if (mBlog) blogId = mBlog[1];
      var mItem = isPage
        ? (html.match(/pageId['":\s]+(\d+)/i) || html.match(/\/pages\/default\/(\d+)/i))
        : (html.match(/postId['":\s]+(\d+)/i) || html.match(/\/posts\/default\/(\d+)/i));
      if (mItem) itemId = mItem[1];

      var orig = window.location.origin || ("https://" + window.location.hostname);
      var paramName = isPage ? "pa" : "po";
      if (blogId && itemId) {
        url = "https://www.blogger.com/comment/frame/" + blogId + "?" + paramName + "=" + itemId + "&hl=tr&origin=" + encodeURIComponent(orig) + "&skin=contempo";
      } else {
        var defBlog = orig.indexOf("aleyulala") !== -1 ? "560859626649677709" : "1915278968279215939";
        var defItem = orig.indexOf("aleyulala") !== -1 ? (isPage ? "1083332573935075987" : "4337311298790360591") : (isPage ? "6836001094147118188" : "5871903855103380275");
        url = "https://www.blogger.com/comment/frame/" + defBlog + "?" + paramName + "=" + defItem + "&hl=tr&origin=" + encodeURIComponent(orig) + "&skin=contempo";
      }
    }

    cachedBaseThreadUrl = url.replace(/&parentID=\d+/g, "");
    return cachedBaseThreadUrl;
  }

  function ensureCommentEditorIframe(targetCommentId) {
    var cf = document.getElementById("commentForm");
    if (!cf) return null;

    var ed = document.getElementById("comment-editor");
    var iCmn = document.getElementById("iCmn");

    var cleanBase = getBaseThreadUrl();
    var rawId = targetCommentId ? String(targetCommentId).replace(/^c/, "") : "";
    var targetSrc = rawId ? (cleanBase + "&parentID=" + rawId) : cleanBase;

    cf.removeAttribute("hidden");
    cf.style.display = "block";
    cf.classList.remove("cmRbox");
    cf.classList.add("btt-composer-box");

    var addCm = document.getElementById("addCm");
    if (addCm) {
      addCm.setAttribute("hidden", "");
      addCm.style.setProperty("display", "none", "important");
    }
    if (iCmn) {
      iCmn.style.setProperty("display", "none", "important");
    }

    // 1. Ensure Composer Header
    var hdr = cf.querySelector(".btt-composer-header");
    if (!hdr) {
      hdr = document.createElement("div");
      hdr.className = "btt-composer-header";
      cf.insertBefore(hdr, cf.firstChild);
    }

    // 2. Ensure /Komutlar Chip Row
    var slashRow = document.getElementById("bttSlashRow");
    if (!slashRow) {
      slashRow = document.createElement("div");
      slashRow.id = "bttSlashRow";
      slashRow.className = "btt-slash-row";
      slashRow.innerHTML =
        '<span class="btt-slash-label">/komutlar</span>' +
        '<button type="button" class="btt-slash-chip" title="Tepki emojisi" onclick="window.bttCopySlashCmd(\'👍\', this)">/tepki</button>' +
        '<button type="button" class="btt-slash-chip" title="Tıklayınca açılan gizli metin" onclick="window.bttCopySlashCmd(\'/spoiler gizli metin\', this)">/spoiler</button>' +
        '<button type="button" class="btt-slash-chip" title="Logolu bağlantı rozeti" onclick="window.bttCopySlashCmd(\'/url https://site.com Başlık\', this)">/url</button>' +
        '<button type="button" class="btt-slash-chip" title="Bağlantı butonu" onclick="window.bttCopySlashCmd(\'/button https://site.com Buton Yazısı\', this)">/button</button>' +
        '<button type="button" class="btt-slash-chip" title="İndirme butonu" onclick="window.bttCopySlashCmd(\'/indir https://site.com/dosya.zip İndir\', this)">/indir</button>' +
        '<button type="button" class="btt-slash-chip" title="Kod bloğu" onclick="window.bttCopySlashCmd(\'/kod kod_buraya\', this)">/kod</button>' +
        '<button type="button" class="btt-slash-chip" title="Uyarı kutusu" onclick="window.bttCopySlashCmd(\'/uyari Uyarı mesajı\', this)">/uyari</button>' +
        '<button type="button" class="btt-slash-chip" title="Bilgi kutusu" onclick="window.bttCopySlashCmd(\'/bilgi Bilgi mesajı\', this)">/bilgi</button>' +
        '<button type="button" class="btt-slash-chip" title="Açılır kapanır detay kutusu" onclick="window.bttCopySlashCmd(\'/detay Başlık | Detay içeriği\', this)">/detay</button>' +
        '<button type="button" class="btt-slash-chip" title="Görsel ekle" onclick="window.bttCopySlashCmd(\'/resim https://site.com/resim.jpg\', this)">/resim</button>' +
        '<button type="button" class="btt-slash-chip" title="YouTube videosu ekle" onclick="window.bttCopySlashCmd(\'/youtube dQw4w9WgXcQ\', this)">/youtube</button>';

      hdr.insertAdjacentElement("afterend", slashRow);
    }

    // 3. Deterministically Ensure Blogger Comment Iframe
    if (!ed) {
      ed = document.createElement("iframe");
      ed.id = "comment-editor";
      ed.name = "comment-editor";
      ed.title = "Blogger comment";
      ed.className = "btt-comment-editor-iframe";
      ed.setAttribute("frameborder", "0");
      ed.setAttribute("allowtransparency", "true");
      // Note: No sandbox attribute so Firefox & Chrome can transmit permitted cookies and open Google login popups.
      ed.setAttribute("data-thread", cleanBase);
      ed.setAttribute("data-src", targetSrc);
      ed.src = targetSrc;
      ed.style.cssText = "width: 100% !important; min-height: 240px !important; border: none !important; border-radius: 8px !important; background: transparent !important; display: block !important;";

      if (iCmn && iCmn.parentNode) {
        iCmn.insertAdjacentElement("beforebegin", ed);
      } else {
        cf.appendChild(ed);
      }
    } else {
      if (ed.hasAttribute("sandbox")) {
        ed.removeAttribute("sandbox");
      }
      ed.setAttribute("data-thread", cleanBase);
      ed.setAttribute("data-src", targetSrc);
      ed.classList.remove("lazyload");
      ed.classList.add("lazyloaded");
      if (ed.src !== targetSrc) {
        ed.src = targetSrc;
      }
    }

    return ed;
  }

  // =========================================================================
  // 2. NATIVE REPLY & CANCEL REPLY ACTIONS
  // =========================================================================
  window.bttNativeReply = function(commentId, e) {
    if (e) {
      if (typeof e.preventDefault === "function") e.preventDefault();
      if (typeof e.stopPropagation === "function") e.stopPropagation();
    }
    var rawId = String(commentId).replace(/^c/, "");
    var targetLi = document.getElementById("c" + rawId) || document.getElementById(commentId);
    if (!targetLi) {
      targetLi = document.querySelector('[data-comment-id="' + rawId + '"]');
    }

    var holder = document.getElementById("cmHolder");
    var rootLi = targetLi ? (targetLi.closest("#cmHolder > li.c") || targetLi) : null;
    if (!rootLi) return;

    // 1. If currently in Main List View, transition into this topic view first!
    if (!holder.classList.contains("btt-in-topic-view") || activeTopicId !== rootLi.id) {
      window.bttOpenTopicPage(rootLi.id);
    }

    var cf = document.getElementById("commentForm");
    if (!cf) return;

    // 2. Ensure cf is at the bottom of this topic's .cmIn (no reparenting between child comments!)
    var cmIn = rootLi.querySelector(":scope > .cmIn") || rootLi.querySelector(".cmIn") || rootLi;
    if (cf.parentNode !== cmIn) {
      cmIn.appendChild(cf);
    }

    // 3. Update editor iframe with &parentID={rawId}
    var ed = ensureCommentEditorIframe(rawId);

    // 4. Update Header with Reply Banner and Cancel button
    var targetAuth = (targetLi ? targetLi.getAttribute("data-author-name") : "") || "Mesaj";
    var isRoot = (targetLi === rootLi);
    var repLabel = isRoot ? ("@" + targetAuth + " (Ana Konu)") : ("@" + targetAuth);

    var hdr = cf.querySelector(".btt-composer-header");
    if (hdr) {
      hdr.innerHTML =
        '<div class="btt-composer-title-wrap">' +
          '<span class="btt-composer-icon">' + BTT_ICONS.reply + '</span>' +
          '<span class="btt-composer-title"><b>' + repLabel.replace(/</g, "&lt;") + '</b> yanıtlanıyor</span>' +
        '</div>' +
        '<div class="btt-composer-cancel-wrap" style="display:block;">' +
          '<button type="button" class="btt-cancel-reply-btn" title="Yanıtı iptal et (Konu ana yanıtına dön)" onclick="window.bttCancelReply(event)">İptal</button>' +
        '</div>';
    }

    // 5. Active composer visual feedback (cyan pulse)
    cf.classList.remove("btt-composer-active-reply");
    void cf.offsetWidth;
    cf.classList.add("btt-composer-active-reply");
    setTimeout(function() {
      cf.classList.remove("btt-composer-active-reply");
    }, 3200);

    // 6. Smooth scroll down to composer and focus the iframe
    setTimeout(function() {
      cf.scrollIntoView({ behavior: "smooth", block: "center" });
      if (ed && ed.focus) {
        try { ed.focus(); } catch (err) {}
      }
    }, 100);
  };

  window.bttCancelReply = function(e) {
    if (e) {
      if (typeof e.preventDefault === "function") e.preventDefault();
      if (typeof e.stopPropagation === "function") e.stopPropagation();
    }
    var cf = document.getElementById("commentForm");
    if (!cf) return;

    var activeTopic = activeTopicId ? document.getElementById(activeTopicId) : null;
    var activeRootEl = activeTopic;
    if (activeTopic) {
      ensureCommentEditorIframe(activeTopicId);
      var activeAuth = (activeRootEl.getAttribute("data-author-name") || "Konu Sahibi").trim();
      var hdr = cf.querySelector(".btt-composer-header");
      if (hdr) {
        hdr.innerHTML =
          '<div class="btt-composer-title-wrap">' +
            '<span class="btt-composer-icon">' + BTT_ICONS.reply + '</span>' +
            '<span class="btt-composer-title">Bu Konuya Yanıt Yaz (<b>@' + activeAuth.replace(/</g, "&lt;") + '</b>)</span>' +
          '</div>' +
          '<div class="btt-composer-cancel-wrap" style="display:none;"></div>';
      }
    } else {
      ensureCommentEditorIframe(null);
      var hdr = cf.querySelector(".btt-composer-header");
      if (hdr) {
        hdr.innerHTML =
          '<div class="btt-composer-title-wrap">' +
            '<span class="btt-composer-icon">' + BTT_ICONS.chat + '</span>' +
            '<span class="btt-composer-title">Yeni Bir Tartışma / Konu Başlat</span>' +
          '</div>' +
          '<div class="btt-composer-cancel-wrap" style="display:none;"></div>';
      }
    }
  };

  window.bttFindAndScrollToAuthor = function(authorName) {
    if (!authorName) return;
    var clean = authorName.replace(/^@/, "").trim().toLowerCase();
    var allItems = document.querySelectorAll("#cmHolder li.c");
    for (var i = 0; i < allItems.length; i++) {
      var item = allItems[i];
      var a = (item.getAttribute("data-author-name") || "").trim().toLowerCase();
      if (a.indexOf(clean) !== -1 || clean.indexOf(a) !== -1) {
        var rootLi = item.closest("#cmHolder > li.c") || item;
        window.bttOpenTopicPage(rootLi.id, item.id);
        return;
      }
    }
  };

  // =========================================================================
  // 3. DETERMINISTIC COMPOSER SYNCHRONIZATION
  // =========================================================================
  function syncComposerForTopic(topicId) {
    var cf = document.getElementById("commentForm");
    if (!cf) return;

    var holder = document.getElementById("cmHolder");
    var activeRootEl = topicId ? document.getElementById(topicId) : null;
    var addCm = document.getElementById("addCm");

    if (activeRootEl) {
      document.body.classList.add("btt-topic-open");
      // Place cf inside activeRootEl > .cmIn (right after .cmRp)
      var cmIn = activeRootEl.querySelector(":scope > .cmIn") || activeRootEl.querySelector(".cmIn") || activeRootEl;
      if (cf.parentNode !== cmIn) {
        cmIn.appendChild(cf);
      }
      var activeAuth = (activeRootEl.getAttribute("data-author-name") || "Konu Sahibi").trim();
      var hdr = cf.querySelector(".btt-composer-header");
      if (hdr) {
        hdr.innerHTML =
          '<div class="btt-composer-title-wrap">' +
            '<span class="btt-composer-icon">' + BTT_ICONS.reply + '</span>' +
            '<span class="btt-composer-title">Bu Konuya Yanıt Yaz (<b>@' + activeAuth.replace(/</g, "&lt;") + '</b>)</span>' +
          '</div>' +
          '<div class="btt-composer-cancel-wrap" style="display:none;"></div>';
      }
      ensureCommentEditorIframe(topicId);
    } else {
      document.body.classList.remove("btt-topic-open");
      var listContainer = (holder && holder.parentNode) ? holder.parentNode : null;
      var targetParent = listContainer || (addCm ? addCm.parentNode : null) || (holder ? holder.parentNode : null);
      if (targetParent && cf.parentNode !== targetParent) {
        targetParent.appendChild(cf);
      }
      var hdr = cf.querySelector(".btt-composer-header");
      if (hdr) {
        hdr.innerHTML =
          '<div class="btt-composer-title-wrap">' +
            '<span class="btt-composer-icon">' + BTT_ICONS.chat + '</span>' +
            '<span class="btt-composer-title">Yeni Bir Tartışma / Konu Başlat</span>' +
          '</div>' +
          '<div class="btt-composer-cancel-wrap" style="display:none;"></div>';
      }
      ensureCommentEditorIframe(null);
    }
  }

  // =========================================================================
  // 4. TOPIC PAGE TEMPLATE TRANSITIONS & PAGINATION
  // =========================================================================
  var TOPICS_PER_PAGE = 9999;
  var currentPage = 1;
  var activeTopicId = null;

  function getRootTopics() {
    var holder = document.getElementById("cmHolder");
    if (!holder) return [];
    return Array.prototype.filter.call(holder.children, function(el) {
      return el.tagName === "LI" && el.classList.contains("c");
    });
  }

  window.bttOpenTopicPage = function(topicId, targetReplyId, e) {
    if (e) {
      e.preventDefault();
      e.stopPropagation();
    }
    var fc = document.getElementById("forComments");
    if (fc) fc.checked = true;
    var cleanTopicId = topicId.indexOf("c") === 0 ? topicId : ("c" + topicId);
    var topicEl = document.getElementById(cleanTopicId);
    if (topicEl && topicEl.parentElement && topicEl.parentElement.id !== "cmHolder") {
      var parentRoot = topicEl.closest("#cmHolder > li.c");
      if (parentRoot) {
        targetReplyId = cleanTopicId;
        cleanTopicId = parentRoot.id;
      }
    }

    var tab0 = document.getElementById("iRcmpf-0");
    if (tab0) tab0.checked = true;

    activeTopicId = cleanTopicId;
    var targetHash = "#topic-" + cleanTopicId;
    if (window.location.hash !== targetHash) {
      if (history.pushState) {
        history.pushState(null, null, targetHash);
      } else {
        window.location.hash = targetHash;
      }
    }
    renderTopicOrListView(targetReplyId || cleanTopicId);
  };

  window.bttBackToTopicList = function(e) {
    if (e) {
      e.preventDefault();
      e.stopPropagation();
    }
    activeTopicId = null;
    if (history.pushState) {
      history.pushState(null, null, window.location.pathname + window.location.search);
    } else {
      window.location.hash = "";
    }
    renderTopicOrListView(null);
    var cmSec = document.getElementById("comment-blogger");
    if (cmSec && cmSec.scrollIntoView) {
      cmSec.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  };

  window.bttChangePage = function(pageNum, e) {
    if (e) e.preventDefault();
    currentPage = pageNum;
    renderTopicOrListView(null);
    var cmSec = document.getElementById("comment-blogger");
    if (cmSec && cmSec.scrollIntoView) {
      cmSec.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  };

  function renderTopicOrListView(scrollToCommentId) {
    var holder = document.getElementById("cmHolder");
    if (!holder) return;
    hydrateLazyAvatars(); ensureGuildedChannelsBar();

    var roots = getRootTopics();
    var topBar = document.getElementById("bttTopSearchBar");
    var topicNav = document.getElementById("bttTopicPageNav");
    var pagerEl = document.getElementById("bttPaginationBar");

    if (activeTopicId && document.getElementById(activeTopicId)) {
      // --- DEDICATED TOPIC PAGE TEMPLATE MODE ---
      holder.classList.add("btt-in-topic-view");
      if (topBar) topBar.style.display = "none";
      if (pagerEl) pagerEl.style.display = "none";

      var currentIdx = -1;
      roots.forEach(function(r, idx) {
        if (r.id === activeTopicId) {
          r.style.display = "";
          currentIdx = idx;
        } else {
          r.style.display = "none";
        }
      });
      hydrateLazyAvatars(); ensureGuildedChannelsBar();

      if (topicNav) {
        topicNav.classList.add("active");
        var prevId = currentIdx > 0 ? roots[currentIdx - 1].id : null;
        var nextId = (currentIdx !== -1 && currentIdx < roots.length - 1) ? roots[currentIdx + 1].id : null;
        topicNav.innerHTML =
          '<button type="button" class="btt-nav-btn btt-back-btn" title="Tüm Konulara Dön" aria-label="Tüm Konulara Dön" onclick="window.bttBackToTopicList(event)">' + BTT_ICONS.arrowLeft + '</button>' +
          '<div class="btt-nav-slider">' +
            '<span class="btt-nav-status">Konu ' + (currentIdx + 1) + ' / ' + roots.length + '</span>' +
            '<div class="btt-slider-dashes-wrap">' +
              '<button type="button" class="btt-slider-dash btt-slider-prev" title="Önceki Konu" ' + (prevId ? 'onclick="window.bttOpenTopicPage(\'' + prevId + '\', null, event)"' : 'disabled') + '>' +
                '<span class="btt-capsule-bar"></span>' +
              '</button>' +
              '<button type="button" class="btt-slider-dash btt-slider-next" title="Sonraki Konu" ' + (nextId ? 'onclick="window.bttOpenTopicPage(\'' + nextId + '\', null, event)"' : 'disabled') + '>' +
                '<span class="btt-capsule-bar"></span>' +
              '</button>' +
            '</div>' +
          '</div>';
      }

      var activeRootEl = document.getElementById(activeTopicId);
      if (activeRootEl) {
        var cmIn = activeRootEl.querySelector(":scope > .cmIn") || activeRootEl.querySelector(".cmIn") || activeRootEl;
        var childReplies = activeRootEl.querySelectorAll(".thCh > li.c");
        var repDivider = cmIn.querySelector(".btt-topic-replies-divider");
        if (!repDivider) {
          repDivider = document.createElement("div");
          repDivider.className = "btt-topic-replies-divider";
          var cmRp = cmIn.querySelector(".cmRp");
          if (cmRp) {
            cmIn.insertBefore(repDivider, cmRp);
          } else {
            cmIn.appendChild(repDivider);
          }
        }
        if (childReplies.length === 0) {
          repDivider.innerHTML =
            '<div class="btt-rep-div-inner empty">' +
              '<span class="btt-rep-div-badge">0 Yanıt</span>' +
              '<span class="btt-rep-div-text">Bu konuya henüz yanıt yazılmamış. İlk yanıtı aşağıdaki kutudan gönderebilirsiniz:</span>' +
            '</div>';
        } else {
          repDivider.innerHTML =
            '<div class="btt-rep-div-inner">' +
              '<span class="btt-rep-div-badge">' + childReplies.length + ' Yanıt</span>' +
              '<span class="btt-rep-div-text">Bu konudaki tüm yanıtlar kronolojik sırayla listelenmiştir:</span>' +
            '</div>';
        }
      }

      syncComposerForTopic(activeTopicId);

      if (scrollToCommentId) {
        setTimeout(function() {
          if (scrollToCommentId === activeTopicId && topicNav) {
            topicNav.scrollIntoView({ behavior: "smooth", block: "start" });
          } else {
            window.bttScrollAndFlash(scrollToCommentId);
          }
        }, 80);
      }
    } else {
      // --- MAIN PAGINATED TOPIC LIST MODE ---
      holder.classList.remove("btt-in-topic-view");
      if (topBar) topBar.style.display = "flex";
      if (topicNav) topicNav.classList.remove("active");

      syncComposerForTopic(null);

      var searchInput = document.getElementById("bttTopicSearch");
      var clearBtn = document.getElementById("bttSearchClear");
      var q = searchInput ? searchInput.value.toLowerCase().trim() : "";
      if (clearBtn) clearBtn.style.display = q ? "inline-flex" : "none";

      var filtered = roots.filter(function(r) {
        if (!q) return true;
        var txt = (r.textContent || "").toLowerCase();
        var auth = (r.getAttribute("data-author-name") || "").toLowerCase();
        return txt.indexOf(q) !== -1 || auth.indexOf(q) !== -1;
      });

      var totalPages = Math.max(1, Math.ceil(filtered.length / TOPICS_PER_PAGE));
      if (currentPage > totalPages) currentPage = totalPages;
      var startIdx = (currentPage - 1) * TOPICS_PER_PAGE;
      var endIdx = startIdx + TOPICS_PER_PAGE;
      var visibleSet = filtered.slice(startIdx, endIdx);

      roots.forEach(function(r) {
        r.style.display = (visibleSet.indexOf(r) !== -1) ? "" : "none";
      });

      if (pagerEl) {
        pagerEl.style.display = "none";
        pagerEl.innerHTML = "";
      }
    }
  }

  // =========================================================================
  // 5. ENHANCE COMMENTS DOM (100% Original yedek.xml Structure Preserved)
  // =========================================================================
  function getMiniAvatarHtml(li) {
    if (!li) return "";
    var name = (li.getAttribute("data-author-name") || "Ziyaretçi").trim();
    var img = li.querySelector(".cmAv img");
    var src = (img && img.src && img.src.indexOf("blank.gif") === -1 && img.src.indexOf("b16-rounded") === -1)
      ? img.src
      : (li.getAttribute("data-author-image") || getFallbackAvatarSvg(name));
    return '<span class="btt-mini-av" title="@' + name.replace(/</g, "&lt;").replace(/"/g, "&quot;") + '"><img src="' + src + '" alt="' + name.replace(/"/g, "&quot;") + '" onerror="this.onerror=null;this.src=window.bttFallbackAv(\'' + name.replace(/'/g, "\\'") + '\');"/></span>';
  }

  function enhanceCommentsDOM() {
    var cmBlogger = document.getElementById("comment-blogger");
    var holder = document.getElementById("cmHolder");
    if (window.location.pathname.indexOf("muhabbet") !== -1) {
      document.body.classList.add("is-muhabbet-hub");
    }
    if (!cmBlogger || !holder) return;
    hydrateLazyAvatars(); ensureGuildedChannelsBar();

    var cmC = cmBlogger.querySelector(".cmC");
    if (cmC && !document.getElementById("bttTopSearchBar")) {
      var topBar = document.createElement("div");
      topBar.id = "bttTopSearchBar";
      topBar.className = "btt-top-bar";
      topBar.innerHTML =
        '<div class="btt-search-wrap">' +
          BTT_ICONS.search +
          '<input type="text" id="bttTopicSearch" class="btt-search-input" placeholder="Mesajlarda, konularda veya @yazarlarda ara..."/>' +
        '</div>';
      var targetContainer = (holder.parentNode && holder.parentNode.parentNode) ? holder.parentNode : holder;
      targetContainer.insertAdjacentElement("beforebegin", topBar);

      var topicNav = document.createElement("div");
      topicNav.id = "bttTopicPageNav";
      topicNav.className = "btt-topic-nav";
      topBar.insertAdjacentElement("afterend", topicNav);

      var pager = document.createElement("div");
      pager.id = "bttPaginationBar";
      pager.className = "btt-pagination";
      targetContainer.insertAdjacentElement("afterend", pager);

      var sIn = document.getElementById("bttTopicSearch");
      var sCl = document.getElementById("bttSearchClear");
      if (sIn) {
        ['keydown', 'keyup', 'keypress'].forEach(function(evName) {
          sIn.addEventListener(evName, function(e) {
            e.stopPropagation();
          }, true);
        });
        sIn.addEventListener("input", function() {
          var q = normTr(sIn.value || "").trim();
          if (holder.classList.contains("btt-in-topic-view")) {
            var replies = holder.querySelectorAll(".thCh > li.c");
            replies.forEach(function(rep) {
              var txt = normTr(rep.textContent || "");
              rep.style.display = (!q || txt.indexOf(q) !== -1) ? "" : "none";
            });
            return;
          }
          var roots = getRootTopics();
          var matchCount = 0;
          roots.forEach(function(r) {
            var txt = normTr(r.textContent || "");
            var auth = normTr(r.getAttribute("data-author-name") || "");
            var isMatch = !q || txt.indexOf(q) !== -1 || auth.indexOf(q) !== -1;
            r.style.display = isMatch ? "" : "none";
            if (isMatch) matchCount++;
          });
          var noRes = document.getElementById("bttTopicNoResult");
          if (!noRes) {
            noRes = document.createElement("li");
            noRes.id = "bttTopicNoResult";
            noRes.className = "btt-no-results-msg";
            noRes.style.cssText = "padding:24px 16px;text-align:center;color:#989b9f;font-size:13px;list-style:none;";
            noRes.textContent = "Aramanızla eşleşen konu veya mesaj bulunamadı.";
            holder.appendChild(noRes);
          }
          if (noRes) noRes.style.display = (matchCount === 0 && q) ? "block" : "none";
        });
      }
      if (sCl && sIn) {
        sCl.addEventListener("click", function() {
          sIn.value = "";
          if (holder.classList.contains("btt-in-topic-view")) {
            var replies = holder.querySelectorAll(".thCh > li.c");
            replies.forEach(function(rep) { rep.style.display = ""; });
            sIn.focus();
            return;
          }
          var roots = getRootTopics();
          roots.forEach(function(r) { r.style.display = ""; });
          var noRes = document.getElementById("bttTopicNoResult");
          if (noRes) noRes.style.display = "none";
          sIn.focus();
        });
      }
      ['keydown', 'keyup', 'keypress'].forEach(function(evName) {
        window.addEventListener(evName, function(e) {
          var t = e.target;
          if (t && (t.id === 'bttTopicSearch' || (t.classList && (t.classList.contains('btt-search-input') || t.classList.contains('btt-native-search'))) || (t.closest && t.closest('#comment-blogger, .btt-search-wrap, #advSearchModal, .btt-native-panel, input, textarea')))) {
            if (e.key !== 'Escape') {
              e.stopPropagation();
            }
          }
        }, true);
      });
    }

    var roots = getRootTopics();
    roots.forEach(function(rootLi, rIdx) {
      var rootId = rootLi.id;
      var rootAuthor = (rootLi.getAttribute("data-author-name") || "Ziyaretçi").trim();
      var rootBodyEl = rootLi.querySelector(":scope > .cmIn > .cmBd > .cmCo");
      var rootRawText = "";

      if (rootBodyEl) {
        if (!rootBodyEl.getAttribute("data-btt-parsed")) {
          rootRawText = (rootBodyEl.textContent || rootBodyEl.innerText || "").trim();
          rootBodyEl.setAttribute("data-raw-text", rootRawText);
          rootBodyEl.setAttribute("data-btt-parsed", "true");
          rootBodyEl.innerHTML = parseDiscourseTags(rootBodyEl.innerHTML);
        } else {
          rootRawText = rootBodyEl.getAttribute("data-raw-text") || "";
        }
      }

      function cleanSnippetText(raw) {
        if (!raw) return "Mesaj";
        var txt = raw.replace(/\/(youtube|img|button|video|audio|code|alert|warning|info|success|danger|tab|spoiler)\b[^\n]*/gi, "[$1]");
        txt = txt.replace(/\s+/g, " ").trim();
        if (txt.length > 50) txt = txt.substring(0, 50) + "…";
        return txt || "Mesaj";
      }

      var rootSnippet = cleanSnippetText(rootRawText) || "Ana mesaj";
      var childReplies = rootLi.querySelectorAll(".thCh > li.c");

      // Child replies
      childReplies.forEach(function(childLi, cIdx) {
        var childBodyEl = childLi.querySelector(".cmCo");
        var cRaw = "";
        if (childBodyEl) {
          if (!childBodyEl.getAttribute("data-btt-parsed")) {
            cRaw = (childBodyEl.textContent || childBodyEl.innerText || "").trim();
            childBodyEl.setAttribute("data-raw-text", cRaw);
            childBodyEl.setAttribute("data-btt-parsed", "true");
            childBodyEl.innerHTML = parseDiscourseTags(childBodyEl.innerHTML);
          } else {
            cRaw = childBodyEl.getAttribute("data-raw-text") || "";
          }
        }

        if (!childLi.getAttribute("data-btt-ready")) {
          childLi.setAttribute("data-btt-ready", "true");
          var childBd = childLi.querySelector(".cmBd");
          var childAv = childLi.querySelector(":scope > .cmAv");
          if (childBd && childAv && childAv.parentNode !== childBd) {
            childBd.insertBefore(childAv, childBd.firstChild);
          }

          // Move action buttons INSIDE childBd at the bottom!
          var childAc = childBd ? childBd.querySelector(".cmAc") : null;
          if (!childAc) {
            childAc = document.createElement("div");
            childAc.className = "cmAc";
            if (childBd) childBd.appendChild(childAc);
          }
          childAc.innerHTML =
            '<button type="button" class="btt-msg-link-btn" title="Mesaj bağlantısını kopyala" onclick="window.bttCopyLink(\'' + childLi.id + '\', this, event)">' +
              BTT_ICONS.link +
            '</button>' +
            '<button type="button" class="rpTo btt-action-reply-btn" data-reply-to="' + childLi.id.replace(/^c/, '') + '" title="Bu mesaja yanıt ver" onclick="window.bttNativeReply(\'' + childLi.id + '\', event)">' +
              BTT_ICONS.reply +
            '</button>';

          // Remove any orphaned .cmAc directly under childIn or outside childBd
          childLi.querySelectorAll(":scope > .cmIn > .cmAc").forEach(function(o) {
            if (o !== childAc && o.parentNode) o.remove();
          });

          // Embed Quote Determination (cevap içine cevap eski mesajı reply olarak gösterme)
          var parentId = rootId;
          var parentAuthor = rootAuthor;
          var parentSnippet = cleanSnippetText(rootRawText);
          var parentLabel = "Ana Mesaj ↑";

          var rawReplyText = cRaw.trim();
          var matchedPrior = null;

          // Check if text mentions @Author of any prior reply in this thread (nearest backwards)
          for (var p = cIdx - 1; p >= 0; p--) {
            var priorRep = childReplies[p];
            var priorAuth = (priorRep.getAttribute("data-author-name") || "").trim();
            if (priorAuth && rawReplyText.toLowerCase().indexOf("@" + priorAuth.toLowerCase()) !== -1) {
              matchedPrior = {
                el: priorRep,
                id: priorRep.id,
                author: priorAuth,
                isRoot: false,
                idx: p + 1
              };
              break;
            }
          }

          // Also check if mentions rootAuthor
          if (!matchedPrior && rootAuthor && rawReplyText.toLowerCase().indexOf("@" + rootAuthor.toLowerCase()) !== -1) {
            matchedPrior = {
              el: rootLi,
              id: rootId,
              author: rootAuthor,
              isRoot: true,
              idx: 0
            };
          }

          if (matchedPrior) {
            parentId = matchedPrior.id;
            parentAuthor = matchedPrior.author;
            var pCo = matchedPrior.el.querySelector(".cmCo");
            var pRaw = pCo ? (pCo.getAttribute("data-raw-text") || pCo.textContent || "") : "";
            parentSnippet = cleanSnippetText(pRaw);
            parentLabel = matchedPrior.isRoot ? "Ana Mesaj ↑" : ("Yanıt #" + (rIdx + 1) + "." + matchedPrior.idx + " ↑");
          } else if (cIdx > 0) {
            // Sequential threaded reply -> replies to immediately preceding reply!
            var prevRep = childReplies[cIdx - 1];
            parentId = prevRep.id;
            parentAuthor = (prevRep.getAttribute("data-author-name") || "Ziyaretçi").trim();
            var prevCo = prevRep.querySelector(".cmCo");
            var prevRaw = prevCo ? (prevCo.getAttribute("data-raw-text") || prevCo.textContent || "") : "";
            parentSnippet = cleanSnippetText(prevRaw);
            parentLabel = "Yanıt #" + (rIdx + 1) + "." + cIdx + " ↑";
          } else {
            // First reply in topic -> replies to root topic
            parentId = rootId;
            parentAuthor = rootAuthor;
            parentSnippet = cleanSnippetText(rootRawText);
            parentLabel = "Ana Mesaj ↑";
          }

          // Clickable Parent Quote Bar at top of Reply body
          if (childBd && childBodyEl && !childBd.querySelector(".btt-reply-quote-ref")) {
            var qBar = document.createElement("div");
            qBar.className = "btt-reply-quote-ref";
            qBar.title = "Yanıtlanan mesaja gitmek için tıklayın";
            (function(pTargetId) {
              qBar.onclick = function(ev) {
                window.bttScrollAndFlash(pTargetId, ev);
              };
            })(parentId);
            qBar.innerHTML =
              '<div class="btt-rq-left">' +
                '<span class="btt-rq-author">' + BTT_ICONS.reply + ' @' + parentAuthor.replace(/</g, "&lt;") + ':</span>' +
                '<span class="btt-rq-text">"' + parentSnippet.replace(/</g, "&lt;") + '"</span>' +
              '</div>' +
              '<span class="btt-rq-jump">' + parentLabel + '</span>';
            childBd.insertBefore(qBar, childBodyEl);
          }
        }
      });

      if (!rootLi.getAttribute("data-btt-ready")) {
        rootLi.setAttribute("data-btt-ready", "true");
        var rootBdEl = rootLi.querySelector(":scope > .cmIn > .cmBd");
        var rootAvEl = rootLi.querySelector(":scope > .cmAv");
        if (rootBdEl && rootAvEl && rootAvEl.parentNode !== rootBdEl) {
          rootBdEl.insertBefore(rootAvEl, rootBdEl.firstChild);
        }

        // Action buttons strictly INSIDE rootBdEl at bottom (BEFORE .cmRp!)
        var rAc = rootBdEl ? rootBdEl.querySelector(".cmAc") : null;
        if (!rAc) {
          rAc = document.createElement("div");
          rAc.className = "cmAc";
          if (rootBdEl) rootBdEl.appendChild(rAc);
        }
        rAc.innerHTML =
          '<button type="button" class="btt-msg-link-btn" title="Konu bağlantısını kopyala" onclick="window.bttCopyLink(\'' + rootId + '\', this, event)">' +
            BTT_ICONS.link +
          '</button>' +
          '<button type="button" class="rpTo btt-action-reply-btn" data-reply-to="' + rootId.replace(/^c/, '') + '" title="Bu konuya yanıt ver" onclick="window.bttNativeReply(\'' + rootId + '\', event)">' +
            BTT_ICONS.reply +
          '</button>';

        // Remove ALL orphaned .cmAc that are placed after .cmRp or directly inside .cmIn
        rootLi.querySelectorAll(".cmRp ~ .cmAc, .cmRp ~ .show-if-js, :scope > .cmIn > .cmAc").forEach(function(o) {
          if (o !== rAc && o.parentNode) o.remove();
        });

        // Build Rich Topic Summary Bar for Main List View
        var rootBd = rootLi.querySelector(":scope > .cmIn > .cmBd");
        if (rootBd && !rootBd.querySelector(".btt-card-open-bar")) {
          var openBar = document.createElement("div");
          openBar.className = "btt-card-open-bar";

          var leftSummary = "";
          if (childReplies.length > 0) {
            var lastRep = childReplies[childReplies.length - 1];
            var lastAuth = (lastRep.getAttribute("data-author-name") || "Ziyaretçi").trim();
            var lastCo = lastRep.querySelector(".cmCo");
            var lastTxt = (lastCo ? (lastCo.getAttribute("data-raw-text") || lastCo.textContent || "") : "").replace(/\s+/g, " ").trim().substring(0, 52);
            leftSummary =
              '<div class="btt-card-summary-left">' +
                '<span class="btt-last-rep-text">Son yanıt <b>@' + lastAuth.replace(/</g, "&lt;") + '</b>: "' + lastTxt.replace(/</g, "&lt;") + (lastTxt.length >= 52 ? "…" : "") + '"</span>' +
              '</div>';
          } else {
            leftSummary = '<div class="btt-card-summary-left"><span class="btt-last-rep-text">Henüz yanıt yok</span></div>';
          }

          var pillLabel = childReplies.length > 0
            ? (BTT_ICONS.chat + '<span class="btt-reply-count-badge">' + childReplies.length + '</span>')
            : BTT_ICONS.chat;
          openBar.innerHTML =
            leftSummary +
            '<div class="btt-card-actions-right">' +
              '<button type="button" class="btt-open-topic-pill" title="Tartışmayı görüntüle" onclick="window.bttOpenTopicPage(\'' + rootId + '\', null, event)">' + pillLabel + '</button>' +
              '<button type="button" class="btt-msg-link-btn" title="Konu bağlantısını kopyala" onclick="window.bttCopyLink(\'' + rootId + '\', this, event)">' +
                BTT_ICONS.link +
              '</button>' +
            '</div>';
          if (rAc && rAc.parentNode === rootBd) {
            rootBd.insertBefore(openBar, rAc);
          } else {
            rootBd.appendChild(openBar);
          }
        }

        if (rootBd) {
          rootBd.addEventListener("click", function(ev) {
            if (holder.classList.contains("btt-in-topic-view")) return;
            if (ev.target && ev.target.closest && ev.target.closest("a, button, input, label, details, video, audio, .spoiler")) return;
            window.bttOpenTopicPage(rootId, null, ev);
          });
        }
      }
    });
  }

  window.bttCopySlashCmd = function(cmdText, chipEl) {
    safeCopy(cmdText);
    if (chipEl) {
      var orig = chipEl.getAttribute("data-orig") || chipEl.innerHTML;
      chipEl.setAttribute("data-orig", orig);
      chipEl.innerHTML = "Kopyalandı";
      setTimeout(function() { chipEl.innerHTML = orig; }, 1300);
    }
    var ed = document.getElementById("comment-editor");
    if (ed && ed.focus) {
      try { ed.focus(); } catch (e) {}
    }
  };



  function enhanceComposerSlashRow() {
    ensureCommentEditorIframe(activeTopicId);
  }

  // =========================================================================
  // 7. NATIVE .cmPkr PANELS: SON AKTİVİTELER & KONULAR
  // =========================================================================
  window.bttReplyFromPanel = function(pageUrl, parentTopicId, commentId, e) {
    if (e) {
      if (typeof e.preventDefault === "function") e.preventDefault();
      if (typeof e.stopPropagation === "function") e.stopPropagation();
    }
    var cleanParentId = parentTopicId ? (parentTopicId.indexOf("c") === 0 ? parentTopicId : ("c" + parentTopicId)) : "";
    var cleanCommentId = commentId ? (commentId.indexOf("c") === 0 ? commentId : ("c" + commentId)) : "";

    var curPath = window.location.pathname;
    var targetPath = (pageUrl || "").replace(/^https?:\/\/[^\/]+/i, "").split("?")[0].split("#")[0];

    var targetLi = (cleanCommentId && document.getElementById(cleanCommentId)) || (cleanParentId && document.getElementById(cleanParentId));
    if ((!targetPath || targetPath === curPath) && targetLi) {
      var tab0 = document.getElementById("iRcmpf-0");
      if (tab0) tab0.checked = true;
      window.bttOpenTopicPage(cleanParentId || cleanCommentId, cleanCommentId);
      setTimeout(function() {
        window.bttNativeReply(cleanCommentId || cleanParentId);
      }, 180);
    } else {
      window.location.href = (targetPath || curPath) + "#topic-" + (cleanParentId || cleanCommentId);
    }
  };

  window.bttGoToActivityMessage = function(pageUrl, parentTopicId, commentId, e) {
    if (e) {
      if (typeof e.preventDefault === "function") e.preventDefault();
      if (typeof e.stopPropagation === "function") e.stopPropagation();
    }
    var cleanParentId = parentTopicId ? (parentTopicId.indexOf("c") === 0 ? parentTopicId : ("c" + parentTopicId)) : "";
    var cleanCommentId = commentId ? (commentId.indexOf("c") === 0 ? commentId : ("c" + commentId)) : "";

    var curPath = window.location.pathname;
    var targetPath = (pageUrl || "").replace(/^https?:\/\/[^\/]+/i, "").split("?")[0].split("#")[0];

    // If on current page and comment element is in DOM
    var targetLi = (cleanCommentId && document.getElementById(cleanCommentId)) || (cleanParentId && document.getElementById(cleanParentId));
    if ((!targetPath || targetPath === curPath) && targetLi) {
      var tab0 = document.getElementById("iRcmpf-0");
      if (tab0) tab0.checked = true;
      window.bttOpenTopicPage(cleanParentId || cleanCommentId, cleanCommentId);
    } else {
      window.location.href = (targetPath || curPath) + "#topic-" + (cleanParentId || cleanCommentId);
    }
  };

  function cleanPreviewText(raw) {
    if (!raw) return "";
    return raw
      .replace(/<[^>]+>/g, " ")
      .replace(/\/(?:button|buton|btn)\s+[^\s]+\s*([^\n\r<]*)/gi, "[Buton: $1]")
      .replace(/\/(?:url|link)\s+[^\s]+\s*([^\n\r<]*)/gi, "[Bağlantı: $1]")
      .replace(/\/(?:uyari|warning)\s+/gi, "[Uyarı] ")
      .replace(/\/(?:bilgi|info)\s+/gi, "[Bilgi] ")
      .replace(/\/(?:resim|img|image)\s+[^\s]+/gi, "[Görsel]")
      .replace(/\/(?:video|youtube|yt)\s+[^\s]+/gi, "[Video]")
      .replace(/\/(?:kod|code)\s+/gi, "[Kod] ")
      .replace(/\/(?:spoiler)\s+/gi, "[Gizli İçerik] ")
      .replace(/\/(?:detay)\s+/gi, "[Detay] ")
      .replace(/https?:\/\/[^\s<"']+/gi, function(u) {
        try {
          var host = new URL(u).hostname.replace(/^www\./, "");
          return "[" + host + "]";
        } catch (e) {
          return "[Link]";
        }
      })
      .replace(/\s+/g, " ")
      .trim();
  }

  window.bttFilterActivityItems = function(q) {
    var term = normTr(q);
    var items = document.querySelectorAll("#bttPanelActivity .btt-native-item");
    var foundCount = 0;
    items.forEach(function(item) {
      var hay = normTr((item.textContent || "") + " " + (item.getAttribute("data-search") || ""));
      var match = !term || hay.indexOf(term) !== -1;
      item.classList.toggle("btt-hidden", !match);
      if (match) {
        item.style.setProperty("display", "flex", "important");
        foundCount++;
      } else {
        item.style.setProperty("display", "none", "important");
      }
    });
    var noRes = document.getElementById("bttActNoResult");
    if (!noRes) {
      noRes = document.createElement("p");
      noRes.id = "bttActNoResult";
      noRes.style.cssText = "padding:20px;text-align:center;opacity:.7;";
      noRes.textContent = "Aramanızla eşleşen sonuç bulunamadı.";
      var panel = document.getElementById("bttPanelActivity");
      if (panel) panel.appendChild(noRes);
    }
    if (noRes) noRes.style.display = (foundCount === 0 && term) ? "block" : "none";
  };

  window.bttFilterTopicsPanel = function(q) {
    var term = normTr(q);
    var items = document.querySelectorAll("#bttPanelTopics .btt-native-item");
    var foundCount = 0;
    items.forEach(function(item) {
      var hay = normTr((item.textContent || "") + " " + (item.getAttribute("data-search") || ""));
      var match = !term || hay.indexOf(term) !== -1;
      item.classList.toggle("btt-hidden", !match);
      if (match) {
        item.style.setProperty("display", "flex", "important");
        foundCount++;
      } else {
        item.style.setProperty("display", "none", "important");
      }
    });
    var secHdrs = document.querySelectorAll("#bttPanelTopics .btt-native-sec-hdr");
    secHdrs.forEach(function(hdr) {
      hdr.style.display = term ? "none" : "";
    });
    var noRes = document.getElementById("bttTopNoResult");
    if (!noRes) {
      noRes = document.createElement("p");
      noRes.id = "bttTopNoResult";
      noRes.style.cssText = "padding:20px;text-align:center;opacity:.7;";
      noRes.textContent = "Aramanızla eşleşen konu bulunamadı.";
      var panel = document.getElementById("bttPanelTopics");
      if (panel) panel.appendChild(noRes);
    }
    if (noRes) noRes.style.display = (foundCount === 0 && term) ? "block" : "none";
  };

  function formatPageSlug(url) {
    if (!url) return "Blog";
    var path = url.replace(/^https?:\/\/[^\/]+/i, "").split("?")[0].split("#")[0];
    var slug = path.split("/").pop().replace(/\.html$/i, "").replace(/-/g, " ");
    if (!slug) return "Ana Sayfa";
    return slug.charAt(0).toUpperCase() + slug.slice(1);
  }

  // =========================================================================
  // INSTANT FEED ENGINE: DOM-FIRST + JSONP BLOG-WIDE MERGE
  // =========================================================================
  var allActivityItems = [];
  var allTopicItems = [];
  var blogFeedsLoaded = false;
  var isFeedFetching = false;

  function extractDomActivityAndTopics() {
    var holder = document.getElementById("cmHolder");
    var activities = [];
    var topics = [];
    if (!holder) return { activities: activities, topics: topics };

    var roots = getRootTopics();
    var pageTitle = (document.title || "Bu Yazı").split("-")[0].split("|")[0].trim() || "Ana Sayfa";
    var pageUrl = window.location.pathname;

    roots.forEach(function(rootLi, rIdx) {
      var rootId = rootLi.id;
      var rootAuthor = (rootLi.getAttribute("data-author-name") || "Ziyaretçi").trim();
      var rootTimeEl = rootLi.querySelector(".timeAgo");
      var rootDate = (rootTimeEl && (rootTimeEl.getAttribute("data-time") || rootTimeEl.textContent)) || (rootLi.getAttribute("data-timestamp") || "");
      var rootBodyEl = rootLi.querySelector(".cmBd > .cmCo") || rootLi.querySelector(".cmCo");
      var rootRaw = (rootBodyEl ? (rootBodyEl.getAttribute("data-raw-text") || rootBodyEl.textContent || "") : "").trim();
      var childReplies = rootLi.querySelectorAll(".thCh > li.c");

      var rootAvImg = rootLi.querySelector(".cmAv img");
      var rootAvatar = (rootLi.getAttribute("data-author-image") || (rootAvImg ? (rootAvImg.getAttribute("src") || rootAvImg.getAttribute("data-src")) : "") || "").trim();
      if (!rootAvatar || rootAvatar.indexOf("blank.gif") !== -1 || rootAvatar.indexOf("b16-rounded") !== -1) {
        rootAvatar = getFallbackAvatarSvg(rootAuthor);
      } else {
        rootAvatar = upgradeAvatarUrl(rootAvatar);
      }

      var topicItem = {
        id: rootId,
        author: rootAuthor,
        avatar: rootAvatar,
        text: rootRaw || "Ana konu mesajı",
        date: rootDate,
        path: pageUrl,
        pageTitle: pageTitle,
        replyCount: childReplies.length,
        lastActivityAuthor: rootAuthor
      };

      // Add root comment to activities
      activities.push({
        commentId: rootId,
        parentTopicId: rootId,
        author: rootAuthor,
        avatar: rootAvatar,
        text: rootRaw || "Ana konu mesajı",
        date: rootDate,
        pageTitle: pageTitle,
        pageUrl: pageUrl,
        isReply: false
      });

      // Add child replies to activities
      childReplies.forEach(function(childLi, cIdx) {
        var cAuthor = (childLi.getAttribute("data-author-name") || "Ziyaretçi").trim();
        var cTimeEl = childLi.querySelector(".timeAgo");
        var cDate = (cTimeEl && (cTimeEl.getAttribute("data-time") || cTimeEl.textContent)) || (childLi.getAttribute("data-timestamp") || "");
        var cBodyEl = childLi.querySelector(".cmBd > .cmCo") || childLi.querySelector(".cmCo");
        var cRaw = (cBodyEl ? (cBodyEl.getAttribute("data-raw-text") || cBodyEl.textContent || "") : "").trim();

        var cAvImg = childLi.querySelector(".cmAv img");
        var cAvatar = (childLi.getAttribute("data-author-image") || (cAvImg ? (cAvImg.getAttribute("src") || cAvImg.getAttribute("data-src")) : "") || "").trim();
        if (!cAvatar || cAvatar.indexOf("blank.gif") !== -1 || cAvatar.indexOf("b16-rounded") !== -1) {
          cAvatar = getFallbackAvatarSvg(cAuthor);
        } else {
          cAvatar = upgradeAvatarUrl(cAvatar);
        }

        topicItem.lastActivityAuthor = cAuthor;

        activities.push({
          commentId: childLi.id,
          parentTopicId: rootId,
          author: cAuthor,
          avatar: cAvatar,
          text: cRaw || "Yanıt mesajı",
          date: cDate,
          pageTitle: pageTitle,
          pageUrl: pageUrl,
          isReply: true
        });
      });

      topics.push(topicItem);
    });

    return { activities: activities, topics: topics };
  }

