  function fetchBlogFeedJsonp(feedUrl, callback) {
    var cbName = "bttFeedCb_" + Math.random().toString(36).substring(2, 9);
    var script = document.createElement("script");
    var timeout = setTimeout(function() {
      cleanup();
      tryFetchFallback();
    }, 3500);

    function cleanup() {
      clearTimeout(timeout);
      delete window[cbName];
      if (script.parentNode) script.parentNode.removeChild(script);
    }

    window[cbName] = function(json) {
      cleanup();
      callback(json);
    };

    var sep = feedUrl.indexOf("?") === -1 ? "?" : "&";
    script.src = feedUrl + sep + "alt=json-in-script&callback=" + cbName;
    script.onerror = function() {
      cleanup();
      tryFetchFallback();
    };

    function tryFetchFallback() {
      var fullUrl = feedUrl.indexOf("http") === 0 ? feedUrl : (window.location.origin + feedUrl);
      var sep2 = fullUrl.indexOf("?") === -1 ? "?" : "&";
      fetch(fullUrl + sep2 + "alt=json")
        .then(function(res) { return res.json(); })
        .then(function(json) { callback(json); })
        .catch(function() { callback(null); });
    }

    document.head.appendChild(script);
  }

  function loadNativeFeeds() {
    window.bttLoadNativeFeeds = loadNativeFeeds;
    var roots = getRootTopics();
    var tab0 = document.querySelector('label[for="iRcmpf-0"]');
    if (tab0 && roots.length > 0) {
      tab0.setAttribute("title", "Tartışmalar (" + roots.length + ")");
    }

    var actPanel = document.getElementById("bttPanelActivity");
    var topPanel = document.getElementById("bttPanelTopics");
    if (!actPanel && !topPanel) return;

    // 1. SYNCHRONOUS DOM-FIRST RENDERING:
    // Extract everything currently in the DOM so the user sees results INSTANTLY with 0ms delay!
    var domData = extractDomActivityAndTopics();
    if (allActivityItems.length === 0 && domData.activities.length > 0) {
      allActivityItems = domData.activities;
    }
    if (allTopicItems.length === 0 && domData.topics.length > 0) {
      allTopicItems = domData.topics;
    }

    // Render immediately from DOM so panels are never empty or stuck at "yükleniyor..."
    renderActivityPanel(allActivityItems);
    renderTopicsPanel(allTopicItems);

    if (blogFeedsLoaded || isFeedFetching) return;
    isFeedFetching = true;

    // 2. ASYNCHRONOUS BLOG-WIDE FEED FETCH (JSONP):
    // Fetch comments across the entire blog and merge with DOM
    fetchBlogFeedJsonp("/feeds/comments/default?max-results=150", function(cmData) {
      isFeedFetching = false;
      if (!cmData || !cmData.feed || !cmData.feed.entry || !cmData.feed.entry.length) {
        blogFeedsLoaded = true;
        renderActivityPanel(allActivityItems);
        renderTopicsPanel(allTopicItems);
        return;
      }

      blogFeedsLoaded = true;
      var cmEntries = cmData.feed.entry;

      function processAndRenderComments(titleMap) {
        titleMap = titleMap || {};
        try {
          var seenCommentIds = {};
          allActivityItems.forEach(function(item) { seenCommentIds[item.commentId] = true; });

          var feedActivities = [];
          var blogTopicsMap = {};
          allTopicItems.forEach(function(top) { blogTopicsMap[top.id] = top; });

          var chronological = cmEntries.slice().reverse();
          chronological.forEach(function(entry) {
            try {
              var rawContent = (entry.content && entry.content.$t) || (entry.summary && entry.summary.$t) || "";
              var cleanTxt = rawContent.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
              if (cleanTxt.indexOf("Bu yorum bir blog yöneticisi tarafından silindi") !== -1) return;

              var idTag = (entry.id && entry.id.$t) || "";
              var commentId = "c" + idTag.split("post-").pop();
              var parentId = null;
              var pageUrl = window.location.pathname;

              if (entry["thr$in-reply-to"] && entry["thr$in-reply-to"].href) {
                pageUrl = entry["thr$in-reply-to"].href;
              }
              (entry.link || []).forEach(function(l) {
                if (l.rel === "alternate" && l.href) pageUrl = l.href;
                if (l.rel === "related" && l.href) {
                  parentId = "c" + l.href.split("/").pop();
                }
              });

              var cleanPath = pageUrl.replace(/^https?:\/\/[^\/]+/i, "").split("?")[0].split("#")[0];
              var pageTitle = titleMap[cleanPath] || formatPageSlug(cleanPath);
              var author = (entry.author && entry.author[0] && entry.author[0].name && entry.author[0].name.$t) || "Ziyaretçi";
              var pubDate = entry.published && entry.published.$t ? new Date(entry.published.$t).toLocaleDateString("tr-TR") : "";
              var isReply = Boolean(parentId && parentId !== commentId);

              var feedAvatar = (entry.author && entry.author[0] && entry.author[0]["gd$image"] && entry.author[0]["gd$image"].src) || "";
              if (!feedAvatar || feedAvatar.indexOf("blank.gif") !== -1 || feedAvatar.indexOf("b16-rounded") !== -1) {
                feedAvatar = getFallbackAvatarSvg(author);
              } else {
                feedAvatar = upgradeAvatarUrl(feedAvatar);
              }

              if (!parentId) {
                if (!blogTopicsMap[commentId]) {
                  var newTopic = {
                    id: commentId,
                    author: author,
                    avatar: feedAvatar,
                    text: cleanTxt.substring(0, 140),
                    date: pubDate,
                    path: cleanPath,
                    pageTitle: pageTitle,
                    replyCount: 0,
                    lastActivityAuthor: author
                  };
                  blogTopicsMap[commentId] = newTopic;
                  allTopicItems.push(newTopic);
                }
              } else if (blogTopicsMap[parentId]) {
                blogTopicsMap[parentId].replyCount++;
                blogTopicsMap[parentId].lastActivityAuthor = author;
              }

              if (!seenCommentIds[commentId]) {
                seenCommentIds[commentId] = true;
                feedActivities.push({
                  commentId: commentId,
                  parentTopicId: parentId || commentId,
                  author: author,
                  avatar: feedAvatar,
                  text: cleanTxt.substring(0, 140),
                  date: pubDate,
                  pageTitle: pageTitle,
                  pageUrl: pageUrl,
                  isReply: isReply
                });
              }
            } catch(e) {}
          });

          if (feedActivities.length > 0) {
            allActivityItems = feedActivities.reverse().concat(allActivityItems);
          }
          renderActivityPanel(allActivityItems);
          renderTopicsPanel(allTopicItems);
        } catch(e) {
          renderActivityPanel(allActivityItems);
          renderTopicsPanel(allTopicItems);
        }
      }

      // Render immediately with available titles
      processAndRenderComments({});

      // Asynchronously enrich with post titles
      try {
        fetchBlogFeedJsonp("/feeds/posts/default?max-results=50", function(postData) {
          if (!postData || !postData.feed || !postData.feed.entry) return;
          var titleMap = {};
          postData.feed.entry.forEach(function(e) {
            var t = (e.title && e.title.$t) || "";
            (e.link || []).forEach(function(l) {
              if (l.rel === "alternate" && l.href && t) {
                var cleanPath = l.href.replace(/^https?:\/\/[^\/]+/i, "").split("?")[0].split("#")[0];
                titleMap[cleanPath] = t;
              }
            });
          });
          processAndRenderComments(titleMap);
        });
      } catch(e) {}
    });
  }

  function syncUrlHashState() {
    var h = window.location.hash || "";
    var fc = document.getElementById("forComments");
    var roots = getRootTopics();

    if (h.indexOf("#topic-") === 0) {
      if (fc) fc.checked = true;
      var tid = h.replace("#topic-", "");
      activeTopicId = tid.indexOf("c") === 0 ? tid : ("c" + tid);
      renderTopicOrListView(null);
    } else if (/^#c\d+$/.test(h)) {
      if (fc) fc.checked = true;
      var cid = h.substring(1);
      window.bttOpenTopicPage(cid, cid);
    } else if (h === "#comment" || h === "#comments" || h === "#Sohbet" || h === "#sohbet" || decodeURIComponent(h) === "#Sohbet" || !h) {
      if (h === "#comments" || h === "#Sohbet" || h === "#sohbet" || decodeURIComponent(h) === "#Sohbet") {
        if (fc) fc.checked = true;
      }
      // If there is only 1 topic, auto-open it directly into topic view so all replies & composer are visible!
      if (roots.length === 1 && !activeTopicId) {
        activeTopicId = roots[0].id;
      }
      renderTopicOrListView(null);
    } else {
      renderTopicOrListView(null);
    }
  }

    // Tab switch listener: instantly render feeds when clicking Son Aktiviteler or Konular
  try {
    document.querySelectorAll('input[name="commentPtf"]').forEach(function(radio) {
      radio.addEventListener("change", function() {
        if (this.id === "iRcmpf-1" || this.id === "iRcmpf-2") {
          loadNativeFeeds();
        }
      });
    });

    // Sekme etiketlerine veya #Sohbet butonuna tıklandığında anında beslemeleri yükle
    document.addEventListener("click", function(ev) {
      var t = ev.target && ev.target.closest && ev.target.closest('label[for="iRcmpf-1"], label[for="iRcmpf-2"], [data-i="iRcmpf-1"], [data-i="iRcmpf-2"], label[for="forComments"], #siSlideSohbet, .ntf-sohbet-link');
      if (t) {
        setTimeout(function() {
          if (typeof loadNativeFeeds === "function") loadNativeFeeds();
          else if (typeof window.bttLoadNativeFeeds === "function") window.bttLoadNativeFeeds();
        }, 30);
      }
    });

    var fcBox = document.getElementById("forComments");
    if (fcBox) {
      fcBox.addEventListener("change", function() {
        if (this.checked) {
          setTimeout(function() {
            if (typeof loadNativeFeeds === "function") loadNativeFeeds();
            else if (typeof window.bttLoadNativeFeeds === "function") window.bttLoadNativeFeeds();
          }, 50);
        }
      });
    }
  } catch (err) {}


  /* ==========================================================================
     Plu$ UI Post Tabs Parser (/tab and [tab] in Blogger Posts)
     ========================================================================== */
  function bttRenderPostTabsHtml(tabs) {
    if (!tabs || tabs.length === 0) return "";
    var uid = "ptab-" + Math.random().toString(36).substring(2, 8);
    var inputs = "", labels = "", bodies = "";
    tabs.forEach(function(t, idx) {
      var num = idx + 1;
      var tid = uid + "-" + num;
      var isChecked = idx === 0 ? " checked=''" : "";
      inputs += "<input id='" + tid + "' type='radio' name='" + uid + "'" + isChecked + ">";
      var safeTitle = (t.title || ("Sekme " + num)).replace(/'/g, "&#39;").replace(/"/g, "&quot;");
      labels += "<label for='" + tid + "' data-text='" + safeTitle + "' onclick='window.bttClickPlusTab(this," + idx + ",event)'></label>";
      var displayStyle = idx === 0 ? "display:block;" : "display:none;";
      bodies += "<div class='tabC-" + num + "' style='" + displayStyle + "padding:16px 18px;'>" + t.body + "</div>";
    });
    return "<div class='tabs stick btt-post-tabs' onclick='event.stopPropagation()'>" + inputs + "<div>" + labels + "</div>" + bodies + "</div>";
  }

  function bttParsePostTabsInHtml(html) {
    if (!html) return html;

    // 1. Bracket syntax: [tabs] ... [tab title="..."]...[/tab] ... [/tabs] or consecutive [tab...]...[/tab]
    var bracketPattern = /(?:\[tabs\])?((?:\s*\[tab(?:\s+title=[\"\']?([^\]\"\']+)[\"\']?|\s+([^\]]+))?\]([\s\S]*?)\[\/tab\]\s*)+)(?:\[\/tabs\])?/gi;
    html = html.replace(bracketPattern, function(match, inner) {
      var subPattern = /\[tab(?:\s+title=[\"\']?([^\]\"\']+)[\"\']?|\s+([^\]]+))?\]([\s\S]*?)\[\/tab\]/gi;
      var tabs = [];
      var sub;
      while ((sub = subPattern.exec(inner)) !== null) {
        var title = sub[1] || sub[2] || ("Sekme " + (tabs.length + 1));
        var body = (sub[3] || "").trim();
        tabs.push({ title: title.trim(), body: body });
      }
      if (tabs.length === 0) return match;
      return bttRenderPostTabsHtml(tabs);
    });

    // 2. Case A: <p>/tab ...</p> or <div>/tab ...</div>
    var blockSlashPattern = /<(p|div)[^>]*>\s*\/(?:tab|tabs)\s+([\s\S]+?)<\/\1>/gi;
    html = html.replace(blockSlashPattern, function(match, tag, content) {
      content = (content || "").trim();
      var parts = content.split("|");
      var tabs = [];
      parts.forEach(function(p) {
        p = p.trim();
        if (!p) return;
        var cIdx = p.indexOf(":");
        if (cIdx !== -1) {
          tabs.push({ title: p.substring(0, cIdx).trim(), body: p.substring(cIdx + 1).trim() });
        } else {
          tabs.push({ title: "Sekme " + (tabs.length + 1), body: p });
        }
      });
      if (tabs.length === 0) return match;
      return bttRenderPostTabsHtml(tabs);
    });

    // 3. Case B: Standalone line /tab ...
    var lineSlashPattern = /(?:^|\n|\r|<br\s*\/?>)\s*\/(?:tab|tabs)\s+([^\r\n]+)/gi;
    html = html.replace(lineSlashPattern, function(match, content) {
      content = (content || "").trim();
      var parts = content.split("|");
      var tabs = [];
      parts.forEach(function(p) {
        p = p.trim();
        if (!p) return;
        var cIdx = p.indexOf(":");
        if (cIdx !== -1) {
          tabs.push({ title: p.substring(0, cIdx).trim(), body: p.substring(cIdx + 1).trim() });
        } else {
          tabs.push({ title: "Sekme " + (tabs.length + 1), body: p });
        }
      });
      if (tabs.length === 0) return match;
      return bttRenderPostTabsHtml(tabs);
    });

    return html;
  }

  function bttParsePostTabs() {
    var posts = document.querySelectorAll(".pS, .post-body, #postBody, .entry-content, article.post, .post-auto-tabs > .tabC-2");
    if (!posts || !posts.length) return;
    posts.forEach(function(post) {
      if (post.getAttribute("data-btt-tabs-parsed")) return;
      var rawHtml = post.innerHTML;
      if (rawHtml.indexOf("/tab") === -1 && rawHtml.indexOf("[tab") === -1) return;

      post.setAttribute("data-btt-tabs-parsed", "true");
      post.innerHTML = bttParsePostTabsInHtml(rawHtml);
    });
  }

  window.bttParsePostTabs = bttParsePostTabs;

  function runAll() {
    try { bttParsePostTabs(); } catch (e) { console.error(e); }
    try { enhanceCommentsDOM(); } catch (e) { console.error(e); }
    try { enhanceComposerSlashRow(); } catch (e) { console.error(e); }
    try { loadNativeFeeds(); } catch (e) { console.error(e); }
    try { syncUrlHashState(); } catch (e) { console.error(e); }
  }

  window.addEventListener("hashchange", syncUrlHashState);
  window.addEventListener("popstate", syncUrlHashState);
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", runAll);
  } else {
    runAll();
  }
  setTimeout(runAll, 80);
  setTimeout(runAll, 450);
})();


