/*-- VTrick Enhanced Stats --*/
function vtrickUpdateStats(json){
  var n=parseInt(json.feed.openSearch$totalResults.$t)||0;
  var st=document.getElementById('vtrick-stat-topics');
  if(st)st.textContent=n;
  var s=document.createElement('script');
  s.src='/feeds/comments/summary?alt=json-in-script&callback=vtrickUpdateCommentCount';
  document.body.appendChild(s);
}
function vtrickUpdateCommentCount(json){
  var n=parseInt(json.feed.openSearch$totalResults.$t)||0;
  var sc=document.getElementById('vtrick-stat-comments');
  if(sc)sc.textContent=n;
}

/*-- VTrick Enhanced Active Users --*/
var vtrickColors=['#1a73e8','#e91e63','#9c27b0','#00897b','#ff9800','#795548','#607d8b','#f44336'];
function vtrickShowActiveUsers(json){
  var c=document.getElementById('vtrick-active-users');
  if(!c)return;
  var entries=json.feed.entry||[];
  var users={};
  for(var i=0;i<entries.length;i++){
    var e=entries[i];
    if(e.author&&e.author[0]){
      var name=e.author[0].name.$t;
      var avatar=e.author[0].gd$image?e.author[0].gd$image.src:'';
      if(!users[name])users[name]=avatar;
    }
  }
  var names=Object.keys(users);
  var s='';
  for(var j=0;j<Math.min(10,names.length);j++){
    var color=vtrickColors[j%vtrickColors.length];
    var initial=names[j].charAt(0).toUpperCase();
    var img=users[names[j]];
    s+='<div style="width:32px;height:32px;border-radius:50%;background:'+color+';display:flex;align-items:center;justify-content:center;color:#fff;font-size:12px;font-weight:700;position:relative;cursor:pointer;transition:transform .2s" title="'+names[j]+'">'+(img?'<img src="'+img+'" style="width:100%;height:100%;border-radius:50%;object-fit:cover"/>':initial)+'<span style="position:absolute;bottom:0;right:0;width:8px;height:8px;background:#51cf66;border-radius:50%;border:2px solid #fff"></span></div>';
  }
  c.innerHTML=s;
  var su=document.getElementById('vtrick-stat-users');
  if(su)su.textContent=names.length;
}

/*-- VTrick Enhanced Tags --*/
function vtrickShowTags(json){
  var c=document.getElementById('vtrick-tags-cloud');
  if(!c)return;
  var labels=json.feed.category||[];
  if(labels.length===0)return;
  labels.sort(function(a,b){return parseInt(b.$t)-parseInt(a.$t)});
  var s='';
  for(var i=0;i<Math.min(12,labels.length);i++){
    s+='<a href="/search/label/'+encodeURIComponent(labels[i].term)+'" style="padding:4px 12px;border-radius:20px;font-size:12px;background:rgba(26,115,232,.05);color:#959595;text-decoration:none;transition:all .2s">'+labels[i].term+'</a>';
  }
  c.innerHTML=s;
}

/*-- VTrick Newsletter --*/
document.querySelectorAll('.vtrick-newsletter button').forEach(function(btn){
  btn.addEventListener('click',function(){
    var input=this.previousElementSibling;
    if(input&&input.value){alert('Teşekkürler! Abone oldunuz.');input.value=''}
  });
});

/*-- VTrick Load Data --*/
(function(){
  var s1=document.createElement('script');s1.src='/feeds/posts/summary?alt=json-in-script&callback=vtrickUpdateStats&max-results=0';document.body.appendChild(s1);
  var s2=document.createElement('script');s2.src='/feeds/posts/summary?alt=json-in-script&callback=vtrickShowActiveUsers&max-results=25';document.body.appendChild(s2);
  var s3=document.createElement('script');s3.src='/feeds/posts/summary?alt=json-in-script&callback=vtrickShowTags&max-results=0';document.body.appendChild(s3);
})();

