    target: {
      home:    'a.headT[href], .hmLnk[href], a[href="/"]',
      menu:    'label.tNav[for="offNav"], label[for="offNav"]',
      search:  '.srchW .i, .headS .i, .srchF .i, input[name="q"], input[type="search"]',
      main:    'main.blogB, main, [role="main"], .blogB, .mainB',
      cmBtn:   '.cmBtn, label[for="forComments"]',
      cmBox:   '#forComments',
      cmPanel: '.fixL, #comment-blogger',
      newer:   '#pager a.n[href], #blog-pager .nwLnk[href], a[rel="next"], .blog-pager-newer-link',
      older:   '#pager a.o[href], #blog-pager .olLnk[href], a[rel="previous"], a[rel="prev"], .blog-pager-older-link',
      theme:   'label[for="offMode"], .tMode',
      top:     'button.tTb'
