    if (dir === 'left') {
      if (r.right > f.left - 2) return null;
      along = f.left - r.right;
      cross = alignGap(f, r, 'y');
    } else if (dir === 'right') {
      if (r.left < f.right - 2) return null;
      along = r.left - f.right;
      cross = alignGap(f, r, 'y');
    } else if (dir === 'up') {
      if (r.bottom > f.top - 2) return null;
      along = f.top - r.bottom;
      cross = alignGap(f, r, 'x');
    } else {
      if (r.top < f.bottom - 2) return null;
