      var el = list[i];
      if (el === from) continue;
      var s = score(el.getBoundingClientRect(), f, dir);
      if (s !== null && s < bestScore) { bestScore = s; best = el; }
    }
    /* İkinci geçiş: geniş kutularda (chatbox, yan panel formu vb.) kenar çakışması varsa merkez noktasına göre strictly o yöndeki en yakın öğeyi seç */
    if (!best) {
      var fcx = f.left + f.width / 2;
      var fcy = f.top + f.height / 2;
      var bestCenterScore = Infinity;
      for (var j = 0; j < list.length; j++) {
