        var primary = 0, secondary = 0;
        if (dir === 'left' && dx < -8) { validDir = true; primary = -dx; secondary = Math.abs(dy); }
        else if (dir === 'right' && dx > 8) { validDir = true; primary = dx; secondary = Math.abs(dy); }
        else if (dir === 'up' && dy < -8) { validDir = true; primary = -dy; secondary = Math.abs(dx); }
        else if (dir === 'down' && dy > 8) { validDir = true; primary = dy; secondary = Math.abs(dx); }
