   *  GLOBAL TV ODAK SEÇİM NOKTASI (#tv-focus-dot) - HER ŞEYİN ÜZERİNDE
   * ------------------------------------------------------------------ */
  var focusDotEl = null;

  function ensureFocusDot() {
    if (!focusDotEl) {
      focusDotEl = doc.getElementById('tv-focus-dot');
      if (!focusDotEl) {
        focusDotEl = doc.createElement('div');
        focusDotEl.id = 'tv-focus-dot';
        (doc.body || root).appendChild(focusDotEl);
      }
    }
    return focusDotEl;
  }

  function updateFocusDot(el) {
    var dot = ensureFocusDot();
    if (S.pointer || !el || !visible(el) || el === doc.body || el === doc.documentElement) {
      dot.classList.remove('on');
      return;
    }
    var r = el.getBoundingClientRect();
