    mark(el, true);
    /* Chatbox / input alanlarının üstüne gezinerek gelindiğinde otomatik klavye kilidine girmesin; sadece Enter/OK ile yazı moduna girsin */
    if (editable(el)) {
      if (doc.activeElement && doc.activeElement !== doc.body && doc.activeElement !== el) {
        try { doc.activeElement.blur(); } catch (e) {}
      }
    } else {
      focusEl(el);
