      var dy = (dir === 'up' ? -300 : dir === 'down' ? 300 : 0);
      var dx = (dir === 'left' ? -260 : dir === 'right' ? 260 : 0);
      try { win.scrollBy({ top: dy, left: dx, behavior: 'smooth' }); } catch (e) { win.scrollBy(dx, dy); }

      win.setTimeout(function() {
        buildList(true);
        var nextEl = from ? findNext(dir, from) : firstVisible();
        if (nextEl && nextEl !== from) pick(nextEl);
      }, 100);
      return true;
    }
  }

  /* ------------------------------------------------------------------ *
   *  6. SEÇME / GERİ
   * ------------------------------------------------------------------ */
  function activate(fromPad) {
    var el = S.current;
    if (!el) { move('down'); return false; }
    if (!doc.contains(el)) { S.current = null; return false; }
    focusEl(el);
    if (editable(el)) { announce('Düzenleme alanı odaklandı.'); return true; }
    var tag = el.tagName;
    /* Bağlantı, düğme ve özet öğelerinde Enter klavyeden zaten tetikler;
       kumandayken eksik kalmaması için burada tıklatılır. */
    if (tag === 'A' || tag === 'BUTTON' || tag === 'SUMMARY') {
      if (fromPad) el.click();
    } else {
      el.click();
    }
    announce('Seçildi: ' + (label(el) || 'öğe'));
    return true;
  }

  function fireChange(el) {
    try {
      var ev = doc.createEvent('HTMLEvents');
      ev.initEvent('change', true, false);
      el.dispatchEvent(ev);
    } catch (e) { /* yoksay */ }
  }

  /* Açık katmanı / menüyü kapat (GENİŞLETİLDİ) */
  function closeOverlay() {
    /* 0) Gelişmiş Arama Modalını (Ctrl+F) Kapat */
    var advM = doc.getElementById('advSearchModal');
    if (advM && advM.classList.contains('is-open')) {
      if (typeof win.closeAdvSearch === 'function') win.closeAdvSearch();
      else advM.classList.remove('is-open');
      announce('Arama kapatıldı.');
      return true;
    }
    /* 0b) Bize Ulaşın (#ContactForm2) Kapat */
    var cfSpot = doc.getElementById('ContactForm2');
    if (cfSpot && cfSpot.classList.contains('cf-spotlight')) {
      var cfCls = cfSpot.querySelector('.cf-close-btn');
      if (cfCls) cfCls.click();
      announce('İletişim formu kapatıldı.');
      return true;
    }
    /* 0c) Yorumlar / Sohbet Çekmecesini Kapat */
    var fcBox = doc.getElementById('forComments');
    if (fcBox && fcBox.checked) {
      if (typeof win.bttIsTopicPage === 'function' && win.bttIsTopicPage()) {
        if (typeof win.bttBackToFeed === 'function') { win.bttBackToFeed(); return true; }
      }
      fcBox.checked = false;
      fireChange(fcBox);
      announce('Sohbet kapatıldı.');
      return true;
    }
    /* 1) Lightbox, video modal, dialog tarzı öğeler */
    var ols = qsa('.fsMediaModal, #fsMediaModal, .zmImg.s, dialog[open], [role="dialog"][aria-modal="true"], .tNtf, .wBkm, .wTrans, .fsMediaModal.active');
    for (var i = 0; i < ols.length; i++) {
      var o = ols[i];
      if (o.classList && o.classList.contains('is-floating')) continue;
      if (!visible(o)) continue;
      var cb = qs('.fCls, .x, .c, .fsClose, [aria-label*="lose" i], [aria-label*="apat" i], [aria-label*="kapat" i], button', o);
      if (cb && visible(cb)) cb.click();
      else { o.classList.remove('active', 'show', 'open', 'fsShow'); }
      announce('Ekran kapatıldı.');
      return true;
    }
    /* 2) Tema mekanizması: gizli onay kutusu ile açılan paneller */
    var boxes = qsa('input[type="checkbox"]:checked');
    for (var j = 0; j < boxes.length; j++) {
      var box = boxes[j];
      if (!box.id || CFG.keepChecked.indexOf(box.id) !== -1) continue;
      var lab = qs('label[for="' + escAttr(box.id) + '"]');
      if (!lab || !visible(lab)) continue;
      box.checked = false;
      fireChange(box);
      announce('Menü kapatıldı.');
      return true;
    }
    /* 3) details ile açılan bölümler */
    var det = qs('details[open]');
    if (det) {
      det.open = false;
      announce('Kapatıldı.');
      return true;
    }
    return false;
  }

  function goBack() {
    if (S.hud && has(S.hud, 'on')) { closeHelp(); return true; }
    if (closeOverlay()) return true;
    var a = doc.activeElement;
    if (a && a !== doc.body && a !== root) {
      a.blur();
      if (S.current) { mark(S.current, false); S.current = null; }
      announce('Odak kaldırıldı.');
      return true;
    }
    return false;
  }

  /* ------------------------------------------------------------------ *
   *  7. KISAYOLLAR
   * ------------------------------------------------------------------ */
  function openSearch() {
    var el = qs(CFG.target.search);
    if (!el) { announce('Arama alanı bulunamadı.'); return false; }
    el.focus();
    try { el.select(); } catch (e) { /* yoksay */ }
    if (!has(el, 'tv-nav-focus')) mark(el, true);
    S.current = el;
    updateFocusDot(el);
    announce('Arama alanı odaklandı.');
    return true;
  }

  function goHome() {
    var el = qs(CFG.target.home);
    var href = (el && el.getAttribute('href')) ? el.getAttribute('href') : '/';
    if (win.location.pathname + win.location.search === href) {
      win.scrollTo({ top: 0, behavior: reduced ? 'auto' : 'smooth' });
      announce('Zaten ana sayfadasınız.');
      return true;
    }
    win.location.href = href;
    return true;
  }

  function toggleMenu() {
    var el = qs(CFG.target.menu);
    if (!el) { announce('Menü düğmesi bulunamadı.'); return false; }
    el.click();
    var box = el.getAttribute('for') ? doc.getElementById(el.getAttribute('for')) : null;
    announce(box && box.checked ? 'Menü kapatıldı.' : 'Menü açıldı.');
    return true;
  }

  function focusMain() {
    var el = qs(CFG.target.main);
    if (!el) { win.scrollTo({ top: 0, behavior: reduced ? 'auto' : 'smooth' }); return true; }
    if (!visible(el)) { announce('Ana içerik bulunamadı.'); return false; }
    if (el.tabIndex < 0) el.tabIndex = -1; /* programatik odak için */
    focusEl(el);
    scrollTo(el);
    announce('Ana içerik odaklandı.');
    return true;
  }

  function toggleComments() {
    var box = qs(CFG.target.cmBox);
    if (box && box.checked) {
      /* Panel açık: içindeki ilk alana git */
      var panel = qs(CFG.target.cmPanel);
      var field = panel ? qs('textarea, input[type="text"], .cmCo a, button', panel) : null;
      if (field) pick(field);
      else announce('Yorum alanı odaklandı.');
      return true;
    }
    var btn = qs(CFG.target.cmBtn);
    if (btn) { btn.click(); announce('Yorumlar açılıyor.'); return true; }
    var sec = qs('#comment-blogger, .cm');
    if (sec) { pick(sec); announce('Yorumlar odaklandı.'); return true; }
    announce('Yorum alanı bulunamadı.');
    return false;
  }

  function gotoPage(dir) {
    var el = qs(dir > 0 ? CFG.target.older : CFG.target.newer);
    if (el) {
      el.click();
      announce(dir > 0 ? 'Önceki sayfaya gidiliyor.' : 'Sonraki sayfaya gidiliyor.');
      return true;
    }
    var pager = qs('#blog-pager');
    if (pager && visible(pager)) { pick(pager); return true; }
    announce('Sayfa bağlantısı bulunamadı.');
    return false;
  }

  function toggleTheme() {
    var el = qs(CFG.target.theme);
    if (el) { el.click(); announce('Tema değiştirildi.'); return true; }
    announce('Tema düğmesi bulunamadı.');
    return false;
  }

  function toTop() {
    var btn = qs(CFG.target.top);
    if (btn) { btn.click(); return true; }
    win.scrollTo({ top: 0, behavior: reduced ? 'auto' : 'smooth' });
    return true;
  }

  /* ------------------------------------------------------------------ *
   *  8. KISAYOL PENCERESİ
   * ------------------------------------------------------------------ */
  var HUD_ROWS = [
    ['Yön tuşları', 'Gezinme'],
    ['Enter / OK', 'Seç'],
    ['Esc / Geri', 'Kapat, odağı kaldır'],
    ['/  S  F', 'Arama alanını aç'],
    ['H', 'Ana sayfa'],
    ['M', 'Menüyü aç / kapat'],
    ['G', 'Ana içeriğe git'],
    ['C', 'Yorumları aç'],
    ['N / P', 'Sayfa değiştir'],
    ['D', 'Açık / koyu tema'],
    ['T', 'Sayfa başına dön'],
    ['?', 'Bu kısayol listesi']
  ];

  function buildHelp() {
    var hud = doc.createElement('div');
    hud.className = 'tv-nav-hud';
    hud.id = 'tv-nav-hud';
    hud.setAttribute('role', 'dialog');
    hud.setAttribute('aria-modal', 'true');
    hud.setAttribute('aria-labelledby', 'tv-nav-hud-title');

    var rows = '';
    for (var i = 0; i < HUD_ROWS.length; i++) {
      rows += '<tr><th scope="row">' + HUD_ROWS[i][0] + '</th><td>' + HUD_ROWS[i][1] + '</td></tr>';
    }

    hud.innerHTML =
      '<div class="in">' +
        '<div class="hud-head">' +
          '<h2 id="tv-nav-hud-title">TV Kumandası / Oyun Kolu / Klavye</h2>' +
          '<button type="button" class="c hud-close" id="tv-nav-hud-close" aria-label="Kapat">' +
            '<svg class="line" viewBox="0 0 24 24"><path d="M19.0005 4.99988L5.00049 18.9999M5.00049 4.99988L19.0005 18.9999"/></svg>' +
          '</button>' +
        '</div>' +
        '<p class="sub">Bu blogu uzaktan kumanda, oyun kolu veya klavye ile ' +
        'kontrol edebilirsiniz.</p>' +
        '<table class="t"><tbody>' + rows + '</tbody></table>' +
        '<div class="ft">' +
          '<button type="button" class="c hud-close" id="tv-nav-hud-ok" aria-label="Kapat">' +
            '<svg class="line" viewBox="0 0 24 24"><path d="M19.0005 4.99988L5.00049 18.9999M5.00049 4.99988L19.0005 18.9999"/></svg>' +
          '</button>' +
        '</div>' +
      '</div>';

    (doc.body || root).appendChild(hud);

    var closeBtn = doc.getElementById('tv-nav-hud-close');
    if (closeBtn) closeBtn.addEventListener('click', function (ev) { ev.preventDefault(); closeHelp(); });

    var ok = doc.getElementById('tv-nav-hud-ok');
    if (ok) ok.addEventListener('click', function (ev) { ev.preventDefault(); closeHelp(); });

    /* Arkadaki alana tıklanınca kapat */
    hud.addEventListener('click', function (ev) {
      if (ev.target === hud) closeHelp();
    });

    /* Odak kilidi: Tab yalnızca pencere içinde dönsün */
    hud.addEventListener('keydown', function (ev) {
      if (ev.key !== 'Tab') return;
      var f = qsa('button, input, [href], [tabindex]:not([tabindex="-1"])', hud);
      if (!f.length) return;
      var first = f[0], last = f[f.length - 1];
      if (ev.shiftKey && doc.activeElement === first) { ev.preventDefault(); focusEl(last); }
      else if (!ev.shiftKey && doc.activeElement === last) { ev.preventDefault(); focusEl(first); }
    });

    S.hud = hud;
    return hud;
  }

  function openHelp() {
    var hud = S.hud || buildHelp();
    S.hudPrev = doc.activeElement;
    hud.classList.add('on');
    if (doc.body) doc.body.classList.add('tv-hud-open');
    focusEl(doc.getElementById('tv-nav-hud-close') || doc.getElementById('tv-nav-hud-ok'));
    announce('Kısayol listesi açıldı.');
  }

  function closeHelp() {
    var hud = S.hud;
    if (!hud) return false;
    hud.classList.remove('on');
    if (doc.body) doc.body.classList.remove('tv-hud-open');
    if (S.hudPrev && doc.contains(S.hudPrev)) focusEl(S.hudPrev);
    else if (S.current && doc.contains(S.current)) focusEl(S.current);
    announce('Kısayol listesi kapatıldı.');
    return true;
  }

  function toggleHelp() {
    if (S.hud && has(S.hud, 'on')) closeHelp();
    else openHelp();
  }

  /* ------------------------------------------------------------------ *
   *  9. SELAMALAMA TETİKLEYİCİSİ & EVRENSEL ÇEVİRİ KÖPRÜSÜ
   * ------------------------------------------------------------------ */
  var trigger = null;
  var trSyncing = false;

  function initUniversalTranslationBridge() {
    var ATTRS = ['data-label', 'data-text', 'data-time', 'data-show', 'data-hide', 'data-write', 'data-title', 'data-caption', 'data-save', 'data-saved'];
    var hasLetterRe = /[a-zA-ZÀ-ɏЀ-ӿ؀-ۿ぀-ヿ一-鿿]/;

    function attachBridgeNodes(rootEl) {
      if (trSyncing) return;
      var ctx = (rootEl && rootEl.querySelectorAll) ? rootEl : doc;

      /* 1) data-label, data-text, data-time, data-show, data-hide, data-write, data-title, data-caption, data-save, data-saved kullanan tüm öğeler (Slides, Tarih/Son Görülme, Etiketler, Forum, Bookmark/Save butonları vb.) ve .qeL admin butonları */
      var sel = '[data-label],[data-text],[data-time],[data-show],[data-hide],[data-write],[data-title],[data-caption],[data-save],[data-saved],.bM,.tIc,.bm-button,.tBkm,.lbHt .hL > a[aria-label],.qeL > *[title],.qeT[title],.pJmp,.pRm a,.aprW > *[aria-label],.aprW[data-text],.thmW[data-text],.viewAllArticles,.bkmC .n > a';
      var els = [];
      try { els = Array.prototype.slice.call(ctx.querySelectorAll(sel)); } catch (e) {}
      if (rootEl && rootEl.nodeType === 1 && rootEl.matches && rootEl.matches(sel)) els.unshift(rootEl);

      for (var i = 0; i < els.length; i++) {
        var el = els[i];
        if (!el || el.closest('.notranslate')) continue;

        var checkAttrs = ATTRS.slice();
        if (el.matches && el.matches('.lbHt .hL > a[aria-label], .pJmp, .pRm a, .aprW > *[aria-label], .tBkm')) {
          checkAttrs.push('aria-label');
        }
        if (el.matches && el.matches('.qeL > *[title], .qeT[title]')) {
          checkAttrs.push('title');
        }
        if (el.matches && el.matches('.bM, .tIc, .bm-button, [data-save], [data-saved]')) {
          if (checkAttrs.indexOf('data-save') === -1) checkAttrs.push('data-save');
          if (checkAttrs.indexOf('data-saved') === -1) checkAttrs.push('data-saved');
          if (el.hasAttribute('aria-label') && checkAttrs.indexOf('aria-label') === -1) checkAttrs.push('aria-label');
          if (el.hasAttribute('title') && checkAttrs.indexOf('title') === -1) checkAttrs.push('title');
        }

        for (var j = 0; j < checkAttrs.length; j++) {
          var attr = checkAttrs[j];
          var val = el.getAttribute(attr);
          if (!val || !hasLetterRe.test(val)) continue;

          var node = el.querySelector(':scope > .tr-live-node[data-tr-attr="' + attr + '"]');
          if (!node) {
            /* Eski display:none pGrtText varsa kaldır */
            var oldP = el.querySelector('.pGrtText');
            if (oldP) oldP.remove();

            node = doc.createElement('span');
            node.className = 'tr-live-node';
            node.setAttribute('data-tr-attr', attr);
            node.setAttribute('data-tr-orig', val);
            node.textContent = val;
            el.appendChild(node);
          } else {
            /* Tema saate göre data-text değiştirdiyse (örn. postGreeting) ve henüz çeviri aktif değilse kaynağı güncelle */
            var orig = node.getAttribute('data-tr-orig');
            var isTranslated = doc.documentElement.classList.contains('translated-ltr') || doc.documentElement.classList.contains('translated-rtl');
            if (!isTranslated && val !== orig && val === node.textContent) {
              node.setAttribute('data-tr-orig', val);
            } else if (!isTranslated && val !== orig && node.textContent === orig) {
              node.setAttribute('data-tr-orig', val);
              node.textContent = val;
            }
          }
        }
      }
    }

    function syncTranslatedAttributes() {
      if (trSyncing) return;
      trSyncing = true;
      try {
        var isTranslated = doc.documentElement.classList.contains('translated-ltr') || doc.documentElement.classList.contains('translated-rtl');
        var nodes = doc.querySelectorAll('.tr-live-node[data-tr-attr]');
        for (var i = 0; i < nodes.length; i++) {
          var n = nodes[i];
          var p = n.parentElement;
          if (!p) continue;
          var attr = n.getAttribute('data-tr-attr');
          var orig = n.getAttribute('data-tr-orig') || '';
          var hasFont = !!n.querySelector('font');
          var curText = (n.textContent || '').trim();
          var txt = (curText && curText !== orig) ? curText : ((isTranslated || hasFont) ? curText : orig);
          if (attr && txt && p.getAttribute(attr) !== txt) {
            p.setAttribute(attr, txt);
            if (p.matches && p.matches('.bm-button')) {
              var isAdded = p.classList.contains('added');
              if ((!isAdded && attr === 'data-save') || (isAdded && attr === 'data-saved')) {
                p.setAttribute('title', txt);
                p.setAttribute('aria-label', txt);
              }
            }
          }
        }
      } catch (e) {}
      trSyncing = false;
    }

    attachBridgeNodes(doc);
    /* postGreeting dinamik saat metni 20ms sonra güncellendiği için tekrar tara */
    setTimeout(function() { attachBridgeNodes(doc); syncTranslatedAttributes(); }, 120);
    setTimeout(function() { attachBridgeNodes(doc); syncTranslatedAttributes(); }, 800);

    /* Yer İmleri Butonu (.bm-button) Tıklandığında Anlık Title/Aria-Label Senkronizasyonu */
    doc.addEventListener('click', function(ev) {
      var btn = ev.target && ev.target.closest && ev.target.closest('.bm-button');
      if (btn) {
        setTimeout(function() {
          var isAdded = btn.classList.contains('added');
          var sText = isAdded ? (btn.getAttribute('data-saved') || 'Saved') : (btn.getAttribute('data-save') || 'Save');
          if (btn.getAttribute('title') !== sText) btn.setAttribute('title', sText);
          if (btn.getAttribute('aria-label') !== sText) btn.setAttribute('aria-label', sText);
        }, 50);
      }
    }, true);

    try {
      var trObs = new MutationObserver(function(mutations) {
        if (trSyncing) return;
        var needSync = false;
        var needAttach = false;
        for (var i = 0; i < mutations.length; i++) {
          var m = mutations[i];
          if (m.type === 'characterData' || (m.target && m.target.closest && m.target.closest('.tr-live-node'))) {
            needSync = true;
          } else if (m.type === 'childList') {
            if (m.target && (m.target.classList && m.target.classList.contains('tr-live-node') || (m.target.closest && m.target.closest('.tr-live-node')))) {
              needSync = true;
            } else if (m.addedNodes && m.addedNodes.length) {
              needAttach = true;
              needSync = true;
            }
          } else if (m.type === 'attributes' && (m.attributeName === 'data-text' || m.attributeName === 'data-time')) {
            var aName = m.attributeName;
            var aVal = m.target.getAttribute(aName);
            var aNode = m.target.querySelector(':scope > .tr-live-node[data-tr-attr="' + aName + '"]');
            if (aNode && aVal && aNode.getAttribute('data-tr-orig') !== aVal) {
              trSyncing = true;
              aNode.setAttribute('data-tr-orig', aVal);
              aNode.textContent = aVal;
              trSyncing = false;
            }
          } else if (m.type === 'attributes' && m.attributeName === 'class' && m.target && m.target.matches && m.target.matches('.bm-button')) {
            var bBtn = m.target;
            var isAdded = bBtn.classList.contains('added');
            var sText = isAdded ? (bBtn.getAttribute('data-saved') || 'Saved') : (bBtn.getAttribute('data-save') || 'Save');
            if (bBtn.getAttribute('title') !== sText) bBtn.setAttribute('title', sText);
            if (bBtn.getAttribute('aria-label') !== sText) bBtn.setAttribute('aria-label', sText);
          }
        }
        if (needAttach) attachBridgeNodes(doc);
        if (needSync) syncTranslatedAttributes();
      });
      trObs.observe(doc.documentElement, {
        childList: true,
        subtree: true,
        characterData: true,
        attributes: true,
        attributeFilter: ['class', 'lang', 'data-text', 'data-time']
      });
    } catch (e) {}
  }

  function initTrigger() {
    try {
      var _app = localStorage.getItem('PLUS_UI_APPEARANCE');
      if (_app) {
        var _p = JSON.parse(_app);
        if (_p && _p.theme === 11) {
          _p.theme = 0;
          localStorage.setItem('PLUS_UI_APPEARANCE', JSON.stringify(_p));
        }
        if (!_p || !_p.mode) {
          _p = _p || {};
          _p.mode = 'dark';
          localStorage.setItem('PLUS_UI_APPEARANCE', JSON.stringify(_p));
          document.documentElement.classList.remove('lgT');
          document.documentElement.classList.add('drK');
          if (window.PU && window.PU.ui && typeof window.PU.ui.dM === 'function') {
            window.PU.ui.dM();
          }
        }
      } else {
        localStorage.setItem('PLUS_UI_APPEARANCE', JSON.stringify({mode: 'dark'}));
        document.documentElement.classList.remove('lgT');
        document.documentElement.classList.add('drK');
        if (window.PU && window.PU.ui && typeof window.PU.ui.dM === 'function') {
          window.PU.ui.dM();
        }
      }
    } catch(e) {}
    /* Eski fazladan oluşturulan yapay butonlar varsa temizle */
    var oldH = doc.getElementById('tv-header-greeting');
    if (oldH) oldH.remove();
    var oldW = doc.getElementById('tv-greeting-wrap');
    if (oldW) oldW.remove();

    /* İçindekiler (TOC) 48px Yatay Slider Bar Başlatıcı */
    function initPostTocSliderBar() {
      var bar = doc.getElementById('postTocSliderBar');
      var track = doc.getElementById('postTocTrack');
      var dotsWrap = doc.getElementById('postTocDots');
      var postBody = doc.getElementById('postBody');
      if (!bar || !track || !postBody) return;

      function slugifyHeading(text, usedMap) {
        var base = (text || '').trim().toLowerCase()
          .replace(/[&\/\\#,+()$~%.'":*?<>{}]/g, '')
          .replace(/\s+/g, '-') || 'heading';
        var id = base;
        while (doc.getElementById(id) || usedMap[id]) {
          usedMap[base] = (typeof usedMap[base] === 'number') ? usedMap[base] + 1 : 1;
          id = base + '-' + usedMap[base];
        }
        usedMap[id] = 1;
        return id;
      }

      function collectItems() {
        var items = [];
        var tocIn = doc.querySelector('#postToc .tocIn');
        var rootOl = tocIn ? tocIn.querySelector(':scope > ol') : null;
        if (rootOl && rootOl.children.length) {
          function walkOl(olEl, prefix) {
            var idx = 0;
            var ch = olEl.children;
            for (var i = 0; i < ch.length; i++) {
              var li = ch[i];
              if (!li || li.tagName !== 'LI') continue;
              idx++;
              var numStr = prefix ? (prefix + '.' + idx) : (idx + '.');
              var a = li.querySelector(':scope > a');
              if (a) {
                var txt = (a.textContent || '').trim();
                var href = a.getAttribute('href') || '';
                if (txt && href) {
                  items.push({ num: numStr, text: txt, href: href });
                }
              }
              var subOl = li.querySelector(':scope > ol');
              if (subOl) {
                walkOl(subOl, prefix ? (prefix + '.' + idx) : String(idx));
              }
            }
          }
          walkOl(rootOl, '');
        }
        if (!items.length) {
          var rawHeads = postBody.querySelectorAll('h1, h2, h3, h4, h5, h6');
          var usedIds = {};
          var hList = [];
          for (var k = 0; k < rawHeads.length; k++) {
            var h = rawHeads[k];
            if (h.closest('.post-media-slider, .sldW, .cm, #comments, details.toc')) continue;
            var hTxt = (h.textContent || '').trim();
            if (!hTxt) continue;
            hList.push(h);
          }
          var mainIdx = 0;
          var subIdx = 0;
          var minLvl = 6;
          for (var m = 0; m < hList.length; m++) {
            var lv = parseInt(hList[m].tagName.substring(1), 10) || 2;
            if (lv < minLvl) minLvl = lv;
          }
          for (var n = 0; n < hList.length; n++) {
            var el = hList[n];
            var lvl = parseInt(el.tagName.substring(1), 10) || 2;
            if (!el.id) el.id = slugifyHeading(el.textContent, usedIds);
            var numLabel = '';
            if (lvl <= minLvl) {
              mainIdx++;
              subIdx = 0;
              numLabel = mainIdx + '.';
            } else {
              if (mainIdx === 0) mainIdx = 1;
              subIdx++;
              numLabel = mainIdx + '.' + subIdx;
            }
            items.push({ num: numLabel, text: (el.textContent || '').trim(), href: '#' + el.id });
          }
        }
        return items;
      }

      var tocItems = collectItems();
      if (!tocItems.length) return;

      track.innerHTML = '';
      for (var i = 0; i < tocItems.length; i++) {
        var it = tocItems[i];
        var a = doc.createElement('a');
        a.className = 'toc-chip' + (i === 0 ? ' active' : '');
        a.setAttribute('href', it.href);
        a.setAttribute('data-index', String(i));
        var sNum = doc.createElement('span');
        sNum.className = 'toc-chip-num';
        sNum.textContent = it.num;
        var sTxt = doc.createElement('span');
        sTxt.className = 'toc-chip-txt';
        sTxt.textContent = it.text;
        a.appendChild(sNum);
        a.appendChild(sTxt);
        track.appendChild(a);
      }

      var autoTabC2 = postBody.querySelector('.post-auto-tabs > .tabC-2');
      if (autoTabC2 && bar.parentElement !== autoTabC2) {
        autoTabC2.insertBefore(bar, autoTabC2.firstChild);
      }
      bar.removeAttribute('hidden');
      bar.classList.add('is-ready');

      var chips = Array.prototype.slice.call(track.querySelectorAll('.toc-chip'));
      var dots = dotsWrap ? Array.prototype.slice.call(dotsWrap.querySelectorAll('.dot')) : [];

      function setActiveDot(idx) {
        for (var d = 0; d < dots.length; d++) {
          dots[d].classList.toggle('active', d === idx);
        }
      }

      function setActiveChip(idx, scrollTrackOnly) {
        if (!chips.length) return;
        if (idx < 0) idx = chips.length - 1;
        if (idx >= chips.length) idx = 0;
        for (var c = 0; c < chips.length; c++) {
          chips[c].classList.toggle('active', c === idx);
        }
        if (scrollTrackOnly) {
          var targetChip = chips[idx];
          var targetLeft = targetChip.offsetLeft - Math.max(0, (track.clientWidth - targetChip.offsetWidth) / 2);
          track.scrollTo({ left: Math.max(0, targetLeft), behavior: 'smooth' });
        }
      }

      /* Başlık chipine tıklanınca ilgili başlığa yumuşak kaydır */
      track.addEventListener('click', function(ev) {
        var chip = ev.target && ev.target.closest ? ev.target.closest('.toc-chip') : null;
        if (!chip) return;
        ev.preventDefault();
        var tab2Radio = doc.getElementById('tabT-2');
        if (tab2Radio && !tab2Radio.checked) tab2Radio.checked = true;
        var idx = parseInt(chip.getAttribute('data-index') || '0', 10);
        setActiveChip(idx, true);
        var href = chip.getAttribute('href') || '';
        if (href.charAt(0) === '#') {
          var targetId = decodeURIComponent(href.substring(1));
          var targetEl = doc.getElementById(targetId);
          if (targetEl) {
            var headerOffset = 74;
            var rect = targetEl.getBoundingClientRect();
            var topPos = rect.top + (win.pageYOffset || doc.documentElement.scrollTop || 0) - headerOffset;
            win.scrollTo({ top: Math.max(0, topPos), behavior: 'smooth' });
          }
        }
      });

      /* Sağdaki 2 çizgili slider butonları (.panel-slider-dots) ile yatay kaydırma / geçiş */
      if (dotsWrap && dots.length) {
        dotsWrap.addEventListener('click', function(ev) {
          var btn = ev.target && ev.target.closest ? ev.target.closest('.dot') : null;
          if (!btn) return;
          ev.preventDefault();
          ev.stopPropagation();
          var dIdx = parseInt(btn.getAttribute('data-index') || '0', 10);
          var maxScroll = track.scrollWidth - track.clientWidth;
          if (maxScroll > 8) {
            var step = Math.max(160, Math.round(track.clientWidth * 0.65));
            if (dIdx === 1) {
              if (track.scrollLeft >= maxScroll - 8) {
                track.scrollTo({ left: 0, behavior: 'smooth' });
                setActiveDot(0);
              } else {
                track.scrollBy({ left: step, behavior: 'smooth' });
                setActiveDot(1);
              }
            } else {
              if (track.scrollLeft <= 8) {
                track.scrollBy({ left: step, behavior: 'smooth' });
                setActiveDot(1);
              } else {
                track.scrollBy({ left: -step, behavior: 'smooth' });
                setActiveDot(0);
              }
            }
          } else if (chips.length > 1) {
            var curIdx = 0;
            for (var c = 0; c < chips.length; c++) {
              if (chips[c].classList.contains('active')) { curIdx = c; break; }
            }
            var nextIdx = (dIdx === 1) ? (curIdx + 1) % chips.length : (curIdx - 1 + chips.length) % chips.length;
            setActiveChip(nextIdx, true);
            setActiveDot(nextIdx > 0 ? 1 : 0);
          }
        });

        track.addEventListener('scroll', function() {
          var maxScroll = track.scrollWidth - track.clientWidth;
          if (maxScroll > 8) {
            setActiveDot(track.scrollLeft > maxScroll * 0.35 ? 1 : 0);
          }
        }, { passive: true });
      }
    }
    initPostTocSliderBar();
    win.setTimeout(initPostTocSliderBar, 120);

    /* Tüm selamlama butonlarına (.pGV-pager / #postGreeting / #ntfGreetingBtn) tıklama bağla */
    var triggers = qsa('.pGV-pager, #postGreeting, #ntfGreetingBtn, .ntf-greet-btn');
    function syncAllGreetings() {
      var h = (new Date()).getHours();
      var greet = 'Hoş geldiniz';
      if (h < 4) greet = 'İyi uykular';
      else if (h < 12) greet = 'Günaydın';
      else if (h < 17) greet = 'İyi günler';
      else if (h < 22) greet = 'İyi akşamlar';
      else greet = 'İyi geceler';
      var pg = doc.getElementById('postGreeting');
      if (pg && pg.getAttribute('data-text')) {
        greet = pg.getAttribute('data-text');
      }
      var ng = doc.getElementById('ntfGreetingText');
      if (ng) {
        ng.setAttribute('data-text', greet);
      }
    }
    syncAllGreetings();
    win.setTimeout(syncAllGreetings, 250);
    for (var i = 0; i < triggers.length; i++) {
      (function(el) {
        if (el.getAttribute('data-hud-bound')) return;
        el.setAttribute('data-hud-bound', '1');
        el.style.cursor = 'pointer';
        el.addEventListener('click', function(ev) {
          ev.preventDefault();
          ev.stopPropagation();
          toggleHelp();
        });
        el.addEventListener('keydown', function(ev) {
          if (ev.key === 'Enter' || ev.key === ' ' || ev.key === 'NumpadEnter') {
            ev.preventDefault();
            ev.stopPropagation();
            toggleHelp();
          }
        });
      })(triggers[i]);
    }

    initUniversalTranslationBridge();
  }
  function isAfternoon() {
    try {
      var h = (new Date()).getHours();
      return h >= 12 && h < 18;
    } catch (e) { return false; }
  }

  /* ------------------------------------------------------------------ *
   *  10. OYUN KOLU DESTEĞİ (GELİŞTİRİLDİ)
   * ------------------------------------------------------------------ */
  /* Esnek buton haritası - farklı kontroller için */
  var PAD_MAP = {
    standard: { ok:0, back:1, search:2, home:3, prev:4, next:5, x:2, y:3, lb:4, rb:5, lt:6, rt:7, select:8, start:9, l3:10, r3:11, up:12, down:13, left:14, right:15, home:16 },
    xbox:     { ok:0, back:1, search:2, home:3, prev:4, next:5, x:2, y:3, lb:4, rb:5, lt:6, rt:7, select:8, start:9, l3:10, r3:11, up:12, down:13, left:14, right:15, home:16 },
    ps:       { ok:1, back:0, search:3, home:16, prev:4, next:5, x:3, y:2, lb:4, rb:5, lt:6, rt:7, select:8, start:9, l3:10, r3:11, up:12, down:13, left:14, right:15, home:16 },
    nintendo: { ok:1, back:0, search:3, home:16, prev:4, next:5, x:3, y:2, lb:4, rb:5, lt:6, rt:7, select:8, start:9, l3:10, r3:11, up:12, down:13, left:14, right:15, home:16 }
  };

  function detectPadLayout(gp) {
    var id = (gp.id || '').toLowerCase();
    if (id.indexOf('playstation') !== -1 || id.indexOf('dualshock') !== -1 || id.indexOf('dualsense') !== -1) return 'ps';
    if (id.indexOf('nintendo') !== -1 || id.indexOf('pro controller') !== -1 || id.indexOf('joy-con') !== -1) return 'nintendo';
    return 'standard';
  }

  var currentPadLayout = 'standard';

  function getPadBtn(gp, action) {
    var layout = PAD_MAP[currentPadLayout] || PAD_MAP.standard;
    return layout[action];
  }

  function padFire(id, fn) {
    var now = Date.now();
    var h = S.held[id];
    if (!h) {                 /* ilk basış: anında tepki ver */
      S.held[id] = { t0: now, last: now };
      fn();
      return;
    }
    if (now - h.t0 >= CFG.padDelay && now - h.last >= CFG.padRepeat) {
      h.last = now;
      fn();
    }
  }


  /* ------------------------------------------------------------------ *
   *  GOOGLE DOT SANAL FARE İMLECİ (VIRTUAL CURSOR) - HER ŞEYİN ÜZERİNDE
   * ------------------------------------------------------------------ */
  var dotEl = null;
  var dotX = win.innerWidth / 2;
  var dotY = win.innerHeight / 2;
  var dotVisible = false;
  var dotTarget = null;
  var dotSpeed = 18;

  function ensureDot() {
    if (!dotEl) {
      dotEl = doc.getElementById('tv-virtual-cursor');
      if (!dotEl) {
        dotEl = doc.createElement('div');
        dotEl.id = 'tv-virtual-cursor';
        (doc.body || root).appendChild(dotEl);
      }
    }
    return dotEl;
  }

  function updateDot(dx, dy) {
    var el = ensureDot();
    if (!dotVisible) {
      dotVisible = true;
      el.classList.add('active');
    }

    var vw = win.innerWidth;
    var vh = win.innerHeight;

    dotX = Math.max(10, Math.min(vw - 10, dotX + dx));
    dotY = Math.max(10, Math.min(vh - 10, dotY + dy));

    el.style.left = dotX + 'px';
    el.style.top = dotY + 'px';

    var target = doc.elementFromPoint(dotX, dotY);

    /* Fixed / yüzen kontrollerin (float menü, yukarı kaydır vb.) üstündeyken kenar kaydırmayı durdur */
    var isFixedTarget = false;
    if (target) {
      try {
        var cs = win.getComputedStyle ? win.getComputedStyle(target) : null;
        if (cs && (cs.position === 'fixed' || cs.position === 'sticky')) isFixedTarget = true;
        if (target.closest && target.closest('.tTb, .cta-container, .fixL, .headS, #fsMediaModal, [style*="fixed"]')) isFixedTarget = true;
      } catch (e) {}
    }

    if (!isFixedTarget) {
      var edgeMargin = 25;
      var scrollAmt = 12;
      if (dotY < edgeMargin) win.scrollBy(0, -scrollAmt);
      else if (dotY > vh - edgeMargin) win.scrollBy(0, scrollAmt);
    }

    if (target) {
      var clickable = target.closest('a, button, input, textarea, select, label, summary, [role="button"], .zmVideoBtn, .zmImg, .fsNavBtn, .fsClose, [tabindex]:not([tabindex="-1"])');
      if (clickable) {
        if (dotTarget !== clickable) {
          dotTarget = clickable;
          el.classList.add('hovering-link');
        }
      } else {
        if (dotTarget) {
          dotTarget = null;
          el.classList.remove('hovering-link');
        }
      }
    }
  }

  function clickDot() {
    var el = ensureDot();
    el.classList.add('clicking');
    setTimeout(function() { el.classList.remove('clicking'); }, 150);

    var target = doc.elementFromPoint(dotX, dotY);
    if (target) {
      var clickable = target.closest('a, button, input, textarea, select, label, summary, [role="button"], .zmVideoBtn, .zmImg, .fsNavBtn, .fsClose, [tabindex]:not([tabindex="-1"])') || target;
      if (clickable) {
        if (typeof clickable.click === 'function') clickable.click();
        else {
          var evt = new MouseEvent('click', { bubbles: true, cancelable: true, view: win });
          clickable.dispatchEvent(evt);
        }
        if (typeof clickable.focus === 'function') {
          try { clickable.focus({ preventScroll: true }); } catch (e) { clickable.focus(); }
        }
      }
    }
  }

  function pollPad(gp) {
    if (!gp || !gp.connected) return;
    currentPadLayout = detectPadLayout(gp);
    var b = gp.buttons || [];
    var ax = gp.axes || [];
    var live = [];

    function btn(i, id, fn) {
      if (i === undefined || i === null) return;
      var x = b[i];
      if (x && (x.pressed || x.value > 0.5)) { live.push(id); padFire(id, fn); }
    }

    var okBtn = getPadBtn(gp, 'ok');
    var backBtn = getPadBtn(gp, 'back');
    var helpBtn = getPadBtn(gp, 'select');
    var menuBtn = getPadBtn(gp, 'start');
    var homeBtn = getPadBtn(gp, 'home');

    var lx = ax[0] || 0, ly = ax[1] || 0;
    var rx = ax[2] || 0, ry = ax[3] || 0;

    // Aktif Bağlamı Belirle (Context Awareness)
    var advModal = doc.getElementById('advSearchModal');
    var isSearchOpen = advModal && advModal.classList.contains('is-open');

    var forComments = doc.getElementById('forComments');
    var isCommentsOpen = forComments && forComments.checked;

    /* ------------------------------------------------------------------
       DURUM 1: Ctrl+F Gelişmiş Arama Modalı Açıkken Gamepad Kontrolleri
       ------------------------------------------------------------------ */
    if (isSearchOpen) {
      // D-Pad Yukarı veya Sol Analog Yukarı: Önceki Arama Sonucu
      if (ly < -CFG.deadzone) {
        live.push('pad-up');
        padFire('pad-up', function () { if (win.advPrevResult) win.advPrevResult(); });
      }
      btn(PAD_MAP.standard.up, 'pad-up', function () { if (win.advPrevResult) win.advPrevResult(); });

      // D-Pad Aşağı veya Sol Analog Aşağı: Sonraki Arama Sonucu
      if (ly > CFG.deadzone) {
        live.push('pad-down');
        padFire('pad-down', function () { if (win.advNextResult) win.advNextResult(); });
      }
      btn(PAD_MAP.standard.down, 'pad-down', function () { if (win.advNextResult) win.advNextResult(); });

      // Sağ Analog (Right Stick RX): Kısayollar ve Arama Şeridini Akıcı Analog Kaydır
      if (Math.abs(rx) > CFG.deadzone) {
        if (win.advScrollShortcuts) win.advScrollShortcuts(rx * 14);
      }

      // D-Pad Sol veya Sol Analog Sol: Kısayol Şeridini Sola Kaydır
      if (lx < -CFG.deadzone) {
        live.push('pad-left');
        padFire('pad-left', function () {
          if (win.advScrollShortcuts) win.advScrollShortcuts(-150);
        });
      }
      btn(PAD_MAP.standard.left, 'pad-left', function () {
        if (win.advScrollShortcuts) win.advScrollShortcuts(-150);
      });

      // D-Pad Sağ veya Sol Analog Sağ: Kısayol Şeridini Sağa Kaydır
      if (lx > CFG.deadzone) {
        live.push('pad-right');
        padFire('pad-right', function () {
          if (win.advScrollShortcuts) win.advScrollShortcuts(150);
        });
      }
      btn(PAD_MAP.standard.right, 'pad-right', function () {
        if (win.advScrollShortcuts) win.advScrollShortcuts(150);
      });

      // LB / RB: Kısayol Şeridinde Hızlı Sağa-Sola Kaydırma (160px)
      btn(PAD_MAP.standard.prev, 'pad-lb', function () {
        if (win.advScrollShortcuts) win.advScrollShortcuts(-160);
      });
      btn(PAD_MAP.standard.next, 'pad-rb', function () {
        if (win.advScrollShortcuts) win.advScrollShortcuts(160);
      });

      // LT / RT: Arama Motorları (Google AI, Google, DeepL, Yandex, vb.) Arasında Geçiş
      btn(PAD_MAP.standard.lt, 'pad-lt', function () { if (win.advPrevPill) win.advPrevPill(); });
      btn(PAD_MAP.standard.rt, 'pad-rt', function () { if (win.advNextPill) win.advNextPill(); });

      // Buton A (0): Seçili Sonucu Aç / Ara
      btn(okBtn, 'pad-ok', function () { if (win.advExecuteCurrent) win.advExecuteCurrent(); });

      // Buton B (1) veya Y (3): Aramayı Kapat
      btn(backBtn, 'pad-back', function () { if (win.closeAdvSearch) win.closeAdvSearch(); });
      btn(PAD_MAP.standard.y, 'pad-y', function () { if (win.closeAdvSearch) win.closeAdvSearch(); });

      for (var k in S.held) {
        if (live.indexOf(k) === -1) delete S.held[k];
      }
      return;
    }

    /* ------------------------------------------------------------------
       DURUM 2: Yorumlar / Sohbet & /Komutlar Açıkken Gamepad Kontrolleri
       ------------------------------------------------------------------ */
    if (isCommentsOpen) {
      // D-Pad Yukarı: Yorum / Konu Listesinde Yukarı Gezin
      btn(PAD_MAP.standard.up, 'pad-up', function () {
        var items = doc.querySelectorAll('.btt-topic-card, #cmHolder > li.c, .cmCo, .btt-channel-btn');
        if (items.length) {
          var cur = doc.querySelector('.btt-topic-card.btt-topic-focused, #cmHolder > li.c:focus-within');
          var cIdx = cur ? Array.prototype.indexOf.call(items, cur) : 0;
          var nIdx = Math.max(cIdx - 1, 0);
          if (cur) cur.classList.remove('btt-topic-focused');
          items[nIdx].classList.add('btt-topic-focused');
          items[nIdx].scrollIntoView({ behavior: 'smooth', block: 'nearest' });
          var fEl = items[nIdx].querySelector('a, button, [tabindex="0"]') || items[nIdx];
          if (fEl && fEl.focus) fEl.focus({ preventScroll: true });
        } else {
          win.scrollBy({ top: -140, behavior: 'smooth' });
        }
      });

      // D-Pad Aşağı: Yorum / Konu Listesinde Aşağı Gezin
      btn(PAD_MAP.standard.down, 'pad-down', function () {
        var items = doc.querySelectorAll('.btt-topic-card, #cmHolder > li.c, .cmCo, .btt-channel-btn');
        if (items.length) {
          var cur = doc.querySelector('.btt-topic-card.btt-topic-focused, #cmHolder > li.c:focus-within');
          var cIdx = cur ? Array.prototype.indexOf.call(items, cur) : -1;
          var nIdx = Math.min(cIdx + 1, items.length - 1);
          if (cur) cur.classList.remove('btt-topic-focused');
          items[nIdx].classList.add('btt-topic-focused');
          items[nIdx].scrollIntoView({ behavior: 'smooth', block: 'nearest' });
          var fEl = items[nIdx].querySelector('a, button, [tabindex="0"]') || items[nIdx];
          if (fEl && fEl.focus) fEl.focus({ preventScroll: true });
        } else {
          win.scrollBy({ top: 140, behavior: 'smooth' });
        }
      });

      // D-Pad Sol / Sağ: /Komutlar Çipleri & Kanal Butonları Arasında Gezin
      btn(PAD_MAP.standard.left, 'pad-left', function () {
        var chips = doc.querySelectorAll('#bttSlashRow .btt-slash-chip, .btt-channel-btn');
        if (chips.length) {
          var focused = doc.activeElement && doc.activeElement.closest && doc.activeElement.closest('#bttSlashRow .btt-slash-chip, .btt-channel-btn');
          var idx = Array.prototype.indexOf.call(chips, focused);
          var nextIdx = (idx - 1 + chips.length) % chips.length;
          chips[nextIdx].focus();
        }
      });
      btn(PAD_MAP.standard.right, 'pad-right', function () {
        var chips = doc.querySelectorAll('#bttSlashRow .btt-slash-chip, .btt-channel-btn');
        if (chips.length) {
          var focused = doc.activeElement && doc.activeElement.closest && doc.activeElement.closest('#bttSlashRow .btt-slash-chip, .btt-channel-btn');
          var idx = Array.prototype.indexOf.call(chips, focused);
          var nextIdx = (idx + 1) % chips.length;
          chips[nextIdx].focus();
        }
      });

      // LB / RB: Guilded Kanal Şeridi Geçişi (#tümü, #sohbet, #duyurular, #yardım, #kaynaklar)
      btn(PAD_MAP.standard.prev, 'pad-lb', function () {
        var chs = doc.querySelectorAll('.btt-channel-btn');
        if (chs.length) {
          var act = doc.querySelector('.btt-channel-btn.active');
          var idx = act ? Array.prototype.indexOf.call(chs, act) : 0;
          var pIdx = (idx - 1 + chs.length) % chs.length;
          chs[pIdx].click();
        }
      });
      btn(PAD_MAP.standard.next, 'pad-rb', function () {
        var chs = doc.querySelectorAll('.btt-channel-btn');
        if (chs.length) {
          var act = doc.querySelector('.btt-channel-btn.active');
          var idx = act ? Array.prototype.indexOf.call(chs, act) : 0;
          var nIdx = (idx + 1) % chs.length;
          chs[nIdx].click();
        }
      });

      // Buton A (0): Seçili Konuyu Aç / Çipi Ekle / Yanıtla
      btn(okBtn, 'pad-ok', function () {
        var actEl = doc.activeElement;
        var topFoc = doc.querySelector('.btt-topic-card.btt-topic-focused');
        if (topFoc && (!actEl || actEl === doc.body || actEl === root)) {
          var openLnk = topFoc.querySelector('.btt-topic-click-overlay, a, button');
          if (openLnk) openLnk.click();
          else topFoc.click();
          return;
        }
        if (actEl && actEl !== doc.body) {
          var clk = actEl.closest('a, button, .btt-slash-chip, .btt-channel-btn, summary') || actEl;
          clk.click();
        }
      });

      // Buton B (1): Konu İçindeyse Geri Dön, Değilse Sohbeti Kapat
      btn(backBtn, 'pad-back', function () {
        if (typeof win.bttIsTopicPage === 'function' && win.bttIsTopicPage()) {
          if (typeof win.bttBackToFeed === 'function') { win.bttBackToFeed(); return; }
        }
        forComments.checked = false;
        fireChange(forComments);
      });

      // Buton X (2): Sohbeti Kapat (Toggle)
      btn(PAD_MAP.standard.x, 'pad-x', function () {
        forComments.checked = false;
        fireChange(forComments);
      });

      // Sağ Analog Çubuk: Yorum Sayfasını Akıcı Kaydır
      if (Math.abs(ry) > 0.18) {
        var cmPanel = doc.querySelector('#comment-blogger .cmBri, #comment-blogger .cmC, #cmHolder') || win;
        if (cmPanel && cmPanel.scrollBy) cmPanel.scrollBy(0, ry * 20);
        else win.scrollBy(0, ry * 20);
      }

      for (var k2 in S.held) {
        if (live.indexOf(k2) === -1) delete S.held[k2];
      }
      return;
    }

    /* ------------------------------------------------------------------
       DURUM 3: Normal Sayfa Gezinmesi (Gamepad + Fare + Klavye)
       ------------------------------------------------------------------ */
    /* Sol analog çubuk: Google Dot Sanal Fare ve Uzamsal Gezinme */
    if (Math.abs(lx) > 0.15 || Math.abs(ly) > 0.15) {
      updateDot(lx * dotSpeed, ly * dotSpeed);
    }
    if (Math.abs(lx) > CFG.deadzone || Math.abs(ly) > CFG.deadzone) {
      if (Math.abs(lx) >= Math.abs(ly)) {
        live.push('ax-x');
        padFire('ax-x', function () { move(lx > 0 ? 'right' : 'left'); });
      } else {
        live.push('ax-y');
        padFire('ax-y', function () { move(ly > 0 ? 'down' : 'up'); });
      }
    }

    /* Sağ analog çubuk: Sayfa akıcı kaydırma */
    if (Math.abs(rx) > 0.15 || Math.abs(ry) > 0.15) {
      var dx = Math.abs(rx) > 0.15 ? rx : 0;
      var dy = Math.abs(ry) > 0.15 ? ry : 0;
      win.scrollBy(dx * 18, dy * 24);
    }

    // Buton A (0): Seç / Tıkla
    btn(okBtn, 'pad-ok', function () {
      if (!editable(doc.activeElement)) {
        if (dotVisible) clickDot();
        else activate(true);
      }
    });

    // Buton B (1): Geri Git / Modalları Kapat
    btn(backBtn, 'pad-back', goBack);

    // Buton Y (3): Ctrl+F Gelişmiş Arama Modalı Aç
    btn(PAD_MAP.standard.y, 'pad-y', function () {
      if (typeof win.openAdvSearch === 'function') win.openAdvSearch();
      else openSearch();
    });

    // Buton X (2): Yorumlar / Sohbet Çekmecesini Aç
    btn(PAD_MAP.standard.x, 'pad-x', function () {
      var fc = doc.getElementById('forComments');
      if (fc) {
        fc.checked = true;
        fireChange(fc);
        var cmEl = doc.getElementById('comment-blogger') || doc.getElementById('comments');
        if (cmEl) setTimeout(function() { cmEl.scrollIntoView({ behavior: 'smooth', block: 'start' }); }, 100);
      }
    });

    // Buton Start (9): Menü Aç / Kapat
    btn(menuBtn, 'pad-menu', toggleMenu);

    // Buton Select (8): Tema Değiştir (Aydınlık / Karanlık)
    btn(helpBtn, 'pad-theme', toggleTheme);

    // D-Pad Yön Tuşları: Sayfayı veya Öğeleri Adım Adım Gezin
    btn(PAD_MAP.standard.up, 'pad-up', function () { win.scrollBy({ top: -160, behavior: 'smooth' }); });
    btn(PAD_MAP.standard.down, 'pad-down', function () { win.scrollBy({ top: 160, behavior: 'smooth' }); });
    btn(PAD_MAP.standard.left, 'pad-left', function () { move('left'); });
    btn(PAD_MAP.standard.right, 'pad-right', function () { move('right'); });

    // LB / RB: Slaytları veya Sayfalamayı Değiştir
    btn(PAD_MAP.standard.prev, 'pad-prev', function () {
      var prevBtn = doc.querySelector('.btt-nav-btn.btt-prev, .car-btn.prev, #ntfSliderDots .dot[data-dir="prev"]');
      if (prevBtn) prevBtn.click();
      else win.scrollBy({ top: -Math.round(win.innerHeight * 0.7), behavior: 'smooth' });
    });
    btn(PAD_MAP.standard.next, 'pad-next', function () {
      var nextBtn = doc.querySelector('.btt-nav-btn.btt-next, .car-btn.next, #ntfSliderDots .dot[data-dir="next"]');
      if (nextBtn) nextBtn.click();
      else win.scrollBy({ top: Math.round(win.innerHeight * 0.7), behavior: 'smooth' });
    });

    /* Bırakılan tuşları temizle */
    for (var k in S.held) {
      if (live.indexOf(k) === -1) delete S.held[k];
    }
  }

  function padFrame() {
    if (!S.running) return;
    var gps = nav.getGamepads ? nav.getGamepads() : [];
    var any = false;
    for (var i = 0; i < gps.length; i++) {
      if (gps[i] && gps[i].connected) { any = true; pollPad(gps[i]); }
    }
    if (win.requestAnimationFrame) win.requestAnimationFrame(padFrame);
    else win.setTimeout(padFrame, 16);
    if (any && !S.padOn) {
      S.padOn = true;
      announce('Oyun kolu veya uzaktan kumanda bağlandı.');
    }
  }

  function startPadLoop() {
    if (S.running) return;
    if (!nav.getGamepads) return;
    S.running = true;
    if (win.requestAnimationFrame) win.requestAnimationFrame(padFrame);
    else win.setTimeout(padFrame, 16);
  }

  /* ------------------------------------------------------------------ *
   *  11. KLAVYE
   * ------------------------------------------------------------------ */
  var DIRS = { ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right' };
  var NATIVE_KEYS = ['A', 'BUTTON', 'SUMMARY', 'INPUT', 'TEXTAREA', 'SELECT', 'DETAILS'];

  function handleKey(ev) {
    var key = ev.key;
    var code = ev.keyCode;

    /* Metin yazılan veya arama yapılan alandayken TVNav klavyeyi ASLA kapmasın */
    var a = doc.activeElement;
    var isInput = editable(ev.target) || editable(a) ||
      (ev.target && (ev.target.tagName === 'INPUT' || ev.target.tagName === 'TEXTAREA' || ev.target.isContentEditable)) ||
      (a && (a.tagName === 'INPUT' || a.tagName === 'TEXTAREA' || a.isContentEditable)) ||
      (ev.target && ev.target.closest && ev.target.closest('#comment-blogger, .btt-search-wrap, #advSearchModal, .btt-native-panel, input, textarea'));

    if (isInput) {
      if (key !== 'Escape') {
        ev.stopPropagation();
        return;
      }
    }

    /* Tab tuşuna basıldığında TVNav seçimini anında senkronize et */
    if (key === 'Tab') {
      S.pointer = false;
      requestAnimationFrame(syncFromDom);
      setTimeout(syncFromDom, 50);
      return;
    }

    /* 1a) Slider ve Medya Kontrolleri Koruması: Kullanıcı slider veya vitrin içindeyken yön ve medya tuşlarını slider'a bırak */
    var inSlider = ev.target && ev.target.closest && ev.target.closest('.post-media-slider, #ntfSlider, .insta-story-container, #fsMediaModal, .pms-track');
    var hoveredSlider = !inSlider ? document.querySelector('.post-media-slider:hover, #ntfSlider:hover, .insta-story-container:hover') : null;
    if (inSlider || hoveredSlider) {
      if (key === 'ArrowLeft' || key === 'ArrowRight' || key === 'Home' || key === 'End' ||
          key === ' ' || key === 'f' || key === 'F' || key === 'm' || key === 'M' || key === 'k' || key === 'K') {
        return;
      }
    }

    /* 1) Kısayol penceresi açıkken yalnızca Esc çalışsın; odak pencerede kalsın */
    if (S.hud && has(S.hud, 'on')) {
      if (key === 'w' || key === 'W' || key === 'f' || key === 'F') {
        ev.preventDefault();
        toggleWideScreen();
        return;
      }
      if (key === 'Escape' || key === 'Backspace' || code === 27) { ev.preventDefault(); closeHelp(); }
      return;
    }

    /* 2) Yazma alanı: yazmayı engelleme; ancak Esc veya kutu boşken/sınırdayken yön tuşları ile çıkabilsin */
    if (editable(ev.target)) {
      if (key === 'Escape' || code === 27) {
        ev.preventDefault();
        ev.target.blur();
        return;
      }
      var edDir = DIRS[key] || ((code >= 37 && code <= 40) ? ['left', 'up', 'right', 'down'][code - 37] : null);
      if (edDir) {
        var valStr = String(ev.target.value || '');
        var isSingleLine = ev.target.tagName === 'INPUT';
        var atStart = true, atEnd = true;
        try {
          if (typeof ev.target.selectionStart === 'number') {
            atStart = (ev.target.selectionStart === 0 && ev.target.selectionEnd === 0);
            atEnd = (ev.target.selectionStart === valStr.length);
          }
        } catch (e) {}
        if (!valStr.length ||
            (isSingleLine && (edDir === 'up' || edDir === 'down')) ||
            (edDir === 'left' && atStart) ||
            (edDir === 'right' && atEnd)) {
          ev.preventDefault();
          S.current = ev.target;
          ev.target.blur();
          move(edDir);
          return;
        }
      }
      return;
    }

    /* 3) Değiştirici tuşlar tarayıcıya bırakılır (Ctrl+F, Ctrl+P, Alt+* …) */
    if (ev.ctrlKey || ev.metaKey || ev.altKey) return;

    /* 4) Geri / kapat */
    if (key === 'Escape' || key === 'Backspace' || key === 'BrowserBack' ||
        key === 'GoBack' || key === 'BrowserStop' || code === 27 || code === 8) {
      ev.preventDefault();
      if (!goBack()) { try { window.history.back(); } catch (e) {} }
      return;
    }

    /* 5) Seç: kendi davranışı olan öğelerde tarayıcıya bırak */
    var a = doc.activeElement;
    var native = NATIVE_KEYS.indexOf(a ? a.tagName : '') !== -1;
    var enterLike = (key === 'Enter' || key === ' ' || key === 'NumpadEnter' ||
                     key === 'OK' || key === 'Select' || key === 'MediaPlayPause' ||
                     code === 13 || code === 32);
    if (native) {
      if (enterLike) return; /* bağlantı açma / form gönderimi / onay kutusu */
    } else if (enterLike) {
      if (key === ' ' && !S.current &&
          (!doc.activeElement || doc.activeElement === doc.body)) return;
      ev.preventDefault();
      activate(false);
      return;
    }

    /* 6) Yön tuşları: uzamsal gezinme */
    var dir = DIRS[key];
    if (!dir && code >= 37 && code <= 40) dir = ['left', 'up', 'right', 'down'][code - 37];
    if (dir) {
      ev.preventDefault();
      move(dir);
      return;
    }

    /* 7) Kısayollar — aynı tuşa çok hızlı basmayı filtrele */
    var now = Date.now();
    if (key === S.lastKey && now - S.lastKeyAt < CFG.keyRepeat) return;

    var fn = null;
    switch (key) {
      case '/': case 's': case 'S': case 'f': case 'F':
      case 'BrowserSearch': case 'MediaSearch': case 'Search':
        fn = openSearch; break;
      case 'h': case 'H': case 'BrowserHome': case 'GoHome':
        fn = goHome; break;
      case 'm': case 'M': case 'BrowserFavorites': case 'Favorites':
        fn = toggleMenu; break;
      case 'g': case 'G': fn = focusMain; break;
      case 'c': case 'C': fn = toggleComments; break;
      case 'n': case 'N': case 'ChannelUp': case 'MediaTrackPrevious':
        fn = function () { gotoPage(-1); }; break;
      case 'p': case 'P': case 'ChannelDown': case 'MediaTrackNext':
        fn = function () { gotoPage(1); }; break;
      case 'd': case 'D': fn = toggleTheme; break;
      case 't': case 'T': fn = toTop; break;
      case '?': case 'F1': fn = toggleHelp; break;
      default: return;
    }
    S.lastKey = key;
    S.lastKeyAt = now;
    ev.preventDefault();
    fn();
  }

  /* ------------------------------------------------------------------ *
   *  12. BAŞLATMA
   * ------------------------------------------------------------------ */
  function syncFromDom() {
    var a = doc.activeElement;
    if (!a || a === doc.body || a === root || S.pointer) {
      if (S.current) mark(S.current, false);
      S.current = null;
      updateFocusDot(null);
      return;
    }
    if (S.current && S.current !== a) {
      mark(S.current, false);
    }
    S.current = a;
    mark(a, true);
    updateFocusDot(a);
  }

  function init() {
    if (S.scan !== null) return;
    buildList(true);
    initTrigger();

    /* İçerik sonradan değişirse (yorumlar, sonsuz kaydırma, reklamlar) tazele */
    try {
      var obs = new MutationObserver(function () { S.listAt = 0; });
      obs.observe(doc.body, { childList: true, subtree: true });
    } catch (e) { /* MutationObserver yoksa yoksay */ }

    /* Giriş türü takibi: fare/dokunma odak halkasını gizler */
    win.addEventListener('mousedown', function () {
      S.pointer = true;
      if (focusDotEl) focusDotEl.classList.remove('on');
      if (S.current) { mark(S.current, false); S.current = null; }
    }, true);
    win.addEventListener('touchstart', function () {
      S.pointer = true;
      if (focusDotEl) focusDotEl.classList.remove('on');
      if (S.current) { mark(S.current, false); S.current = null; }
    }, true);
    doc.addEventListener('keydown', function () { S.pointer = false; }, true);

    doc.addEventListener('focusin', syncFromDom);
    doc.addEventListener('focusout', function () { setTimeout(syncFromDom, 20); });
    win.addEventListener('gamepadconnected', startPadLoop);
    win.addEventListener('blur', function () { S.held = {}; });
    doc.addEventListener('keydown', handleKey, true);

    startPadLoop();

    /* Olay gönderilmeden bağlanmış kumandalar için düşük ritimli tarama */
    var scan = win.setInterval(function () {
      if (S.running) { win.clearInterval(scan); return; }
      var gps = nav.getGamepads ? nav.getGamepads() : [];
      for (var i = 0; i < gps.length; i++) {
        if (gps[i] && gps[i].connected) { win.clearInterval(scan); startPadLoop(); return; }
      }
    }, CFG.scanInterval);
    S.scan = scan;

    root.setAttribute('data-tv-nav', 'on');
  }

  window.TVNav.api = {
    move: move,
    activate: activate,
    back: goBack,
    search: openSearch,
    home: goHome,
    menu: toggleMenu,
    help: toggleHelp,
    refresh: function () { buildList(true); },
    version: '1.0.0'
  };

  if (doc.readyState === 'loading') doc.addEventListener('DOMContentLoaded', init);
  else init();
})();
//

body.script:
//
(function(){
  // 1. Contact Form Submit & Kusursuz Yana Kayan Carousel Slider Mantığı
  var f = document.querySelector("#ContactForm2 form");
  if(f){
    var b = f.querySelector(".contact-form-button-submit"),
        e = f.querySelector(".contact-form-error-message"),
        o = f.querySelector(".contact-form-success-message"),
        c = document.getElementById("json:contactconfig");

    var slideName = document.getElementById("cfSlideName"),
        slideEmail = document.getElementById("cfSlideEmail"),
        slideMsg = document.getElementById("cfSlideMsg"),
        slideSubmit = document.getElementById("cfSlideSubmit"),
        next1 = document.getElementById("cfNext1"),
        next2 = document.getElementById("cfNext2"),
        next3 = document.getElementById("cfNext3"),
        inputName = f.querySelector(".contact-form-name"),
        inputEmail = f.querySelector(".contact-form-email"),
        inputMsg = f.elements["message"] || f.elements["email-message"];

    var slides = [slideName, slideEmail, slideMsg, slideSubmit];
    var currentStep = 0; // 0: Name, 1: Email, 2: Message, 3: Submit

    function showError(msg, activeSlide){
      if(o) o.textContent = "";
      if(e){
        e.textContent = msg;
        e.style.display = "block";
      }
      if(activeSlide){
        activeSlide.classList.remove("cf-shake");
        void activeSlide.offsetWidth;
        activeSlide.classList.add("cf-shake");
        setTimeout(function(){ activeSlide.classList.remove("cf-shake"); }, 350);
      }
    }

    function clearError(){
      if(e){
        e.textContent = "";
        e.style.display = "none";
      }
    }

    function validateEmail(val) {
      return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val);
    }

    // Chatbox otomatik genişleme
    function autoResizeMsg() {
      if(!inputMsg) return;
      inputMsg.style.height = 'auto';
      var scrollH = inputMsg.scrollHeight;
      var newH = Math.min(220, Math.max(48, scrollH));
      inputMsg.style.height = newH + 'px';
      inputMsg.style.overflowY = scrollH > 220 ? 'auto' : 'hidden';
    }

    if(inputMsg){
      inputMsg.addEventListener('input', autoResizeMsg);
      inputMsg.addEventListener('focus', autoResizeMsg);
      autoResizeMsg();
    }

    // Kullanıcı yazarken hataları otomatik temizle
    if(inputName) inputName.addEventListener("input", function(){ if(e && e.textContent) clearError(); });
    if(inputEmail) inputEmail.addEventListener("input", function(){ if(e && e.textContent) clearError(); });
    if(inputMsg) inputMsg.addEventListener("input", function(){ if(e && e.textContent) clearError(); });

    // Yana kaydırma fonksiyonu (Slider Step)
    function goToStep(stepIndex){
      currentStep = stepIndex;
      clearError();

      for(var i = 0; i < slides.length; i++){
        if(!slides[i]) continue;
        slides[i].classList.remove("active", "passed");
        if(i < stepIndex){
          slides[i].classList.add("passed");
        } else if(i === stepIndex){
          slides[i].classList.add("active");
        }
      }

      if(stepIndex === 0 && inputName) setTimeout(function(){ inputName.focus(); }, 120);
      if(stepIndex === 1 && inputEmail) setTimeout(function(){ inputEmail.focus(); }, 120);
      if(stepIndex === 2 && inputMsg) {
        setTimeout(function(){
          inputMsg.focus();
          autoResizeMsg();
        }, 120);
      }
      if(stepIndex === 3 && b) setTimeout(function(){ b.focus(); }, 120);
    }

    // 1. Adımı doğrula ve E-posta adımına yana kaydır (Boşsa ASLA geçemez)
    function handleNext1(){
      var n = inputName ? inputName.value.trim() : "";
      if(!n || n.length < 2){
        showError("Lütfen adınızı girin.", slideName);
        if(inputName) inputName.focus();
        return;
      }
      goToStep(1);
    }

    // 2. Adımı doğrula ve Mesaj adımına yana kaydır (Geçersiz e-posta ile ASLA geçemez)
    function handleNext2(){
      var em = inputEmail ? inputEmail.value.trim() : "";
      if(!em || !validateEmail(em)){
        showError("Lütfen geçerli bir e-posta adresi girin.", slideEmail);
        if(inputEmail) inputEmail.focus();
        return;
      }
      goToStep(2);
    }

    // 3. Mesajı doğrula ve Gönder butonuna yana kaydır (Mesaj boşsa ASLA geçemez)
    function handleNext3(){
      var rm = inputMsg ? inputMsg.value.trim() : "";
      if(!rm || rm.length < 2){
        showError("Lütfen mesajınızı yazın.", slideMsg);
        if(inputMsg) inputMsg.focus();
        return;
      }
      goToStep(3);
    }

    if(next1) next1.addEventListener("click", handleNext1);
    if(next2) next2.addEventListener("click", handleNext2);
    if(next3) next3.addEventListener("click", handleNext3);

    // Enter tuş desteği
    if(inputName){
      inputName.addEventListener("keydown", function(ev){
        if(ev.key === "Enter"){
          ev.preventDefault();
          handleNext1();
        }
      });
    }

    if(inputEmail){
      inputEmail.addEventListener("keydown", function(ev){
        if(ev.key === "Enter"){
          ev.preventDefault();
          handleNext2();
        }
      });
    }

    if(inputMsg){
      inputMsg.addEventListener("keydown", function(ev){
        if((ev.ctrlKey || ev.metaKey) && ev.key === "Enter"){
          ev.preventDefault();
          handleNext3();
        }
      });
    }

    // Form Gönderim Mantığı
    function handleContactSubmit(ev){
      if(ev) ev.preventDefault();
      if(!c) return;
      var j = JSON.parse(c.textContent);
      var n = inputName ? inputName.value.trim() : "",
          rm = inputMsg ? inputMsg.value.trim() : "",
          em = inputEmail ? inputEmail.value.trim() : "";

      if(!n || n.length < 2){
        goToStep(0);
        showError("Lütfen adınızı girin.", slideName);
        return;
      }
      if(!em || !validateEmail(em)){
        goToStep(1);
        showError("Lütfen geçerli bir e-posta adresi girin.", slideEmail);
        return;
      }
      if(!rm || rm.length < 2){
        goToStep(2);
        showError("Lütfen göndermek istediğiniz mesajı yazın.", slideMsg);
        return;
      }

      clearError();
      if(o) o.textContent = "Gönderiliyor...";
      var submitBtn = b;
      if(submitBtn) {
        submitBtn.disabled = true;
        submitBtn.classList.add("is-sending");
      }

      // Kullanıcının yazdığı mesajı giden baloncuk olarak ekle
      var bubbleStack = document.getElementById("cfBubbleStack");
      if(bubbleStack){
        var userBubble = document.createElement("div");
        userBubble.className = "cf-chat-bubble cf-user-bubble";
        var safeText = rm.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
        userBubble.innerHTML = "<span>" + safeText + "</span>" +
          "<div class='cf-bubble-meta'><span class='cf-bubble-time'>Şimdi</span>" +
          "<svg class='cf-double-check' viewBox='0 0 24 24'><path d='M18 6L7 17l-5-5M22 10l-7.5 7.5L13 16'/></svg></div>";
        bubbleStack.appendChild(userBubble);
        userBubble.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }

      var m = "Email: " + em + "\n\n" + rm;
      if(n) m = "Ad: " + n + "\n" + m;
      var p = document.createElement("form");
      p.method = "POST";
      p.action = j.au;
      p.target = "cframe";
      p.style.display = "none";
      var h = [["email", em], ["message", m], ["blogID", "<data:blog.blogId/>"], ["token", j.tk]];
      if(n) h.push(["name", n]);
      for(var t = 0; t < h.length; t++){
        var inp = document.createElement("input");
        inp.type = "hidden";
        inp.name = h[t][0];
        inp.value = h[t][1];
        p.appendChild(inp);
      }
      document.body.appendChild(p);
      p.submit();
      document.body.removeChild(p);
      setTimeout(function(){
        if(submitBtn) {
          submitBtn.disabled = false;
          submitBtn.classList.remove("is-sending");
        }

        // Gönderildi Efekti ve Onay Kartı
        if(bubbleStack){
          var botReply = document.createElement("div");
          botReply.className = "cf-sent-success-card";
          botReply.innerHTML = "<div class='cf-sent-check-icon'><svg viewBox='0 0 24 24'><polyline points='20 6 9 17 4 12'/></svg></div>" +
            "<div style='font-weight: 700; font-size: 0.95rem; color: #10b981;'>Mesajınız Başarıyla İletildi! ✓✓</div>" +
            "<div style='font-size: 0.84rem; opacity: 0.88;'>En kısa sürede e-posta adresinizden dönüş yapacağız.</div>";
          bubbleStack.appendChild(botReply);
          botReply.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        }

        if(o) o.textContent = "Mesajınız başarıyla iletildi!";
        clearError();
        f.reset();
        autoResizeMsg();
        goToStep(0);
        setTimeout(function(){
          if(o) o.textContent = "";
        }, 5000);
        setTimeout(closeSpotlight, 2800);
      }, 1600);
    }

    if(b){
      b.onclick = handleContactSubmit;
    }
    f.onsubmit = handleContactSubmit;
  }

  // 2. Bize Ulaşın (#ContactForm2) Odak & Bulanıklık (Blur) Modalı
  var cf = document.getElementById("ContactForm2");

  // Kenar çubuğu yerleşimini koruyan görünmez yer tutucu
  var placeholder = document.getElementById("cfPlaceholder");
  if(cf && !placeholder){
    placeholder = document.createElement("div");
    placeholder.id = "cfPlaceholder";
    placeholder.style.display = "none";
    if(cf.parentNode) cf.parentNode.insertBefore(placeholder, cf);
  }

  // ContactForm2 içi Kapat (X) butonu
  var closeBtn = cf ? cf.querySelector(".cf-close-btn") : null;
  if(cf && !closeBtn){
    closeBtn = document.createElement("button");
    closeBtn.className = "cf-close-btn";
    closeBtn.type = "button";
    closeBtn.setAttribute("aria-label", "Kapat");
    closeBtn.setAttribute("title", "Kapat");
    closeBtn.innerHTML = "<svg viewBox='0 0 24 24'><line x1='18' y1='6' x2='6' y2='18'/><line x1='6' y1='6' x2='18' y2='18'/></svg>";
    cf.appendChild(closeBtn);
  }

  // Bulanık arkaplan örtüsü (Backdrop)
  var backdrop = document.getElementById("cfBackdrop");
  if(!backdrop){
    backdrop = document.createElement("div");
    backdrop.id = "cfBackdrop";
    backdrop.className = "cf-backdrop";
    document.body.appendChild(backdrop);
  }

  function initChatboxResizer(){
    return;
  }

  function openSpotlight(){
    var targetCf = document.getElementById("ContactForm2");
    if(!targetCf){
      var h = window.location.hash;
      if(h !== "#ContactForm2" && h !== "#İletişim" && h !== "#iletisim" && decodeURIComponent(h) !== "#İletişim"){
        window.location.href = window.location.origin + "/#ContactForm2";
      }
      return;
    }
    targetCf.classList.remove("cf-closed");
    if(placeholder && placeholder.parentNode){
      placeholder.style.display = "block";
      if(targetCf.parentNode !== document.body){
        document.body.appendChild(targetCf);
      }
    }
    document.body.classList.add("cf-blurred");
    targetCf.classList.add("cf-spotlight");
    initChatboxResizer();

    // Ensure close button exists
    if(!targetCf.querySelector(".cf-close-btn")){
      var cb = document.createElement("button");
      cb.className = "cf-close-btn";
      cb.type = "button";
      cb.setAttribute("aria-label", "Kapat");
      cb.setAttribute("title", "Kapat");
      cb.innerHTML = "<svg viewBox='0 0 24 24'><line x1='18' y1='6' x2='6' y2='18'/><line x1='6' y1='6' x2='18' y2='18'/></svg>";
      targetCf.appendChild(cb);
    }

    // 'Yazıyor...' Animasyon Efekti (Typing Indicator)
    var typingEl = document.getElementById("cfTypingIndicator");
    var statusLbl = document.getElementById("cfStatusLabel");
    var bubbleStack = document.getElementById("cfBubbleStack");
    if(typingEl && bubbleStack){
      typingEl.style.display = "inline-flex";
      if(statusLbl) statusLbl.textContent = "yazıyor...";
      var botBubbles = bubbleStack.querySelectorAll(".cf-chat-bubble:not(.cf-user-bubble)");
      botBubbles.forEach(function(b){ b.style.opacity = "0"; b.style.transform = "translateY(8px)"; });
      setTimeout(function(){
        typingEl.style.display = "none";
        if(statusLbl) statusLbl.textContent = "Çevrimiçi";
        botBubbles.forEach(function(b, idx){
          setTimeout(function(){
            b.style.transition = "all 0.35s cubic-bezier(0.16, 1, 0.3, 1)";
            b.style.opacity = "1";
            b.style.transform = "translateY(0)";
          }, idx * 120);
        });
      }, 700);
    }

    var firstInput = targetCf.querySelector("input:not([type=hidden]):not([type=button])");
    if(firstInput) setTimeout(function(){ firstInput.focus(); }, 150);
  }

  function closeSpotlight(){
    document.body.classList.remove("cf-blurred");
    var targetCf = document.getElementById("ContactForm2");
    if(targetCf){
      targetCf.classList.remove("cf-spotlight");
      targetCf.classList.add("cf-closed");
      if(placeholder && placeholder.parentNode){
        placeholder.parentNode.insertBefore(targetCf, placeholder);
        placeholder.style.display = "none";
      }
      var tempBubbles = targetCf.querySelectorAll(".cf-user-bubble, .cf-sent-success-card");
      tempBubbles.forEach(function(el){ el.remove(); });
      var botBubbles = targetCf.querySelectorAll(".cf-chat-bubble:not(.cf-user-bubble)");
      botBubbles.forEach(function(b){ b.style.opacity = ""; b.style.transform = ""; b.style.transition = ""; });
      var statusLbl = document.getElementById("cfStatusLabel");
      if(statusLbl) statusLbl.textContent = "Çevrimiçi";
    }
    try {
      var curHash = window.location.hash || "";
      if(curHash.indexOf("ContactForm2") !== -1 || curHash.indexOf("letişim") !== -1 || curHash.indexOf("letisim") !== -1 || decodeURIComponent(curHash).indexOf("İletişim") !== -1){
        if(window.history && window.history.replaceState){
          window.history.replaceState(null, "", window.location.pathname + window.location.search);
        } else {
          window.location.hash = "#!";
        }
      }
    } catch(err){}
  }

  if(backdrop) backdrop.addEventListener("click", closeSpotlight);

  document.addEventListener("keydown", function(ev){
    if(ev.key === "Escape" || ev.keyCode === 27){
      if(document.body.classList.contains("cf-blurred") || (cf && cf.classList.contains("cf-spotlight"))){
        closeSpotlight();
      }
    }
  });

  // Capture phase listener for close buttons, ContactForm2, and Comments/Sohbet triggers
  document.addEventListener("click", function(ev){
    var closeTrigger = ev.target && ev.target.closest && ev.target.closest(".cf-close-btn, #cfBackdrop, [data-cf-close]");
    if(closeTrigger){
      ev.preventDefault();
      ev.stopPropagation();
      closeSpotlight();
      return;
    }
    // Web Share API & Diğer Uygulamalarda Paylaşım Desteği
    var shareBtn = ev.target && ev.target.closest && ev.target.closest(".sh.tIc, label[for='forShare'], .pShc label[for='forShare'], .mS label[for='forShare']");
    if (shareBtn) {
      ev.preventDefault();
      ev.stopPropagation();
      var cb = document.getElementById("forShare");
      if (cb) {
        cb.checked = !cb.checked;
        cb.dispatchEvent(new Event("change"));
      } else if (navigator.share) {
        navigator.share({
          title: document.title,
          url: window.location.href
        }).catch(function() {});
      }
      return;
    }

    var a = ev.target && ev.target.closest && ev.target.closest("a[href*='#ContactForm2'], a[href*='#İletişim'], a[href*='#iletisim'], a[href*='%C4%B0leti%C5%9Fim'], .cf-sidebar-trigger-btn:not(.cm-sidebar-trigger-btn), .ntf-contact-link");
    if(a){
      ev.preventDefault();
      openSpotlight();
      return;
    }
    var cmA = ev.target && ev.target.closest && ev.target.closest(".cmnt, a.cmnt, a[href*='#comment'], a[href*='#comments'], a[href*='#Sohbet'], a[href*='#sohbet'], a[href*='#comment-blogger'], .cm-sidebar-trigger-btn, .ntf-sohbet-link, [data-open-comments]");
    if(cmA){
      ev.preventDefault();
      var fc = document.getElementById("forComments");
      if(fc){
        fc.checked = true;
        fc.dispatchEvent(new Event("change"));
        var cmEl = document.getElementById("comment-blogger") || document.getElementById("comments");
        if(cmEl){
          cmEl.scrollIntoView({ behavior: "smooth", block: "start" });
        }
        if(typeof loadNativeFeeds === "function") loadNativeFeeds();
        else if(typeof window.bttLoadNativeFeeds === "function") window.bttLoadNativeFeeds();
      } else {
        var targetHref = (cmA.getAttribute && (cmA.getAttribute('data-href') || cmA.getAttribute('href'))) || '';
        if (targetHref && targetHref.indexOf('#') !== 0 && targetHref.indexOf('javascript') !== 0) {
          window.location.href = targetHref;
        } else {
          window.location.href = '/p/muhabbet.html';
        }
      }
      return;
    }
  }, true);

  window.addEventListener("hashchange", function(){
    var h = window.location.hash;
    if(h === "#ContactForm2" || h === "#İletişim" || h === "#iletisim" || decodeURIComponent(h) === "#İletişim"){
      openSpotlight();
    } else {
      closeSpotlight();
    }
  });

  var initHash = window.location.hash;
  if(initHash === "#ContactForm2" || initHash === "#İletişim" || initHash === "#iletisim" || decodeURIComponent(initHash) === "#İletişim"){
    setTimeout(openSpotlight, 150);
  }

  initChatboxResizer();
  setTimeout(initChatboxResizer, 400);
})();
