(function(){
  function initNtfSlider(){
    var slider = document.getElementById("ntfSlider");
    if(!slider) return;

    var dotWraps = Array.prototype.slice.call(document.querySelectorAll("#ntfSliderDots, [data-dots-for='ntfSlider']"));

    function updateDots() {
      if(!dotWraps.length) return;
      var scrollLeft = slider.scrollLeft;
      var firstChild = slider.children[0];
      var childW = (firstChild ? firstChild.offsetWidth : 0) || slider.clientWidth || 1;
      dotWraps.forEach(function(wrap) {
        var dots = Array.prototype.slice.call(wrap.querySelectorAll(".dot"));
        var maxIdx = Math.max(0, dots.length - 1);
        var activeIdx = Math.min(maxIdx, Math.max(0, Math.round(scrollLeft / childW)));
        dots.forEach(function(d, i) {
          if (i === activeIdx) {
            d.classList.add("active");
          } else {
            d.classList.remove("active");
          }
        });
      });
      if (window.updateSliderMask) window.updateSliderMask(slider);
    }

    var ticking = false;
    slider.addEventListener("scroll", function() {
      if(!ticking) {
        window.requestAnimationFrame(function() {
          updateDots();
          ticking = false;
        });
        ticking = true;
      }
    }, { passive: true });

    dotWraps.forEach(function(wrap) {
      var dots = Array.prototype.slice.call(wrap.querySelectorAll(".dot"));
      dots.forEach(function(dot, idx) {
        dot.addEventListener("click", function(e) {
          e.preventDefault();
          e.stopPropagation();
          var items = Array.prototype.slice.call(slider.children);
          var targetPos = 0;
          if (idx === 0) {
            targetPos = 0;
          } else if (items[idx]) {
            targetPos = items[idx].offsetLeft;
          } else {
            var firstChild = slider.children[0];
            var childW = (firstChild ? firstChild.offsetWidth : 0) || slider.clientWidth || 1;
            targetPos = idx * childW;
          }
          slider.scrollTo({ left: targetPos, behavior: "smooth" });
        });
      });
    });

    // Ticker Stili Prev/Next Butonları (< >)
    var prevBtn = document.getElementById("ntfTickerPrev");
    var nextBtn = document.getElementById("ntfTickerNext");
    if (prevBtn) {
      prevBtn.addEventListener("click", function(e) {
        e.preventDefault();
        e.stopPropagation();
        var firstChild = slider.children[0];
        var childW = (firstChild ? firstChild.offsetWidth : 0) || slider.clientWidth || 1;
        if (slider.scrollLeft <= 5) {
          slider.scrollTo({ left: slider.scrollWidth - slider.clientWidth, behavior: "smooth" });
        } else {
          slider.scrollBy({ left: -childW, behavior: "smooth" });
        }
      });
    }
    if (nextBtn) {
      nextBtn.addEventListener("click", function(e) {
        e.preventDefault();
        e.stopPropagation();
        var firstChild = slider.children[0];
        var childW = (firstChild ? firstChild.offsetWidth : 0) || slider.clientWidth || 1;
        var maxScroll = slider.scrollWidth - slider.clientWidth;
        if (slider.scrollLeft >= maxScroll - 5) {
          slider.scrollTo({ left: 0, behavior: "smooth" });
        } else {
          slider.scrollBy({ left: childW, behavior: "smooth" });
        }
      });
    }

    // Ticker Otomatik Kaydırma (Her 5 saniyede bir sonraki slayta geçer, üzerine gelince duraklar)
    setInterval(function() {
      if (!slider || !document.contains(slider) || slider.matches(':hover')) return;
      var firstChild = slider.children[0];
      var childW = (firstChild ? firstChild.offsetWidth : 0) || slider.clientWidth || 1;
      var maxScroll = slider.scrollWidth - slider.clientWidth;
      if (maxScroll <= 0) return;
      if (slider.scrollLeft >= maxScroll - 5) {
        slider.scrollTo({ left: 0, behavior: "smooth" });
      } else {
        slider.scrollBy({ left: childW, behavior: "smooth" });
      }
    }, 5000);

    slider.scrollLeft = 0;
    updateDots();

    // Masaüstünde fare ile sürükleyerek kaydırma desteği (tapps & saved stili)
    if (window.enableMouseDrag) {
      window.enableMouseDrag(slider, updateDots);
    }

    // Klavye ile Kontrol Desteği (Sol/Sağ ok, Home, End)
    slider.setAttribute('tabindex', '0');
    slider.setAttribute('role', 'region');
    slider.setAttribute('aria-label', 'Bildirim Slaytları');

    // slider.focus kaldırıldı (fare üzerine gelince dikey sayfa kaydırmasını kilitlemez)

    slider.addEventListener('keydown', function(e) {
      var firstChild = slider.children[0];
      var childW = (firstChild ? firstChild.offsetWidth : 0) || slider.clientWidth || 1;
      if (e.key === 'ArrowRight') {
        e.preventDefault();
        slider.scrollBy({ left: childW, behavior: 'smooth' });
      } else if (e.key === 'ArrowLeft') {
        e.preventDefault();
        slider.scrollBy({ left: -childW, behavior: 'smooth' });
      } else if (e.key === 'Home') {
        e.preventDefault();
        slider.scrollTo({ left: 0, behavior: 'smooth' });
      } else if (e.key === 'End') {
        e.preventDefault();
        slider.scrollTo({ left: slider.scrollWidth, behavior: 'smooth' });
      }
    });
  }

  //--[ Saved Stili Kategorize Edilmiş Gönderiler (.aCat) ve Benzer Yazılar (.aRps) Vitrin Kontrolcüsü ]--
  function initCategorizedShowcaseSlider() {
    function setupContainer(container) {
      if (!container || container.dataset.showcaseReady === '1') return;
      var track = container.querySelector('.blogP, .itemRp');
      if (!track) return;
      var items = track.querySelectorAll('article, .ntry, .itm');
      if (!items || !items.length) return;

      container.dataset.showcaseReady = '1';
      container.classList.add('cat-showcase-carousel');
      track.classList.add('cat-showcase-track');

      var nav = container.querySelector('.car-nav');
      if (!nav) {
        nav = document.createElement('div');
        nav.className = 'car-nav';
        nav.innerHTML = '<button type="button" class="car-btn car-prev active" aria-label="Önceki"></button>' +
                        '<button type="button" class="car-btn car-next" aria-label="Sonraki"></button>';
        container.appendChild(nav);
      }

      var prevBtn = nav.querySelector('.car-prev');
      var nextBtn = nav.querySelector('.car-next');

      function updateNav() {
        var max = track.scrollWidth - track.clientWidth;
        var has = max > 4;
        var atStart = track.scrollLeft <= 4;
        var atEnd = track.scrollLeft >= max - 4;

        container.classList.toggle('has-overflow', has);
        container.classList.toggle('at-start', atStart);
        container.classList.toggle('at-end', atEnd);

        if (prevBtn) {
          prevBtn.classList.toggle('at-end', atStart);
          prevBtn.classList.toggle('is-disabled', atStart);
          prevBtn.classList.toggle('active', !atStart && track.scrollLeft < max / 2);
        }
        if (nextBtn) {
          nextBtn.classList.toggle('at-end', atEnd || !has);
          nextBtn.classList.toggle('is-disabled', atEnd || !has);
          nextBtn.classList.toggle('active', !atEnd && (track.scrollLeft >= max / 2 || atStart));
        }
      }

      var scrollTimer = null;
      function stopScroll() {
        if (scrollTimer) {
          clearInterval(scrollTimer);
          scrollTimer = null;
        }
      }
      function startScroll(dir) {
        if (scrollTimer) return;
        var step = function() {
          return Math.max(18, Math.round(track.clientWidth * 0.035));
        };
        scrollTimer = setInterval(function() {
          track.scrollBy({ left: dir * step(), behavior: 'smooth' });
        }, 30);
      }
      function singleScroll(dir) {
        stopScroll();
        var firstItem = track.querySelector('article, .ntry, .itm');
        var itemW = (firstItem ? firstItem.offsetWidth : 0) || 240;
        var shift = (itemW + 16) * 2;
        track.scrollBy({ left: dir * shift, behavior: 'smooth' });
      }

      if (prevBtn) {
        prevBtn.addEventListener('click', function(e) {
          e.preventDefault(); e.stopPropagation();
          singleScroll(-1);
        });
        prevBtn.addEventListener('mousedown', function(e) {
          if (e.button !== 0) return;
          startScroll(-1);
        });
        prevBtn.addEventListener('touchstart', function(e) {
          startScroll(-1);
        }, { passive: true });
        prevBtn.addEventListener('mouseup', stopScroll);
        prevBtn.addEventListener('mouseleave', stopScroll);
        prevBtn.addEventListener('touchend', stopScroll);
        prevBtn.addEventListener('touchcancel', stopScroll);
      }

      if (nextBtn) {
        nextBtn.addEventListener('click', function(e) {
          e.preventDefault(); e.stopPropagation();
          singleScroll(1);
        });
        nextBtn.addEventListener('mousedown', function(e) {
          if (e.button !== 0) return;
          startScroll(1);
        });
        nextBtn.addEventListener('touchstart', function(e) {
          startScroll(1);
        }, { passive: true });
        nextBtn.addEventListener('mouseup', stopScroll);
        nextBtn.addEventListener('mouseleave', stopScroll);
        nextBtn.addEventListener('touchend', stopScroll);
        nextBtn.addEventListener('touchcancel', stopScroll);
      }

      track.addEventListener('scroll', updateNav, { passive: true });
      window.addEventListener('resize', updateNav, { passive: true });

      // Fare ile masaüstünde tutup sağa/sola sürükleyerek kaydırma
      if (window.enableMouseDrag) {
        window.enableMouseDrag(track, updateNav);
      }

      // Kartın tamamına tıklanabilirlik (sürükleme değilse)
      items.forEach(function(item) {
        item.style.cursor = 'pointer';
        item.addEventListener('click', function(e) {
          if (track.classList.contains('is-dragging') || track.dataset.wasDragging === '1') {
            e.preventDefault();
            e.stopPropagation();
            return;
          }
          if (!e.target.closest('a')) {
            var link = item.querySelector('a.thmb, .pTtl a, a[href]');
            if (link) link.click();
          }
        });
      });

      updateNav();
      setTimeout(updateNav, 100);
      setTimeout(updateNav, 400);
    }

    function scanAll() {
      var containers = document.querySelectorAll('.aCat, .aRps, #related .aRps');
      containers.forEach(setupContainer);
    }

    scanAll();

    // Dinamik olarak feed'den yüklenen tüm kategorileri ve benzer yazıları anında yakala
    if (typeof MutationObserver !== 'undefined') {
      var obs = new MutationObserver(function() {
        scanAll();
      });
      obs.observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['class'] });
    }

    setTimeout(scanAll, 500);
    setTimeout(scanAll, 1500);
    setTimeout(scanAll, 3000);
  }

  // Etiketler (#Label01) Akıcı Yatay Slayt ve Çizgi Butonları Motoru
  function initLabelSlider() {
    var labelWidgets = document.querySelectorAll('#Label01, .wL.Label');
    if (!labelWidgets.length) return;

    labelWidgets.forEach(function(widget) {
      if (widget.dataset.sliderInit === '1') return;
      var track = widget.querySelector('.lbL');
      if (!track) return;
      widget.dataset.sliderInit = '1';

      var title = widget.querySelector('.title');
      var nav = widget.querySelector('.car-nav');
      if (!nav && title) {
        nav = document.createElement('div');
        nav.className = 'car-nav label-slider-nav';
        nav.innerHTML = '<button type="button" class="car-btn car-prev active" aria-label="Önceki"></button>' +
                        '<button type="button" class="car-btn car-next" aria-label="Sonraki"></button>';
        title.appendChild(nav);
      }

      var prevBtn = nav ? nav.querySelector('.car-prev') : null;
      var nextBtn = nav ? nav.querySelector('.car-next') : null;

      function updateNav() {
        var max = track.scrollWidth - track.clientWidth;
        var has = max > 4;
        var atStart = track.scrollLeft <= 4;
        var atEnd = track.scrollLeft >= max - 4;

        if (nav) nav.style.display = has ? 'flex' : 'none';
        if (prevBtn) {
          prevBtn.classList.toggle('at-end', atStart);
          prevBtn.classList.toggle('is-disabled', atStart);
          prevBtn.classList.toggle('active', !atStart);
        }
        if (nextBtn) {
          nextBtn.classList.toggle('at-end', atEnd || !has);
          nextBtn.classList.toggle('is-disabled', atEnd || !has);
          nextBtn.classList.toggle('active', !atEnd && has);
        }
      }

      if (prevBtn) {
        prevBtn.addEventListener('click', function(e) {
          e.preventDefault(); e.stopPropagation();
          track.scrollBy({ left: -180, behavior: 'smooth' });
        });
      }
      if (nextBtn) {
        nextBtn.addEventListener('click', function(e) {
          e.preventDefault(); e.stopPropagation();
          track.scrollBy({ left: 180, behavior: 'smooth' });
        });
      }

      track.addEventListener('scroll', updateNav, { passive: true });
      window.addEventListener('resize', updateNav, { passive: true });

      // Masaüstünde dikey sayfa akışını asla kilitleme; sadece Shift tuşuyla yatay kaydır
      track.addEventListener('wheel', function(e) {
        if (e.shiftKey) {
          track.scrollLeft += (e.deltaY || e.deltaX);
          e.preventDefault();
        }
      }, { passive: false });

      // Masaüstünde fare ile tutup sürükleyerek kaydırma desteği
      if (window.enableMouseDrag) {
        window.enableMouseDrag(track, updateNav);
      }

      updateNav();
      setTimeout(updateNav, 200);
      setTimeout(updateNav, 600);
    });
  }


  // Blogger Plus UI 1:1 Numaralı Sayfalama Motoru (#blog-pager .blogN - 1 2 3 4 5...)
  function initBloggerNumberedPagination() {
    var pager = document.getElementById('blog-pager');
    if (!pager) return;
    if (document.body.classList.contains('item-view') || document.querySelector('.post-body, .pHead')) {
      return;
    }

    // 1 2 3 4 5 butonlarının kategorize edilmiş gönderiler ve tüm içeriklerin en altında durması garantisi
    function placePagerAtVeryBottom() {
      var p = document.getElementById('blog-pager');
      if (!p) return;
      var catWidget = document.getElementById('LinkList07') || document.querySelector('.aCat');
      var mainSection = document.getElementById('sec_Main_Widgets') || document.querySelector('.blogB');

      if (catWidget && catWidget.parentElement) {
        if (catWidget.nextElementSibling !== p) {
          catWidget.parentElement.appendChild(p);
        }
      } else if (mainSection && p.parentElement !== mainSection) {
        mainSection.appendChild(p);
      }
    }
    placePagerAtVeryBottom();
    window.addEventListener('load', placePagerAtVeryBottom);
    setTimeout(placePagerAtVeryBottom, 150);
    setTimeout(placePagerAtVeryBottom, 600);
    setTimeout(placePagerAtVeryBottom, 1800);

    var perPage = 7;
    var loc = window.location.href;
    var urlObj;
    try {
      urlObj = new URL(loc);
    } catch(e) {
      return;
    }

    var path = urlObj.pathname;
    var feedUrl = '/feeds/posts/summary?alt=json&max-results=150';
    var labelTerm = null;

    var labelMatch = path.match(/\/search\/label\/([^/?#]+)/i);
    if (labelMatch && labelMatch[1]) {
      try {
        labelTerm = decodeURIComponent(labelMatch[1]);
        feedUrl = '/feeds/posts/summary/-/' + encodeURIComponent(labelTerm) + '?alt=json&max-results=150';
      } catch(e) {}
    } else {
      var qMatch = urlObj.searchParams.get('q');
      if (qMatch) {
        feedUrl = '/feeds/posts/summary?q=' + encodeURIComponent(qMatch) + '&alt=json&max-results=150';
      }
    }

    var cacheKey = 'negronn_feed_' + (labelTerm ? ('lbl_' + labelTerm) : (urlObj.searchParams.get('q') ? ('q_' + urlObj.searchParams.get('q')) : 'all'));
    var cachedData = null;
    try {
      var raw = sessionStorage.getItem(cacheKey);
      if (raw) cachedData = JSON.parse(raw);
    } catch(e) {}

    function renderPager(data) {
      var entries = (data && data.feed && data.feed.entry) || [];
      var totalPosts = 0;
      if (data && data.feed && data.feed.openSearch$totalResults && data.feed.openSearch$totalResults.$t) {
        totalPosts = parseInt(data.feed.openSearch$totalResults.$t, 10);
      }
      if (!totalPosts) totalPosts = entries.length;
      if (totalPosts <= perPage) return;

      var totalPages = Math.ceil(totalPosts / perPage);

      // Aktif sayfayı tespit et
      var currentUpdatedMax = urlObj.searchParams.get('updated-max');
      var currentPage = 1;

      if (currentUpdatedMax) {
        var targetClean = currentUpdatedMax.replace(/[^0-9]/g, '').substring(0, 14);
        var firstPostIdx = -1;
        for (var i = 0; i < entries.length; i++) {
          var pub = entries[i].published ? entries[i].published.$t : '';
          var pubClean = pub.replace(/[^0-9]/g, '').substring(0, 14);
          if (pubClean < targetClean) {
            firstPostIdx = i;
            break;
          }
        }
        if (firstPostIdx >= 0) {
          currentPage = Math.floor(firstPostIdx / perPage) + 1;
        } else {
          var savedP = sessionStorage.getItem('negronn_blog_page');
          if (savedP) currentPage = parseInt(savedP, 10) || 2;
        }
      }

      if (currentPage < 1) currentPage = 1;
      if (currentPage > totalPages) currentPage = totalPages;

      function getPageUrl(p) {
        if (p === 1) {
          if (labelTerm) {
            return '/search/label/' + encodeURIComponent(labelTerm) + '?max-results=' + perPage;
          }
          return '/';
        }
        var prevLastIdx = (p - 1) * perPage - 1;
        if (prevLastIdx >= 0 && prevLastIdx < entries.length) {
          var pub = entries[prevLastIdx].published.$t;
          var formatted = (pub.substring(0, 19) + pub.substring(23, 29)).replace(/\+/g, '%2B');
          if (labelTerm) {
            return '/search/label/' + encodeURIComponent(labelTerm) + '?updated-max=' + formatted + '&max-results=' + perPage;
          }
          return '/search?updated-max=' + formatted + '&max-results=' + perPage;
        }
        return '/';
      }

      var pages = [];
      if (totalPages <= 7) {
        for (var p = 1; p <= totalPages; p++) pages.push(p);
      } else {
        pages.push(1);
        var startP = Math.max(2, currentPage - 2);
        var endP = Math.min(totalPages - 1, currentPage + 2);

        if (currentPage <= 3) {
          startP = 2;
          endP = Math.min(5, totalPages - 1);
        } else if (currentPage >= totalPages - 2) {
          startP = Math.max(2, totalPages - 4);
          endP = totalPages - 1;
        }

        if (startP > 2) pages.push('...');
        for (var p = startP; p <= endP; p++) pages.push(p);
        if (endP < totalPages - 1) pages.push('...');
        pages.push(totalPages);
      }

      var prevSvg = "<svg class='line' viewBox='0 0 24 24'><path d='M9.57 5.92993L3.5 11.9999L9.57 18.0699' stroke='currentColor' fill='none' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round'/><path d='M20.5 12H3.67004' stroke='currentColor' fill='none' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round'/></svg>";
      var nextSvg = "<svg class='line' viewBox='0 0 24 24'><path d='M14.4301 5.92993L20.5001 11.9999L14.4301 18.0699' stroke='currentColor' fill='none' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round'/><path d='M3.5 12H20.33' stroke='currentColor' fill='none' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round'/></svg>";

      var html = "";

      // Önceki Sayfa (<)
      if (currentPage > 1) {
        html += "<a href='" + getPageUrl(currentPage - 1) + "' class='nwLnk' data-page='" + (currentPage - 1) + "' aria-label='Önceki Sayfa' title='Önceki Sayfa'>" + prevSvg + "</a>";
      } else {
        html += "<div class='nwLnk nPst disabled' aria-disabled='true'>" + prevSvg + "</div>";
      }

      // Sayfa Numaraları (1, 2, 3, 4, 5...)
      for (var j = 0; j < pages.length; j++) {
        var itm = pages[j];
        if (itm === '...') {
          html += "<div class='nPst ellipsis' aria-hidden='true'>...</div>";
        } else if (itm === currentPage) {
          html += "<span class='active nPst' aria-current='page'>" + itm + "</span>";
        } else {
          html += "<a href='" + getPageUrl(itm) + "' data-page='" + itm + "' aria-label='Sayfa " + itm + "'>" + itm + "</a>";
        }
      }

      // Sonraki Sayfa (>)
      if (currentPage < totalPages) {
        html += "<a href='" + getPageUrl(currentPage + 1) + "' class='olLnk' data-page='" + (currentPage + 1) + "' aria-label='Sonraki Sayfa' title='Sonraki Sayfa'>" + nextSvg + "</a>";
      } else {
        html += "<div class='olLnk nPst disabled' aria-disabled='true'>" + nextSvg + "</div>";
      }

      pager.className = "blogN numP";
      pager.innerHTML = html;
      placePagerAtVeryBottom();

      pager.addEventListener('click', function(e) {
        var a = e.target.closest('a[data-page]');
        if (a) {
          var pgNum = a.getAttribute('data-page');
          if (pgNum) {
            try { sessionStorage.setItem('negronn_blog_page', pgNum); } catch(err) {}
          }
        }
      });
    }

    if (cachedData) {
      renderPager(cachedData);
    } else {
      fetch(feedUrl)
        .then(function(res) {
          if (!res.ok) throw new Error('Feed error');
          return res.json();
        })
        .then(function(data) {
          try { sessionStorage.setItem(cacheKey, JSON.stringify(data)); } catch(e) {}
          renderPager(data);
        })
        .catch(function(err) {
          console.warn('Numbered pagination feed error:', err);
        });
    }
  }


