  // Floating Admin Panel (.qeF / #offQEdit) Açıldığında Arka Plan ve Slayt Senkronizasyonu
  document.addEventListener('change', function(e) {
    if (e.target && (e.target.id === 'offQEdit' || (e.target.classList && e.target.classList.contains('qeI')))) {
      document.body.classList.toggle('qe-open', !!e.target.checked);
    }
  });
  if (typeof document !== 'undefined') {
