  // Floating Admin Panel (.qeL): Backup Theme & Backup Content Handler
  document.addEventListener("click", function(e) {
    var bTheme = e.target.closest("a[title*='Backup theme' i], a[title*='Temayı Yedekle' i], #qeBackupTheme, .qe-backup-theme");
    if (bTheme) {
      var blogId = (window.PU && window.PU.bg && window.PU.bg.bgId) || "";
      if (!blogId && window._WidgetManager && window._WidgetManager._GetAllData) {
        var allD = window._WidgetManager._GetAllData();
        if (allD && allD.blog) blogId = allD.blog.blogId || "";
      }
      if (!blogId) {
        var m = (bTheme.getAttribute("href") || "").match(/blogID=([0-9]+)/i);
        if (m) blogId = m[1];
      }
      if (blogId) {
        bTheme.setAttribute("href", "https://www.blogger.com/blogger-nongwt.do?blogID=" + blogId + "&action=download&expandWidget=true");
      }
      bTheme.setAttribute("target", "_blank");
      if (bTheme.hasAttribute("rel")) {
        bTheme.removeAttribute("rel");
      }
      return;
    }

    var bContent = e.target.closest("a[title*='Backup content' i], a[title*='İçeriği Yedekle' i], #qeBackupContent, .qe-backup-content");
    if (bContent) {
      e.preventDefault();
      var bId = (window.PU && window.PU.bg && window.PU.bg.bgId) || "";
      if (!bId && window._WidgetManager && window._WidgetManager._GetAllData) {
        var aData = window._WidgetManager._GetAllData();
        if (aData && aData.blog) bId = aData.blog.blogId || "";
      }
      // 1. Direct XML feed backup download
      var feedA = document.createElement("a");
      feedA.href = window.location.origin + "/feeds/posts/default?max-results=500";
      feedA.download = (window.location.hostname.replace(/[^a-z0-9]/gi, "-") || "blogger") + "-content-backup.xml";
      feedA.target = "_blank";
      document.body.appendChild(feedA);
      feedA.click();
      document.body.removeChild(feedA);
      // 2. Also open Blogger Settings page where full content export is located
      if (bId) {
        window.open("https://www.blogger.com/blog/settings/" + bId, "_blank");
      }
    }
  });

  /* ---------------------------------------------------------
     Rust Programming Language First-Class Support Engine
     - Detects Rust code blocks (class, data-lang, auto-detect)
     - Dynamic Highlight.js Rust grammar loading via PU.iHl('rust')
     - Injects interactive Rust Playground button (play.rust-lang.org)
     - MutationObserver support for Ajax / infinite scroll
     --------------------------------------------------------- */
  function initRustSupport() {
    var rustSvg = '<svg viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 14.5v-9l6 4.5-6 4.5z"/></svg>';

    function isRustBlock(pre, code) {
      var raw = ((pre ? (pre.className || '') + ' ' + (pre.getAttribute('data-lang') || '') + ' ' + (pre.getAttribute('data-language') || '') + ' ' + (pre.getAttribute('data-result-language') || '') : '') + ' ' + (code ? (code.className || '') + ' ' + (code.getAttribute('data-lang') || '') : '')).toLowerCase();
      if (/\b(rust|rs|lang-rust|language-rust|language-rs|lang-rs)\b/i.test(raw)) return true;
      if (code) {
        var text = (code.textContent || '').trim();
        if (/^(fn\s+main\s*\(|use\s+std::|pub\s+fn\b|impl\b[\s\S]*?\bfor\b|#\[derive\()/m.test(text)) {
          return true;
        }
      }
      return false;
    }

    function setupRustBlock(pre) {
      if (!pre || pre.dataset.rustInit === '1') return;
      var code = pre.querySelector('code');
      if (!code && !isRustBlock(pre, null)) return;
      if (!isRustBlock(pre, code)) return;

      pre.dataset.rustInit = '1';
      pre.setAttribute('data-result-language', 'rust');
      if (code && !code.classList.contains('language-rust')) {
        code.classList.add('language-rust');
      }

      // Add Rust Playground Button
      if (!pre.querySelector('button.play-rust')) {
        var btn = document.createElement('button');
        btn.className = 'play-rust';
        btn.type = 'button';
        btn.setAttribute('data-tooltip', "Rust Playground'da Çalıştır");
        btn.setAttribute('aria-label', "Rust Playground");
        btn.innerHTML = rustSvg;

        btn.addEventListener('click', function(ev) {
          ev.preventDefault();
          ev.stopPropagation();
          var targetEl = pre.querySelector('code') || pre;
          var codeText = targetEl.textContent || '';
          if (!codeText.trim()) return;
          var playUrl = 'https://play.rust-lang.org/?version=stable&mode=debug&edition=2021&code=' + encodeURIComponent(codeText);
          window.open(playUrl, '_blank', 'noopener,noreferrer');
        });

        var cpBtn = pre.querySelector('button.cp');
        if (cpBtn && cpBtn.parentNode === pre) {
          pre.insertBefore(btn, cpBtn);
        } else {
          pre.appendChild(btn);
        }
      }

      // Load & apply Rust grammar via PU.iHl
      if (code && !code.dataset.rustHl) {
        if (window.PU && typeof window.PU.iHl === 'function') {
          window.PU.iHl('rust').then(function(hljs) {
            if (code && hljs && typeof hljs.highlightElement === 'function') {
              hljs.highlightElement(code);
              code.dataset.rustHl = '1';
            }
          }).catch(function(){});
        } else if (window.hljs && typeof window.hljs.highlightElement === 'function') {
          window.hljs.highlightElement(code);
          code.dataset.rustHl = '1';
        }
      }
    }

    function scanAllRust() {
      var pres = document.querySelectorAll('pre');
      for (var i = 0; i < pres.length; i++) {
        setupRustBlock(pres[i]);
      }
    }

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', scanAllRust);
    } else {
      scanAllRust();
    }

    if (typeof MutationObserver !== 'undefined') {
      var observer = new MutationObserver(function(mutations) {
        for (var i = 0; i < mutations.length; i++) {
          var added = mutations[i].addedNodes;
          for (var j = 0; j < added.length; j++) {
            var node = added[j];
            if (node.nodeType === 1) {
              if (node.tagName === 'PRE') {
                setupRustBlock(node);
              } else if (node.querySelectorAll) {
                var subPres = node.querySelectorAll('pre');
                for (var k = 0; k < subPres.length; k++) {
                  setupRustBlock(subPres[k]);
                }
              }
            }
          }
        }
      });
      observer.observe(document.body || document.documentElement, { childList: true, subtree: true });
    }
  }
  initRustSupport();

  // Barların Slayt Motoru (Slayt 0 = Metin, Slayt 1 = İletişim - Ticker Stili Otomatik & Çizgi Butonlu Geçiş)
  function initBarsSlider() {
    function setupBar(sliderId, dotsId, autoPlayMs) {
      var slider = document.getElementById(sliderId);
      var dotWrap = document.getElementById(dotsId);
      if (!slider || !dotWrap || slider.dataset.barSliderInit === "1") return;
      slider.dataset.barSliderInit = "1";
      var slides = Array.prototype.slice.call(slider.querySelectorAll(".bar-slide"));
      var dots = Array.prototype.slice.call(dotWrap.querySelectorAll(".dot"));
      if (!slides.length || !dots.length) return;

      var currentIdx = 0;
      var timer = null;

      function goTo(idx) {
        currentIdx = (idx + slides.length) % slides.length;
        slides.forEach(function(s, i) {
          if (i === currentIdx) {
            s.classList.add("active");
          } else {
            s.classList.remove("active");
          }
        });
        if (dots.length === 2 && slides.length > 2) {
          var activeDotIdx = currentIdx === 0 ? 0 : 1;
          dots.forEach(function(d, i) {
            if (i === activeDotIdx) {
              d.classList.add("active");
            } else {
              d.classList.remove("active");
            }
          });
        } else {
          dots.forEach(function(d, i) {
            if (i === currentIdx) {
              d.classList.add("active");
            } else {
              d.classList.remove("active");
            }
          });
        }
      }

      function nextSlide() {
        goTo(currentIdx + 1);
      }

      function startAuto() {
        if (autoPlayMs && autoPlayMs > 0) {
          stopAuto();
          timer = setInterval(nextSlide, autoPlayMs);
        }
      }

      function stopAuto() {
        if (timer) {
          clearInterval(timer);
          timer = null;
        }
      }

      dots.forEach(function(dot, i) {
        dot.addEventListener("click", function(e) {
          e.preventDefault();
          e.stopPropagation();
          if (dots.length === 2 && slides.length > 2) {
            if (i === 0) {
              goTo(currentIdx - 1);
            } else {
              goTo(currentIdx + 1);
            }
          } else {
            if (i === currentIdx) {
              goTo(currentIdx + 1);
            } else {
              goTo(i);
            }
          }
          startAuto();
        });
      });

      var container = slider.parentElement || slider;
      container.addEventListener("mouseenter", stopAuto);
      container.addEventListener("mouseleave", startAuto);

      var touchStartX = 0;
      container.addEventListener("touchstart", function(e) {
        if (e.touches && e.touches.length) {
          touchStartX = e.touches[0].clientX;
        }
      }, { passive: true });
      container.addEventListener("touchend", function(e) {
        if (e.changedTouches && e.changedTouches.length) {
          var diff = touchStartX - e.changedTouches[0].clientX;
          if (Math.abs(diff) > 30) {
            goTo(diff > 0 ? currentIdx + 1 : currentIdx - 1);
            startAuto();
          }
        }
      }, { passive: true });

      goTo(0);
      startAuto();
    }

    var srcTabs = document.getElementById("aliNsoneTabsSource");
    var dstTabs = document.getElementById("ntfTabsSlide");
    if (srcTabs && dstTabs && !dstTabs.children.length && srcTabs.firstElementChild) {
      dstTabs.appendChild(srcTabs.firstElementChild.cloneNode(true));
    }
    var tickerLinks = document.querySelectorAll("#ticker-wrapper .ticker-item .entry-title a");
    var bSlider = document.getElementById("bottomBarSlider");
    if (bSlider && tickerLinks && tickerLinks.length && !bSlider.querySelector(".bar-slide-post")) {
      var seenUrls = {};
      for (var k = 0; k < tickerLinks.length; k++) {
        var aEl = tickerLinks[k];
        var href = aEl.getAttribute("href") || "#";
        var txt = (aEl.textContent || "").trim();
        if (!txt || seenUrls[href]) continue;
        seenUrls[href] = true;
        var slideDiv = document.createElement("div");
        slideDiv.className = "bar-slide bar-slide-text bar-slide-post";
        slideDiv.setAttribute("data-slide", String(bSlider.querySelectorAll(".bar-slide").length));
        var newA = document.createElement("a");
        newA.className = "ntf-ticker-text ntf-post-link";
        newA.href = href;
        newA.title = aEl.getAttribute("title") || txt;
        newA.textContent = txt;
        slideDiv.appendChild(newA);
        bSlider.appendChild(slideDiv);
      }
    }
    setupBar("bottomBarSlider", "ntfSliderDots", 5000);

    /* Reklam Alanları (.ad-slider-wrap, .mdlAd, .pAd, .rAd) Otomatik ve Çizgi Butonlu Slayt Motoru */
    function initAdSliders() {
      var extraAdBoxes = document.querySelectorAll('.mdlAd, .pAd, .rAd, .pAdIf');
      for (var m = 0; m < extraAdBoxes.length; m++) {
        var box = extraAdBoxes[m];
        if (box.querySelector('.ad-slider-wrap') || box.dataset.adUpgraded === '1') continue;
        box.dataset.adUpgraded = '1';
        var rawHtml = box.innerHTML.trim();
        if (!rawHtml) continue;
        var secondHtml = rawHtml.replace(/\(Post Middle Ad 1\)/g, '(Post Middle Ad 2)').replace(/- 1\)/g, '- 2)');
        box.innerHTML =
          '<div class="ad-slider-wrap">' +
            '<div class="ad-slider-track">' +
              '<div class="ad-slide active" data-slide="0">' + rawHtml + '</div>' +
              '<div class="ad-slide" data-slide="1">' + secondHtml + '</div>' +
            '</div>' +
            '<div aria-hidden="true" class="panel-slider-dots ad-slider-dots" title="Reklam Slaytı">' +
              '<button aria-label="Slayt 1" class="dot active" data-index="0" type="button"></button>' +
              '<button aria-label="Slayt 2" class="dot" data-index="1" type="button"></button>' +
            '</div>' +
          '</div>';
      }

      var wraps = document.querySelectorAll('.ad-slider-wrap');
      for (var w = 0; w < wraps.length; w++) {
        (function(wrap) {
          if (wrap.dataset.adSliderInit === '1') return;
          wrap.dataset.adSliderInit = '1';
          var slides = Array.prototype.slice.call(wrap.querySelectorAll('.ad-slide'));
          var dotWrap = wrap.querySelector('.ad-slider-dots');
          if (slides.length < 2 || !dotWrap) return;

          var dots = Array.prototype.slice.call(dotWrap.querySelectorAll('.dot'));
          var current = 0;
          var timer = null;

          function goToAdSlide(idx) {
            current = (idx + slides.length) % slides.length;
            for (var s = 0; s < slides.length; s++) {
              slides[s].classList.toggle('active', s === current);
            }
            var activeDot = current % dots.length;
            for (var d = 0; d < dots.length; d++) {
              dots[d].classList.toggle('active', d === activeDot);
            }
          }

          function nextAdSlide() {
            goToAdSlide(current + 1);
          }

          function startAdTimer() {
            stopAdTimer();
            timer = setInterval(nextAdSlide, 5000);
          }

          function stopAdTimer() {
            if (timer) {
              clearInterval(timer);
              timer = null;
            }
          }

          dotWrap.addEventListener('click', function(e) {
            var btn = e.target.closest('.dot');
            if (!btn) return;
            e.preventDefault();
            e.stopPropagation();
            var idx = parseInt(btn.getAttribute('data-index'), 10);
            if (isNaN(idx)) return;
            if (idx % dots.length === current % dots.length || slides.length > 2) {
              goToAdSlide(current + 1);
            } else {
              goToAdSlide(idx);
            }
            startAdTimer();
          });

          var startX = 0;
          wrap.addEventListener('touchstart', function(e) {
            if (e.touches && e.touches.length === 1) {
              startX = e.touches[0].clientX;
              stopAdTimer();
            }
          }, { passive: true });
          wrap.addEventListener('touchend', function(e) {
            if (e.changedTouches && e.changedTouches.length === 1) {
              var dx = e.changedTouches[0].clientX - startX;
              if (Math.abs(dx) > 35) {
                goToAdSlide(dx < 0 ? current + 1 : current - 1);
              }
              startAdTimer();
            }
          }, { passive: true });

          wrap.addEventListener('mouseenter', stopAdTimer);
          wrap.addEventListener('mouseleave', startAdTimer);
          startAdTimer();
        })(wraps[w]);
      }
    }
    initAdSliders();
    setTimeout(initAdSliders, 400);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initBarsSlider);
  } else {
    initBarsSlider();
  }

  // Ana Sayfa Fotoğraf Slaytı (.sldW) Çizgi Butonları Motoru (GitHub Saved Stili)
