  // Plu$ UI 3.0.0 Native Top Announcement Slider Engine
  /* ---------------------------------------------------------
     Plu$ UI Native Tabbed Menu (.navS) & Notification (.ntfT)
     Smooth Horizontal Slide / Touch & Drag Handler
     --------------------------------------------------------- */
  function initNavAndNotifSliders() {
    var sliders = document.querySelectorAll('.navS, .ntfT');
    sliders.forEach(function(el) {
      if (!el || el.dataset.slideInit) return;
      el.dataset.slideInit = '1';
      var isDown = false;
      var startX = 0;
      var scrollLeft = 0;

      el.addEventListener('mousedown', function(e) {
        isDown = true;
        el.classList.add('is-dragging');
        startX = e.pageX - el.offsetLeft;
        scrollLeft = el.scrollLeft;
      });
      el.addEventListener('mouseleave', function() {
        isDown = false;
        el.classList.remove('is-dragging');
      });
      el.addEventListener('mouseup', function() {
        isDown = false;
        el.classList.remove('is-dragging');
      });
      el.addEventListener('mousemove', function(e) {
        if (!isDown) return;
        e.preventDefault();
        var x = e.pageX - el.offsetLeft;
        var walk = (x - startX) * 1.5;
        el.scrollLeft = scrollLeft - walk;
      });
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initNavAndNotifSliders);
  } else {
    initNavAndNotifSliders();
  }
  window.addEventListener('load', initNavAndNotifSliders);

  //--[ Dinamik Noktalama İşaretleri Renklendirici Motoru ]--
  function stylePunctuation(root) {
    try {
      var sel = '.pTtl a, .pTtl span, .pTtl, .aTtl a, .aTtl, .title, .title a, .blogT .title, .ntf-ticker-text, .ntf-marquee-text, .entry-title, .pSnpt, .pCntn > p, .cmCo, .itemPp .pTtl, .itemFt .pTtl';
      var els = (root || document).querySelectorAll(sel);
      for (var i = 0; i < els.length; i++) {
        var el = els[i];
        if (!el || el.dataset.punctReady === '1' || el.closest('.notranslate, pre, code, svg, script, style, textarea, input')) continue;
        var child = el.firstChild;
        while (child) {
          var next = child.nextSibling;
          if (child.nodeType === 3 && child.nodeValue) {
            var text = child.nodeValue;
            if (/([.,!?:;\/»«—–•|&~#*()\[\]{}"\x27\-]+)/.test(text)) {
              var frag = document.createDocumentFragment();
              var parts = text.split(/([.,!?:;\/»«—–•|&~#*()\[\]{}"\x27\-]+)/g);
              for (var p = 0; p < parts.length; p++) {
                var part = parts[p];
                if (!part) continue;
                if (/^[.,!?:;\/»«—–•|&~#*()\[\]{}"\x27\-]+$/.test(part)) {
                  var span = document.createElement('span');
                  span.className = 'punct-mark';
                  span.textContent = part;
                  frag.appendChild(span);
                } else {
                  frag.appendChild(document.createTextNode(part));
                }
              }
              el.replaceChild(frag, child);
            }
          }
          child = next;
        }
        el.dataset.punctReady = '1';
      }
    } catch(e) {}
  }
  var punctTimer = null;
  function schedulePunctuation() {
    if (punctTimer) clearTimeout(punctTimer);
    punctTimer = setTimeout(function() {
      stylePunctuation();
    }, 120);
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", schedulePunctuation);
  } else {
    schedulePunctuation();
  }
  if (typeof MutationObserver !== "undefined") {
    var punctObs = new MutationObserver(schedulePunctuation);
    punctObs.observe(document.body || document.documentElement, { childList: true, subtree: true });
  }

  // Post View Counter Fallback & Stability Engine (Runs instantly across all cards & posts)
  (function() {
    function getPostId(el) {
      return el.getAttribute('data-id') || (el.closest('[data-id]') ? el.closest('[data-id]').getAttribute('data-id') : null);
    }
    function getStableBase(id) {
      if (!id) return 15;
      var h = 0;
      for (var i = 0; i < id.length; i++) {
        h = ((h << 5) - h) + id.charCodeAt(i);
        h |= 0;
      }
      return Math.abs(h % 70) + 15;
    }
    function syncPostViews() {
      var vEls = document.querySelectorAll('.fb-views, .pV, .pVws');
      if (!vEls.length) return;
      vEls.forEach(function(el) {
        var id = getPostId(el);
        if (!id) return;
        var storeKey = 'pu_v_' + id;
        var sessKey = 'pu_s_' + id;
        var val = localStorage.getItem(storeKey);
        if (!val) {
          val = getStableBase(id);
          localStorage.setItem(storeKey, val);
        } else {
          val = parseInt(val, 10);
        }
        if (el.getAttribute('data-increment') === 'true' && !sessionStorage.getItem(sessKey)) {
          val += 1;
          localStorage.setItem(storeKey, val);
          sessionStorage.setItem(sessKey, '1');
        }
        if (!el.hasAttribute('data-views') || el.getAttribute('data-views') === '0') {
          el.setAttribute('data-views', val.toString());
          el.style.setProperty('--v', "'" + val + "'");
        }
      });
    }
    syncPostViews();
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', syncPostViews);
    }
    window.addEventListener('load', syncPostViews);
    if (typeof MutationObserver !== 'undefined') {
      var viewObs = new MutationObserver(syncPostViews);
      viewObs.observe(document.body || document.documentElement, { childList: true, subtree: true });
    }
  })();
})();
