window.advScrollShortcuts = function(delta) {
  var b = document.getElementById("advBannerContent");
  if (b) {
    if (Math.abs(delta) < 25) {
      b.scrollLeft += delta;
    } else {
      b.scrollBy({ left: delta, behavior: "smooth" });
    }
  }
  var p = document.getElementById("advPillsRow");
  if (p && !b) p.scrollBy({ left: delta, behavior: "smooth" });
};

function initHorizontalSliding(el) {
  if (!el || el.dataset.slideBound === "1") return;
  el.dataset.slideBound = "1";
  el.style.cursor = "grab";

  // Fare Tekerleği ile Akıcı Yatay Kaydırma (Hem Dikey hem Yatay Wheel)
  el.addEventListener("wheel", function(e) {
    var d = Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : e.deltaY;
    if (d !== 0) {
      e.preventDefault();
      el.scrollLeft += d * 0.9;
    }
  }, { passive: false });

  // Fare ile Basılı Tutup Sürükleyerek Kaydırma (Mouse Drag-to-Scroll)
  var isDown = false, startX = 0, startY = 0, sLeft = 0, hasDragged = false;
  el.addEventListener("mousedown", function(e) {
    if (e.button !== 0) return;
    isDown = true;
    hasDragged = false;
    startX = e.pageX;
    startY = e.pageY;
    sLeft = el.scrollLeft;
    el.style.cursor = "grabbing";
  });

  window.addEventListener("mousemove", function(e) {
    if (!isDown) return;
    var dx = e.pageX - startX;
    var dy = e.pageY - startY;
    if (Math.abs(dx) > 4) {
      hasDragged = true;
      el.scrollLeft = sLeft - dx * 1.35;
    }
  });

  window.addEventListener("mouseup", function(e) {
    if (!isDown) return;
    isDown = false;
    el.style.cursor = "grab";
    if (hasDragged) {
      var captureClick = function(ev) {
        ev.preventDefault();
        ev.stopPropagation();
        window.removeEventListener("click", captureClick, true);
      };
      window.addEventListener("click", captureClick, true);
      setTimeout(function() {
        window.removeEventListener("click", captureClick, true);
      }, 50);
    }
  });
}

function bindSearchSliders() {
  initHorizontalSliding(document.getElementById("advBannerContent"));
  initHorizontalSliding(document.getElementById("advSearchBanner"));
  initHorizontalSliding(document.getElementById("advPillsRow"));
  initHorizontalSliding(document.getElementById("bttSlashRow"));
}
setTimeout(bindSearchSliders, 200);

  var SHORTCUTS = {
