  };

  function calcMath(q) {
    if (!/^[\d\s+\-*/().%]+$/.test(q)) return null;
    if (!/[+\-*/%]/.test(q)) return null;
    try {
      var fn = new Function('"use strict"; return (' + q + ')');
      var res = fn();
      return (typeof res === 'number' && isFinite(res)) ? res : null;
    } catch (e) {
      return null;
    }
  }

  var blogPosts = null;
  var isFetchingPosts = false;

  function extractPostsFromDOM() {
    var links = document.querySelectorAll('.blogP .entry-title a, .featured-title a, .pms-title a, article a[href*=".html"], .entry-title a, .wL a[href*=".html"], .ticker-item a');
    var seen = {};
    var list = [];
    links.forEach(function(a) {
      var href = a.getAttribute('href') || '';
      var text = (a.textContent || '').trim();
      if (href && text && !seen[href] && href.indexOf('#') !== 0 && href.indexOf('javascript:') !== 0) {
        seen[href] = true;
        list.push({ title: text, url: href, categories: ['Blog'] });
      }
    });
    return list;
  }

  function loadBlogPosts() {
    if (!blogPosts || blogPosts.length === 0) {
      try {
        var cached = sessionStorage.getItem('__NS_POSTS_CACHE__');
        if (cached) {
          blogPosts = JSON.parse(cached);
        }
      } catch (e) {}
    }

    if (!blogPosts || blogPosts.length === 0) {
      var domPosts = extractPostsFromDOM();
      if (domPosts.length > 0) {
        blogPosts = domPosts;
      }
    }

    if (isFetchingPosts) return;
    isFetchingPosts = true;
    fetch('/feeds/posts/summary?alt=json&max-results=150')
      .then(function(res) { return res.json(); })
      .then(function(data) {
        var entries = (data && data.feed && data.feed.entry) ? data.feed.entry : [];
        if (entries.length > 0) {
          blogPosts = entries.map(function(item) {
            var title = (item.title && item.title.$t) ? item.title.$t : '';
            var href = '';
            if (item.link) {
              for (var i = 0; i < item.link.length; i++) {
                if (item.link[i].rel === 'alternate') {
                  href = item.link[i].href;
                  break;
                }
              }
            }
            var cats = [];
            if (item.category) {
              cats = item.category.map(function(c) { return c.term || ''; }).filter(Boolean);
            }
            return { title: title, url: href, categories: cats };
          });
          try {
            sessionStorage.setItem('__NS_POSTS_CACHE__', JSON.stringify(blogPosts));
          } catch (e) {}
        }
        var m = document.getElementById('advSearchModal');
        if (m && m.classList.contains('is-open')) {
          renderState();
        }
      })
      .catch(function() {
        if (!blogPosts) blogPosts = [];
      });
  }

  function initAdvSearch() {
    var modalEl = document.getElementById('advSearchModal');
    var inputEl = document.getElementById('advSearchInput');
    var selectEl = document.getElementById('advSearchSelect');
    var clearBtn = document.getElementById('advInputClear');
    var submitBtn = document.getElementById('advSearchSubmit');
    var closeBtn = document.getElementById('advCloseBtn');
    var bannerEl = document.getElementById('advSearchBanner');
    var bannerContentEl = document.getElementById('advBannerContent');
    var bannerKbdEl = document.getElementById('advBannerKbd') || (bannerEl ? bannerEl.querySelector('.adv-banner-kbd') : null);
    var resultsEl = document.getElementById('advSearchResults');
    var resultsCountEl = document.getElementById('advResultsCount');
    var resultsItemsEl = document.getElementById('advResultsItems');
    var pillsRowEl = document.getElementById('advPillsRow');

    if (!modalEl || !inputEl || !selectEl) return;

    var currentResults = [];
    var selectedIndex = -1;

    function renderDefaultBanner() {
      if (!bannerContentEl) return;
      bannerContentEl.innerHTML =
        '<span class="adv-banner-chip" data-prefix="tr " title="Google Çeviri">tr</span>' +
        '<span class="adv-banner-chip" data-prefix="deepl " title="DeepL Çeviri">deepl</span>' +
        '<span class="adv-banner-chip" data-prefix="ytr " title="Yandex Çeviri">ytr</span>' +
        '<span class="adv-banner-chip" data-prefix="ytm " title="YouTube Music üzerinde ara">ytm</span>' +
        '<span class="adv-banner-chip" data-prefix="kaynak " title="Google Kaynak Tercihleri">kaynak</span>' +
        '<span class="adv-banner-chip" data-prefix="yt " title="YouTube üzerinde ara">yt</span>' +
        '<span class="adv-banner-chip" data-prefix="gh " title="GitHub üzerinde ara">gh</span>' +
        '<span class="adv-banner-chip" data-prefix="wiki " title="Wikipedia üzerinde ara">wiki</span>' +
        '<span class="adv-banner-chip" data-prefix="ps " title="PageSpeed hız testi">ps</span>' +
        '<span class="adv-banner-chip" data-prefix="@" title="Kategoriye göre ara">@kategori</span>';
      if (bannerKbdEl) bannerKbdEl.innerHTML = 'Enter &#8629;';
      if (bannerEl) bannerEl.style.display = 'flex';
    }

    window.openAdvSearch = openAdvSearch;
    window.closeAdvSearch = closeAdvSearch;
    window.advNextResult = function() {
      if (currentResults.length > 0) {
        selectedIndex = Math.min(selectedIndex + 1, currentResults.length - 1);
        renderState();
        var sel = resultsItemsEl ? resultsItemsEl.querySelector('.is-selected') : null;
        if (sel) sel.scrollIntoView({ block: 'nearest' });
      }
    };
    window.advPrevResult = function() {
      if (currentResults.length > 0) {
        selectedIndex = Math.max(selectedIndex - 1, 0);
        renderState();
        var sel = resultsItemsEl ? resultsItemsEl.querySelector('.is-selected') : null;
        if (sel) sel.scrollIntoView({ block: 'nearest' });
      }
    };
    window.advNextPill = function() {
      if (selectEl && selectEl.options.length > 1) {
        selectEl.selectedIndex = (selectEl.selectedIndex + 1) % selectEl.options.length;
        updateActivePill(selectEl.value);
        renderState();
      }
    };
    window.advPrevPill = function() {
      if (selectEl && selectEl.options.length > 1) {
        selectEl.selectedIndex = (selectEl.selectedIndex - 1 + selectEl.options.length) % selectEl.options.length;
        updateActivePill(selectEl.value);
        renderState();
      }
    };
    window.advExecuteCurrent = function() {
      executeSearch();
    };

    function openAdvSearch(initialQuery) {
      modalEl.classList.add('is-open');
      document.body.style.overflow = 'hidden';
      loadBlogPosts();
      if (typeof initialQuery === 'string') {
        inputEl.value = initialQuery;
      }
      selectedIndex = -1;
      setTimeout(function() {
        inputEl.focus();
        inputEl.select();
      }, 50);
      renderState();
    }

    function closeAdvSearch() {
      modalEl.classList.remove('is-open');
      document.body.style.overflow = '';
      selectedIndex = -1;
    }

    function escapeHtml(str) {
      return (str || '').replace(/[&<>"']/g, function(m) {
        return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m];
      });
    }

    function updateActivePill(val) {
      if (!pillsRowEl) return;
      var pills = pillsRowEl.querySelectorAll('.adv-pill');
      pills.forEach(function(pill) {
        if (pill.getAttribute('data-url') === val) {
          pill.classList.add('is-active');
        } else {
          pill.classList.remove('is-active');
        }
      });
    }

    function renderState() {
      var raw = (inputEl.value || '').trim();
      if (clearBtn) clearBtn.style.display = raw ? 'flex' : 'none';

      var math = calcMath(raw);
      var parts = raw.split(/\s+/);
      var prefix = (parts[0] || '').toLowerCase().replace(/:$/, '');
      var hasShortcut = SHORTCUTS[prefix] && raw.length > parts[0].length;
      var isDirectUrl = /^(https?:\/\/|[\w-]+\.[a-z]{2,})(\/|$)/i.test(raw);

      // 1. Enter Bar (Kısayollar & Canlı Önizleme)
      if (bannerEl && bannerContentEl) {
        bannerEl.style.display = 'flex';
        if (math !== null) {
          bannerContentEl.innerHTML = '<span style="font-size:15px;">🧮</span><span>Hesap Sonucu: <strong>' + escapeHtml(raw) + ' = ' + math + '</strong></span>';
          if (bannerKbdEl) bannerKbdEl.innerHTML = 'Enter &#8629;';
        } else if (hasShortcut) {
          var sc = SHORTCUTS[prefix];
          var payload = raw.slice(parts[0].length).trim();
          bannerContentEl.innerHTML = '<span class="adv-banner-hint-label">' + escapeHtml(sc.label) + ':</span><span>&ldquo;<strong>' + escapeHtml(payload) + '</strong>&rdquo; üzerinde ara</span>';
          if (bannerKbdEl) bannerKbdEl.innerHTML = 'Enter &#8629;';
        } else if (isDirectUrl) {
          bannerContentEl.innerHTML = '<span style="font-size:14px;">🔗</span><span>Doğrudan Web Sitesine Git: <strong>' + escapeHtml(raw) + '</strong></span>';
          if (bannerKbdEl) bannerKbdEl.innerHTML = 'Git (Enter &#8629;)';
        } else if (selectedIndex >= 0 && currentResults[selectedIndex]) {
          bannerContentEl.innerHTML = '<span style="font-size:13px;">🚀</span><span>Yazıyı Aç: <strong>' + escapeHtml(currentResults[selectedIndex].title) + '</strong></span>';
          if (bannerKbdEl) bannerKbdEl.innerHTML = 'Aç (Enter &#8629;)';
        } else if (selectEl.value !== 'blog') {
          var opt = selectEl.options[selectEl.selectedIndex];
          var engName = opt ? opt.textContent : 'Arama Motoru';
          bannerContentEl.innerHTML = '<span class="adv-banner-hint-label">' + escapeHtml(engName) + ':</span><span>&ldquo;<strong>' + escapeHtml(raw || '...') + '</strong>&rdquo; ara</span>';
          if (bannerKbdEl) bannerKbdEl.innerHTML = 'Ara (Enter &#8629;)';
        } else if (!raw) {
          renderDefaultBanner();
        } else {
          bannerContentEl.innerHTML = '<span style="font-size:12.5px;">🔍 <strong>&ldquo;' + escapeHtml(raw) + '&rdquo;</strong> için ara veya aşağıdan yazı seçin</span>';
          if (bannerKbdEl) bannerKbdEl.innerHTML = 'Enter &#8629;';
        }
      }

      // 2. Sayfada Çekmecesi (Blog Yazıları Listesi)
      if (selectEl.value === 'blog') {
        resultsEl.style.display = 'flex';
        var matches = [];
        var isLatest = false;

        if (blogPosts && blogPosts.length > 0) {
          if (!raw) {
            matches = blogPosts.slice(0, 8);
            isLatest = true;
          } else if (raw.charAt(0) === '@') {
            var cat = raw.slice(1).trim().toLowerCase();
            matches = blogPosts.filter(function(p) {
              return p.categories && p.categories.some(function(c) {
                return c.toLowerCase().indexOf(cat) !== -1;
              });
            }).slice(0, 8);
          } else {
            var q = raw.toLowerCase();
            matches = blogPosts.filter(function(p) {
              var tMatch = p.title.toLowerCase().indexOf(q) !== -1;
              var uMatch = p.url.toLowerCase().indexOf(q) !== -1;
              var cMatch = p.categories && p.categories.some(function(c) {
                return c.toLowerCase().indexOf(q) !== -1;
              });
              return tMatch || uMatch || cMatch;
            }).slice(0, 8);
          }

          currentResults = matches;

          if (matches.length > 0) {
            resultsCountEl.innerHTML = isLatest
              ? '<span>📖 Son Eklenen Yazılar (' + matches.length + ')</span>'
              : '<span>🔍 Eşleşen Blog Yazıları (' + matches.length + ')</span>';

            resultsItemsEl.innerHTML = matches.map(function(item, idx) {
              var isSel = (idx === selectedIndex);
              var catBadge = (item.categories && item.categories.length > 0)
                ? ('<span class="adv-item-tag">' + escapeHtml(item.categories[0]) + '</span>')
                : '<span class="adv-item-tag">Blog</span>';
              var shortUrl = item.url.replace(/^https?:\/\/[^\/]+/, '') || 'Yazıyı Oku';
              return '<a class="adv-item' + (isSel ? ' is-selected' : '') + '" href="' + escapeHtml(item.url) + '" data-idx="' + idx + '">' +
                '<div class="adv-item-main">' +
                  '<span class="adv-item-icon">' +
                    '<svg class="line" viewBox="0 0 24 24"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>' +
                  '</span>' +
                  '<div class="adv-item-text">' +
                    '<div class="adv-item-title">' + escapeHtml(item.title) + '</div>' +
                    '<div class="adv-item-sub">' + escapeHtml(shortUrl) + '</div>' +
                  '</div>' +
                '</div>' +
                catBadge +
              '</a>';
            }).join('');
          } else {
            resultsCountEl.innerHTML = '<span>Eşleşen Sonuç Bulunamadı</span>';
            resultsItemsEl.innerHTML = '<div style="padding:14px;font-size:12px;color:#989b9f;text-align:center;">Sayfada eşleşen yazı bulunamadı. Enter tuşuna basarak genel arama yapabilirsiniz.</div>';
          }
        } else {
          resultsCountEl.innerHTML = '<span>Yazılar Yükleniyor...</span>';
          resultsItemsEl.innerHTML = '<div style="padding:14px;font-size:12px;color:#989b9f;text-align:center;">Sayfadaki yazılar hazırlanıyor...</div>';
        }
      } else {
        currentResults = [];
        resultsEl.style.display = 'none';
      }
    }

    function executeSearch(overrideUrl) {
      var raw = (inputEl.value || '').trim();
      if (!raw) {
        if (selectedIndex >= 0 && currentResults[selectedIndex]) {
          window.location.href = currentResults[selectedIndex].url;
          closeAdvSearch();
          return;
        }
        return;
      }

      var math = calcMath(raw);
      if (math !== null) {
        inputEl.value = raw + ' = ' + math;
        renderState();
        return;
      }

      var parts = raw.split(/\s+/);
      var prefix = (parts[0] || '').toLowerCase().replace(/:$/, '');
      var hasShortcut = SHORTCUTS[prefix] && raw.length > parts[0].length;
      if (hasShortcut) {
        var sc = SHORTCUTS[prefix];
        var payload = raw.slice(parts[0].length).trim();
        if (sc.url === 'blog') {
          window.location.href = '/search?q=' + encodeURIComponent(payload);
        } else {
          window.open(sc.url + encodeURIComponent(payload), '_blank', 'noopener,noreferrer');
        }
        closeAdvSearch();
        return;
      }

      var isDirectUrl = /^(https?:\/\/|[\w-]+\.[a-z]{2,})(\/|$)/i.test(raw);
      if (isDirectUrl) {
        var safe = /^https?:\/\//i.test(raw) ? raw : ('https://' + raw);
        window.open(safe, '_blank', 'noopener,noreferrer');
        closeAdvSearch();
        return;
      }

      if (selectedIndex >= 0 && currentResults[selectedIndex]) {
        window.location.href = currentResults[selectedIndex].url;
        closeAdvSearch();
        return;
      }

      var targetUrl = overrideUrl || selectEl.value;
      if (targetUrl === 'blog') {
        window.location.href = '/search?q=' + encodeURIComponent(raw);
      } else {
        window.open(targetUrl + encodeURIComponent(raw), '_blank', 'noopener,noreferrer');
      }
      closeAdvSearch();
    }

    inputEl.addEventListener('input', function() {
      selectedIndex = -1;
      renderState();
    });

    inputEl.addEventListener('keydown', function(e) {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        if (currentResults.length > 0) {
          selectedIndex = Math.min(selectedIndex + 1, currentResults.length - 1);
          renderState();
          var sel = resultsItemsEl.querySelector('.is-selected');
          if (sel) sel.scrollIntoView({ block: 'nearest' });
        }
        return;
      }

      if (e.key === 'ArrowUp') {
        e.preventDefault();
        if (currentResults.length > 0) {
          selectedIndex = Math.max(selectedIndex - 1, -1);
          renderState();
          var sel = resultsItemsEl.querySelector('.is-selected');
          if (sel) sel.scrollIntoView({ block: 'nearest' });
        }
        return;
      }

      // Klavye ile Kısayollar Şeridini Kaydırma (Alt+Ok veya İmleç Sınırındayken)
      if (e.key === 'ArrowLeft') {
        if (e.altKey || inputEl.selectionStart === 0) {
          e.preventDefault();
          if (window.advScrollShortcuts) window.advScrollShortcuts(-150);
        }
      } else if (e.key === 'ArrowRight') {
        if (e.altKey || inputEl.selectionStart === inputEl.value.length) {
          e.preventDefault();
          if (window.advScrollShortcuts) window.advScrollShortcuts(150);
        }
      }

      if (e.key === 'Enter') {
        e.preventDefault();
        if (selectedIndex >= 0 && currentResults[selectedIndex]) {
          window.location.href = currentResults[selectedIndex].url;
          closeAdvSearch();
          return;
        }
        executeSearch();
      }
    });

    // Modal Odaklıyken Klavye Sol / Sağ Ok Tuşlarıyla Kısayolları Kaydırabilme
    modalEl.addEventListener('keydown', function(e) {
      if (e.target !== inputEl) {
        if (e.key === 'ArrowLeft') {
          e.preventDefault();
          if (window.advScrollShortcuts) window.advScrollShortcuts(-150);
        } else if (e.key === 'ArrowRight') {
          e.preventDefault();
          if (window.advScrollShortcuts) window.advScrollShortcuts(150);
        }
      }
    });

    selectEl.addEventListener('change', function() {
      updateActivePill(selectEl.value);
      renderState();
      inputEl.focus();
    });

    if (pillsRowEl) {
      pillsRowEl.addEventListener('click', function(e) {
        var pill = e.target.closest('.adv-pill');
        if (!pill) return;
        var url = pill.getAttribute('data-url');
        selectEl.value = url;
        updateActivePill(url);
        var raw = (inputEl.value || '').trim();
        if (raw) {
          executeSearch(url);
        } else {
          renderState();
          inputEl.focus();
        }
      });
    }

    if (bannerContentEl) {
      bannerContentEl.addEventListener('click', function(e) {
        var chip = e.target.closest('.adv-banner-chip');
        if (!chip) return;
        var pref = chip.getAttribute('data-prefix') || '';
        inputEl.value = pref;
        inputEl.focus();
        selectedIndex = -1;
        renderState();
      });
    }

    if (clearBtn) {
      clearBtn.addEventListener('click', function() {
        inputEl.value = '';
        selectedIndex = -1;
        renderState();
        inputEl.focus();
      });
    }

    if (submitBtn) {
      submitBtn.addEventListener('click', function() {
        executeSearch();
      });
    }

    if (closeBtn) {
      closeBtn.addEventListener('click', function() {
        closeAdvSearch();
      });
    }

    modalEl.addEventListener('click', function(e) {
      if (e.target === modalEl) {
        closeAdvSearch();
      }
    });

    if (resultsItemsEl) {
      resultsItemsEl.addEventListener('mousemove', function(e) {
        var item = e.target.closest('.adv-item');
        if (item && item.dataset.idx !== undefined) {
          var idx = parseInt(item.dataset.idx, 10);
          if (selectedIndex !== idx) {
            selectedIndex = idx;
            var cur = resultsItemsEl.querySelector('.is-selected');
            if (cur) cur.classList.remove('is-selected');
            item.classList.add('is-selected');
          }
        }
      });
      resultsItemsEl.addEventListener('click', function(e) {
        var item = e.target.closest('.adv-item');
        if (item) {
          closeAdvSearch();
        }
      });
    }

    var pillTrigger = document.getElementById('pillSearchTrigger');
    if (pillTrigger) {
      pillTrigger.addEventListener('click', function(e) {
        e.preventDefault();
        openAdvSearch();
      });
    }

    // Global Klavye Kısayolları: Ctrl+K veya Ctrl+F ile arama modalını aç, Esc ile kapat
    document.addEventListener('keydown', function(e) {
      if ((e.ctrlKey || e.metaKey) && (e.key === 'k' || e.key === 'K' || e.key === 'f' || e.key === 'F')) {
        e.preventDefault();
        openAdvSearch();
      } else if (e.key === 'Escape' && modalEl.classList.contains('is-open')) {
        e.preventDefault();
        closeAdvSearch();
      }
    });

    var headSearchIcons = document.querySelectorAll('.headIc .isSrh, .headIc .tSrch, label[for="forSearch"]');
    headSearchIcons.forEach(function(ico) {
      ico.addEventListener('click', function(e) {
        e.preventDefault();
        e.stopPropagation();
        openAdvSearch();
      });
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initAdvSearch);
  } else {
    initAdvSearch();
  }
})();

/* #Sohbet & #İletişim Kapsül Slider Motoru */
(function() {
  function initSiSlider() {
    var bar = document.getElementById('sohbetIletisimBar');
    if (!bar || bar.dataset.siInit === '1') return;
    bar.dataset.siInit = '1';

    var slides = bar.querySelectorAll('.si-slide');
    var dots = bar.querySelectorAll('.si-slider-dots .dot');
    if (!slides.length) return;

    var cur = 0;
    var timer = null;

    function showSi(idx) {
      cur = (idx + slides.length) % slides.length;
      slides.forEach(function(s, i) {
        if (i === cur) {
          s.classList.add('active');
        } else {
          s.classList.remove('active');
        }
      });
      dots.forEach(function(d, i) {
        if (i === cur) {
          d.classList.add('active');
        } else {
          d.classList.remove('active');
        }
      });
    }

    function startAuto() {
      stopAuto();
      timer = setInterval(function() {
        showSi(cur + 1);
      }, 4500);
    }

    function stopAuto() {
      if (timer) { clearInterval(timer); timer = null; }
    }

    dots.forEach(function(d, i) {
      d.addEventListener('click', function(e) {
        e.preventDefault();
        e.stopPropagation();
        showSi(i);
        startAuto();
      });
    });

    bar.addEventListener('mouseenter', stopAuto);
    bar.addEventListener('mouseleave', startAuto);
    startAuto();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initSiSlider);
  } else {
    initSiSlider();
  }
})();
